L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "마지막으로 생략한 감사 인사: |cffffffff%s|r, %d초 전 (%s)"
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "이 프로필에서 꺼짐 -- 아무것도 기록하거나 띄우지 않음; /manners on"
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "알림창 잠금 해제됨 -- /manners lock 입력 전까지 아무에게도 버프를 주지 않음"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100%s까지 숨김|r -- 그때까지 알림창이 뜨지 않음; /manners snooze off 입력 시 종료"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100탈것 탑승 중|r -- 탈것 탑승 중 숨기기 옵션 때문에 내릴 때까지 알림창이 뜨지 않음"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 내 버프와, 나에게 버프를 주거나 요청한 사람만 뜸"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100마나 절약 중|r -- 마나가 %d%%로 회복될 때까지 나에게 버프를 주거나 요청한 사람만 뜸"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100전투 준비|r -- 전투가 시작될 때까지 내 파티나 공격대가 먼저 뜸"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100공격대 파티|r -- 공격대에서는 %s파티만 요청 없이 뜸"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100공격대 파티|r -- 모든 파티가 선택 해제되어 있어, 공격대에서는 아무도 요청 없이 뜨지 않음"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try 장전됨:|r %s -- 내용 없이 /manners try 입력 시 해제"
L["queue now: %d"] = "현재 대기열: %d"
L["queue if switched on: %d"] = "켰을 때 대기열: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners help|r 명령으로 전체 목록을 볼 수 있습니다."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "|cffffd100/manners %s|r 명령은 없습니다 -- 혹시 |cffffd100/manners %s|r 명령을 찾으셨나요? |cffffd100/manners dev|r 명령으로 시험 도구 목록을 볼 수 있습니다."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "고맙구먼, {name}! 대장간에 돌아가면 첫 잔은 내가 사지."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "신세 졌네, {name}. 이제 자넨 산의 친구일세."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "고맙구먼, {name}! 없어도 끄떡없었겠지만. 그래도 고맙네."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "고맙네, {name}! 한번 안아 주고 싶다만, 그럼 자네가 치유사 신세일세."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "벌써 갚았네, {name}. 내 평생 술값도 이리 빨리 갚아 본 적이 없구먼."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "썬더브루에선 자네가 내 목숨을 구했다고 떠벌릴 걸세, {name}. 고맙네!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "훌륭하네, {name}! 석상이라도 깎아 주고 싶지만, 이게 더 빠르지."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "티탄께서 돌로 빚은 이 가슴도 찡하구먼, {name}. 고맙네."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "고맙네, {name}. 내 자존심이 눈치채기 전에 얼른 갚아 두지."
L["Thank ye, {name}. Muradin says a debt left unpaid rusts. Here, before it does."] = "고맙네, {name}. 묵힌 빚은 녹이 슨다고 무라딘 님이 그러셨지. 옜네."
L["Thank ye, {name}. I'd give ye a ride on me ram, but he bites strangers. And me."] = "고맙네, {name}. 내 산양 좀 태워 주고 싶다만, 낯선 이를 물어. 나도 물고."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "이런 매너는 어디서 발굴했나, {name}? 탐험가 연맹이 탐내겠구먼. 고맙네!"
L["Thank ye, {name}. Me beard's on end. That's dwarven fer 'deeply touched'."] = "고맙네, {name}. 수염이 곤두섰구먼. 드워프 말로 '크게 감동했다'는 뜻일세."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "카즈 모단 절반을 캐 봤지만, {name}, 이런 노다지는 처음일세. 자네 몫이네."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "던 모로 눈보라 속 카라노스 벽난로 같구먼, {name}. 고맙네."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "와일드해머의 폭풍망치처럼 돌아왔네, {name}. 덜 아프긴 하지만."
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "아이언포지에 한번 오게, {name}. 울 엄니가 배 터지게 먹이실 걸세. 고맙네!"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "버릇처럼 화약부터 확인했네, {name}. 깨끗하구먼. 자, 자네 몫일세!"
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "암, {name}, 말만 하면 되지. 모루처럼 가만있어 보게."
L["Say no more, {name}. Stone and steel, here it comes."] = "두말하면 잔소리지, {name}. 돌과 강철의 힘, 받게!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "드워프한테 도움을 청하면 받긴 받네, {name}. 시끄럽게."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "좋아, {name}. 단단히 버티게. 난 뭘 하든 망치 휘두르듯 하니까."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "암, {name}. 덤으로 묻지도 않은 얘기까지 해 주지. 어디 보자..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{name}, 갓 뽑은 생맥주처럼 시원한 {buff} 한 잔일세."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "다 됐네, {name}. 드워프 솜씨라 쓸데없이 튼튼하고, 값싸고, 평생 보증일세."
L["Easy, {name}. Last favour I did was fix a gnome's tank. Cost me both eyebrows."] = "쉽지, {name}. 지난번엔 노움 전차 고쳐 주다 눈썹을 둘 다 잃었다네."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "암, {name}. 산악왕은 거절을 모르지. 난 동네 뒷산급이지만, 규칙은 같네."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "담금질까지 끝냈네, {name}. 아직 뜨거우니 조심하게."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "말 끝나기 전에 다 됐네, {name}. 드워프는 '부탁'을 바위 너머로도 듣지."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "암, {name}. 던 모로에선 얼른 도와야 하네. 안 그럼 둘 다 선 채로 얼지."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "암, {name}. 발끝부터 찌릿할 걸세. 그게 드워프 솜씨란 증거지."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "암, {name}. 거절하면 노움한테 부탁할 테고, 그럼 그게 다 내 책임 아닌가."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "옜네, {name}. 버티라고 주는 쪼끄만 선물일세. 나처럼 쪼끄맣지."
L["Off ye go, {name}, steady as the mountain."] = "가 보게, {name}. 산처럼 든든하게!"
L["Here, {name}. Ale's for after; this is for before."] = "옜네, {name}. 맥주는 싸운 뒤에, 이건 싸우기 전에."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "마그니 님은 대의를 위해 다이아몬드가 되셨지, {name}. 이건 보급형일세."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "자네 등 뒤는 드워프가 지키네, {name}. 뭐, 무릎 뒤지만. 비슷하지."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "트로그가 귀찮게 굴면, {name}, 드워프가 보냈다고 하게. 그리고 튀게."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "효과가 떨어지면, {name}, 한 대 쾅 치게. 우린 뭐든 그렇게 고치지."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "받게, {name}. 고집도 좀 나눠 주고 싶다만, 내 건 내가 다 쓰는 중일세."
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "웬디고 조심하게, {name}. 크고 털 많고 성질 고약하지. 나보다 배고플 뿐."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "받게, {name}. 우리 할아범은 곡괭이랑 이것만으로 전쟁을 세 번 치렀지."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "드워프제일세, {name}. 탄돌 교각에서 떨어뜨려도 멀쩡하지. 해 보진 말게."
L["Stonewrought Dam holds back all o' Loch Modan, {name}. This'll hold ye an hour."] = "모단 호수도 댐 하나가 막아 내지, {name}. 이건 자넬 한 시간 막아 주네."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "저습지에선 장화가 젖을 걸세, {name}. 그건 어쩔 수 없지. 나머진 막아 주네."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "광부의 철칙일세, {name}. 굴에 들 땐 등불, 동료, 그리고 이것."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "브란 브론즈비어드는 이것도 없이 탐험 가서 책을 세 권 썼네, {name}."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "산악대가 애용하는 걸세, {name}. 더 잘 오르진 못해도, 떨어질 때 덜 아프지."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "아이언포지 성문은 한 번도 무너진 적 없네, {name}. 자네도 그래야지. 받게."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "검은바위 산 사촌들이었으면 불부터 붙였을 걸세, {name}. 행운을 빈다고."
L["Stone and hammer keep ye, cousin {name}!"] = "돌과 망치가 자넬 지켜 주길, 사촌 {name}!"
L["Three Hammers, one round, cousin {name}!"] = "망치는 셋, 술잔은 하나일세, 사촌 {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "자네 사촌의 사촌이 내 사촌과 혼인했을걸, {name}. 산이 좁잖나."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "드워프가 둘이나 뭉쳤네, {name}. 앞길 막는 놈들만 불쌍하게 됐구먼."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "브론즈비어드, 와일드해머, 검은무쇠, 토석인, {name}. 한 식구에 의견은 넷."
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "우리 둘이면, {name}, 고집으로 산도 이기겠구먼."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "동족한테 이만큼도 안 했다간, {name}, 할머니가 무덤에서 뛰쳐나오실 걸세."
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "티탄께서 우릴 한 바위에서 깎으셨지, {name}. 그래서 머리가 이리 단단한가."
L["Proud o' ye, {name}. Don't let it go to yer head; no room under the helmet."] = "자랑스럽네, {name}. 우쭐하진 말게. 투구 속엔 그럴 자리가 없으니."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "내 뒤에 서게, {name}. 암, 아네. 좀 쭈그리게."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "자, {name}. 앞은 내가, 전리품은 자네가. 다툼은 그다음일세."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "내가 노래를 부르면, {name}, 싸움이 잘 풀린 걸세. 아니면 아주 망했거나."
L["Dwarves never leave a mate behind, {name}. Nor a keg. Mates first, mind."] = "드워프는 동료를 두고 가지 않네, {name}. 술통도. 물론 동료가 먼저지."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "수염 내밀게, {name}! 수염 없는 친구는 인상이라도 쓰게. 거의 비슷하네."
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "옆 바위를 두드려 봤네, {name}. 단단하구먼. 오늘 무너질 일은 없겠어."
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "내 배낭 근처엔 불 금지일세, {name}. 거의 화약이거든. 샌드위치 하나랑."
L["Dwarves don't retreat, {name}. Our legs aren't built fer it. So forward it is."] = "드워프는 후퇴를 모르네, {name}. 다리가 짧아 무리거든. 그러니 전진일세."
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "붙어 있게, {name}. 어두워지면 욕하는 소리를 따라오게. 그게 날세."
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "드워프는 어느 쪽이 아래인지 늘 안다네, {name}. 위는 자네가 알아서 하게."
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "돌로 된 건 뭐든, {name}, 내가 먼저 말 걸어 보겠네. 사촌일지도 모르니."
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "천장이 삐걱대면, {name}, 내가 알려 주지. 내가 조용해지면, 뛰게."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "좋은 아침일세, {name}! 맥주엔 아직 이르지. 거의. 이거부터 받게."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "화로와 함께 기상일세, {name}! 드워프의 하루는 망치와 이걸로 시작하지."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "이르다고, {name}? 무슨 소리. 광산은 두 시간 전에 열었네. 옜네."
L["Mornin', {name}. Me beard's still asleep. The rest o' me is ready."] = "좋은 아침일세, {name}. 수염은 아직 자고 있네. 나머진 준비됐고."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "좋은 아침일세, {name}. 죽, 파이프, 그리고 이것. 앞의 둘은 내 걸세."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "산양 놈들이 새벽부터 깨웠네, {name}. 나올 때까지 문을 들이받더군. 옜네."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "좋은 아침일세, {name}. 어젯밤 노래판 때문에 아직 귀가 울리네. 옜네."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "고맙소, {name}. 음유시인이 멋대로 지어내기 전에 내가 먼저 갚으리다."
L["Kindly done, {name}. Let no one say we forget a friend."] = "친절에 감사하오, {name}. 우린 친구를 잊지 않는다오."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "고맙소, {name}. 기사 작위라도 주고 싶지만, '허가가 필요하다'는구려."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "즉석에서 갚았소, {name}. 스톰윈드였다면 서류 세 장에 도장까지 필요했을 거요."
L["Thanks, {name}. I'd pay in gold, but Stormwind still owes the stonemasons."] = "고맙소, {name}. 금화로 갚고 싶지만, 스톰윈드가 아직 석공 조합에 빚이 있어서."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "신세 졌소, {name}. 어머니께서 그릇은 빈 채로 돌려주는 게 아니라 하셨소."
L["Thank you, {name}. Consider the scales balanced, by royal decree. Mine."] = "고맙소, {name}. 왕명으로 이 빚은 청산하오. 내가 내린 왕명이오."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "부끄럽구려, {name}. 내가 먼저 했어야 하는데. 이제라도 갚으리다."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "서부 몰락지대 스튜보다 든든하구려, {name}. 그 스튜에 울어 본 몸이오."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "고맙소, {name}. 듀간 원수께 보고하리다. 관심 없으시겠지만, 보고는 하리다."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "작업 완료, {name}! 할아버지가 이 말로 스톰윈드 절반을 지으셨소. 고맙소."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "레이크샤이어 다리가 완공돼야 이걸 잊겠소, {name}. 그러니 영영 못 잊소."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "쿨 티라스에선 친절은 다음 물때에 돌려보낸다오, {name}. 자, 보내오."
L["Thank you, {name}. Northshire's monks would be proud. Of you. They know me."] = "고맙소, {name}. 북녘골 수도사들이 뿌듯해하겠소. 나 말고. 날 잘 아시거든."
L["Not since Mum packed my Deadmines lunch, {name}, have I felt so looked after."] = "어머니가 죽음의 폐광 도시락 싸 주신 뒤로, {name}, 이런 챙김은 처음이오."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "회고록에 넣으리다, {name}. 9장: '모두가 다정했다'. 고맙소."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "돼지와 휘파람 선술집에서 건배하리다, {name}. 다음은 돼지, 그다음은 휘파람."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "물론이오, {name}. 가만히, 영웅다운 표정으로. 음유시인들이 좋아하오."
L["Right away, {name}. Keep your shield high."] = "당장 하리다, {name}. 방패를 높이 드시오."
L["More work? Gladly, {name}. It beats the lumber mill."] = "일감이오? 기꺼이, {name}. 제재소보단 낫소."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "물론이오, {name}. 인간은 돕기와 큰소리치기에 능하오. 이건 돕는 쪽이오."
L["Certainly, {name}. Humans are quick learners; I learned this one yesterday."] = "그러리다, {name}. 인간은 배우는 게 빠르오. 이것도 어제 배웠소."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "가만히 계시오, {name}. 영웅의 골짜기 석상처럼. 딱 어울리겠소."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "당장 하리다, {name}. 빛은 구하는 자를 돕소. 나도 돕소. 더 빨리."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "뱃사람 규칙이오, {name}. 누가 도와 달라 하면, 노를 젓는 거요. 받으시오."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "물론이오, {name}. 허리 펴시오. 옛 교관님이 어디선가 지켜보고 계시니."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "물론이오, {name}. 공손한 부탁은 그늘숲의 조용한 밤보다 귀하오."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "당장 하리다, {name}. 난 대주교 흉내를 낼 테니, 감동한 척해 주시오."
L["Step into the light, {name}. Not the Light; I just like to see my aim."] = "빛 속으로 오시오, {name}. 성스러운 쪽 말고, 조준 잘 되게 밝은 쪽."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "스톰윈드도 잿더미에서 다시 섰소, {name}. {buff} 하나쯤이야."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "물론이오, {name}. 지난번엔 서부 몰락지대 허수아비에게 해 줬소. 긴 얘기요."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "좋소, {name}. 쿨 티라스식 조건이오. 악수 한 번이면 뱃노래는 봐 드리지."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "갈 길이 멀다오, {name}. 길을 줄여 주진 못해도 도움은 될 거요."
L["Fair winds and following seas, {name}."] = "순풍과 잔잔한 바다가 함께하길, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "받으시오, {name}. 엘프는 수백 년간 베풀면 되지만, 난 한 오십 년뿐이오."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "작은 선물이오, {name}. 경비병들한텐 비밀이오. 다들 달라고 할 테니."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "받으시오, {name}. 코볼트가 물으면, 양초는 없다고 하시오."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "받으시오, {name}. 인간식 선물이오. 뜻은 좋고, 급히 만들었고, 의외로 튼튼하오."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "멀록 조심하시오, {name}. 받으시오. 놈들이 소풍을 어떻게 망치는지 봤소."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "모든 길엔 영웅이 필요하오, {name}. 오늘은 나인가 보오. 받으시오."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "해 지면 그늘숲엔 가지 마시오, {name}. 거긴 늘 해가 져 있소. 받으시오."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "붉은마루 놀은 못 박히지 않은 건 다 가져가오, {name}. 이건 못 박아 뒀소."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "들창코를 만나거든, {name}, 이것과 친구를 챙기시오. 주로 친구를."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "빛과 튼튼한 장화면 된다오, {name}. 이제 그중 하나는 갖췄소."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "스톰윈드 영웅은 다 친절 하나와 빌린 검 한 자루로 시작했소, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "받으시오, {name}. 데피아즈단도 이건 못 훔치오. 다른 건 다 훔쳐 봤지만."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "우서 경은 길 가는 낯선 이도 축복했소, {name}. 망치는 작아도 뜻은 같소."
L["Take this, {name}. It's a tradition. I just started it, but it's a tradition."] = "받으시오, {name}. 전통이오. 방금 시작했지만, 어쨌든 전통이오."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "엘윈 숲 늑대는 순해 보이오, {name}. 안 순하오. 받으시오."
L["Arathor's children stand together, {name}."] = "아라소르의 후예는 함께 서는 법이오, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "같은 인간이구려, {name}! 어서 점심 전에 왕국이나 하나 세웁시다."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "스톰윈드든 보랄러스든, {name}, 날씨 불평하는 건 매한가지요."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "인간끼리 하는 말인데, {name}. 왜 만날 우리한테만 일이 터지는지 나도 모르겠소."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "수명은 짧고 할 일은 많소, {name}. 우리 인간끼린 서로 도와야지."
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "스톰윈드 돌이든 쿨 티라스 참나무든, {name}, 우린 늘 예상보다 오래 버티오."
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "인간끼리 뭉칩시다, {name}. 다른 종족은 다 더 크거나, 늙었거나, 털이 많소."
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "우리 인간은 빵과 고집과 불운으로 세상 절반을 세웠소, {name}."
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "드워프들한텐 비밀이오, {name}. 선술집은 사실 인간이 발명했소."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "가까이 붙으시오, {name}. 인간은 늘 머릿수로 이겨 왔소."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "대형을 유지하시오, {name}. 대형은 없지만, 아무튼 유지하시오."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "작전을 짜 오리다, {name}. 그리고 다 같이 무시합시다."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "노래 속 영웅 곁엔 늘 동료가 있었소, {name}. 그들의 노래는 내가 부르리다."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "방패를 드시오, {name}. 스톰윈드는 행군은 가르쳐도 멈추는 법은 안 가르쳤소."
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "일이 틀어지면, {name}, 가장 가까운 여관에서 재집결하오. 인간 전술이오."
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "우리 깃발을 만들었소, {name}. 막대에 손수건이지만, 우리 거요."
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "횃불을 꺼뜨리지 마시오, {name}. 인간은 어둠 속에선 못 보고, 그게 싫소."
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "등은 서로 지켜 줍시다, {name}. 나머진 빛께서 보시오. 위에선 더 잘 보이니."
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "인간은 위기 앞에서 늘 일어서오, {name}. 대개 거기 걸려 넘어진 다음에."
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "잘해 봅시다, {name}. 어느 엘프가 천 년은 두고두고 얘기할 테니."
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "농부, 뱃사람, 빵집 주인. {name}, 스톰윈드 군대는 늘 그랬소. 전진!"
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. 당일에 갚다니, 칼도레이로선 서두른 셈이오."
L["Thank you, {name}. Elune smiles on the generous."] = "감사하오, {name}. 엘룬께선 베푸는 이에게 미소 지으신다오."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "감사하오, {name}. 좀처럼 감동 않는 위습들마저 더 밝게 빛나는구려."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "엘룬께서 보셨소, {name}. 다 보시는 분이니, 얼른 갚아야겠소."
L["Thank you, {name}. Returned before I nap for a century or two."] = "감사하오, {name}. 한 이백 년 낮잠 들기 전에 갚아 두리다."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "감사하오, {name}. 고대정령들 귀에도 들어갈 거요. 소문을 워낙 좋아해서."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "감사하오, {name}. 파수대에 그대를 그만 겨누라 일러 두리다."
L["My people never hurry, {name}. For you, an exception."] = "우리 종족은 서두르는 법이 없소, {name}. 그대만은 예외요."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil, {name}. 그대의 근심도 덜어지기를. 방금 내 근심이 덜어졌듯."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "하이잘에서 불멸을 내려놓았소, {name}. 그 뒤로 친절의 값이 곱절이 되었지."
L["My ears went a darker purple, {name}. On a kaldorei, that means I'm touched."] = "귀가 더 짙은 보라색이 됐구려, {name}. 칼도레이에겐 감동했다는 뜻이오."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "아즈샤라의 궁정도 거저 준 건 없었소, {name}. 그대가 여왕보다 낫구려."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "부엉이들이 고개를 돌렸소, {name}. 한 바퀴 다. 최고의 찬사요."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "세계가 쪼개질 때도 버텼지만, {name}, 그대에게 진 빚은 못 버티겠소."
L["All those centuries of memories, {name}, and this one goes near the front."] = "수천 년 치 기억 가운데서도, {name}, 이건 맨 앞줄에 두리다."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "오늘 밤 달에게 그대 얘기를 하리다, {name}. 좋은 이야기를 좋아하시니."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "기꺼이, {name}. 가만히, 달빛이 그대에게 닿도록."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "물론이지요, {name}. 엘룬의 축복은 나누라고 있는 것이니."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "드디어, {name}! 누가 청해 주길 만 년이나 기다렸소."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "수수께끼도, 엘룬의 계시도 없소, {name}. 이번만은 그저 '그러겠소'."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "물론이오, {name}. 다음엔 다르나서스어로 청하면 절까지 해 드리리다."
L["Elune already said yes, {name}. I'm merely catching up."] = "엘룬께선 이미 허락하셨소, {name}. 난 뒤따를 뿐이오."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "물론이오, {name}. 가만히, 나무인 척하시오. 도움이 되오."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "밝은 데로 오시오, {name}. 지난번 칼도레이는 그림자 숨기를 써 버렸소."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "물론이오, {name}. 칼도레이에게 뭐든 물어도 좋소. 나이만 빼고."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "다르나서스에선, {name}, 달의 샘과 여사제가 필요하오. 여기선 나면 되오."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "지난번엔 악마와 싸우던 군대가 청했소, {name}. 그대가 더 공손하구려."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "기꺼이, {name}. 엘룬께 빌린 셈 치시오. 한 번도 받아 가신 적은 없소."
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "잠시만, {name}. 내 머리칼은 웬만한 왕국보다 오래돼서 잘 엉키오."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "다르나서스어엔 '예'가 아홉 가지요, {name}. 여덟은 생략하리다."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "물론이오, {name}. 파수대라면 암호를 물었겠지만, 난 '부탁하오'면 되오."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. 사뿐히 걸으시오. 나무들은 잠귀가 밝으니."
L["May the forest shelter you, {name}, wherever you roam."] = "{name}, 어디를 가든 숲이 그대를 품어 주기를."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "그림자 속에서 주는 선물이오, {name}. 아니, 찾지 마시오. 못 찾을 테니."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "엘룬께서 그대의 길을 비추시오, {name}. 난 등불만 들었을 뿐."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "부엉이들이 그대를 콕 집었소, {name}. 안목 까다로운 녀석들이오. 받으시오."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "티란데 님이라면 꼭 주라 하셨을 거요, {name}. 그분께 토 다는 자는 없지."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "받으시오, {name}. 지난번엔 히포그리프에게 줬는데, 그놈은 고마운 줄 모르더군."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "짐승들을 조심하시오, {name}. 절반은 드루이드고, 전부 지켜보고 있소."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "엘룬과 함께 걸으시오, {name}. 바쁘시다면 이것과 함께."
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "사티로스를 조심하시오, {name}. 원래 명가였소. 비웃는 얼굴 보면 티가 나지."
L["I've watched you from the treeline a while, {name}. Supportively. Here."] = "숲 가장자리에서 한참 지켜봤소, {name}. 응원하는 마음으로. 받으시오."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "펄볼그는 대개 우호적이오, {name}. 이건 나머지를 위한 거요."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "달의 샘물이면 더 좋겠지만, {name}, 들고 다니기가 어렵소. 이건 쉽지."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "텔드랏실에서 온 선물이오, {name}. 내려오는 길이 길어 떨어뜨릴 뻔했소."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "칼도레이 수다는 다음 보름달까지 가니, {name}, 이만 받으시오."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas, {name}. 싸울 준비를 하라는 뜻이오. 자, 이제 준비됐소."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "칼도레이와 달과 아주 오래된 나무가 드리오, {name}. 주로 내가."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. 엘룬께선 자녀들을 늘 곁에 두시지요."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "당연히 보였소, {name}. 칼도레이는 칼도레이가 알아보는 법."
L["One kaldorei to another, {name}: we lost a tree, never each other."] = "칼도레이끼리 하는 말이오, {name}. 나무는 잃어도 서로는 잃지 않았소."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "칼도레이는 동족을 어둠 속에 두지 않소, {name}. 숨으려는 게 아니라면."
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "칼도레이가 둘인데, {name}, 우리 귀에 맞는 투구는 여전히 없구려."
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "파수병, 드루이드, 아니면 그냥 고집쟁이요, {name}? 난 좋은 밤엔 셋 다요."
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "우리 둘이면, {name}, 이만 년 동안 '그거 해 봤소' 소리만 한 셈이구려."
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "언제 같이 그림자 숨기를 써 봅시다, {name}. 누가 알아채나 보게."
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "우리 샨도께선 꿈속에 잠드셨소, {name}. 깨어나실 보람이 있게 합시다."
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "우리 종족은 땅 위엔 드물지만, {name}, 나무 위엔 수두룩하오."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "금방 끝내자고, {name}? 칼도레이 셈법으론 시작 전에 끝난 셈이오."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "난 안 보이는 쪽을 맡으리다, {name}. 실수가 아니라 작전이오."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "엘룬께서 파티 전체를 지켜보시오, {name}. 난 손 흔드는 담당이고."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "만 년 동안 동료를 겪어 봤소, {name}. 그대들은 꽤 상위권이오."
L["Stay close, {name}. We kaldorei misplaced two World Trees. Not you, though."] = "곁에 있으시오, {name}. 우린 세계수를 둘이나 잃었소. 그대는 안 잃으리다."
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "내가 쓰러져도, {name}, 걱정 마시오. 위습이 되어 현명한 척 떠다닐 테니."
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "넬타리온과 함께 싸운 적이 있소, {name}. 그대가 벌써 더 나은 동료구려."
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "따라오시오, {name}. 이 길은 내가 아오. 지난번엔 숲이었지만."
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "우리가 진다 해도, {name}, 그대는 몇천 년쯤 좋게 기억하리다."
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "수천 년간 영웅들의 눈먼 돌격을 봤소, {name}. 우린 눈 뜨고 해 봅시다."
L["If anyone asks, {name}, we were always this good. I'll swear to it for ages."] = "누가 묻거든, {name}, 우린 원래 이렇게 잘했소. 몇 세기든 내가 증언하리다."
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "첫 불침번은 내가 서리다, {name}. 둘째도. 칼도레이에게 하룻밤은 잠깐이오."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "달이 떴소, {name}. 칼도레이에겐 지금이 한창 아침이오."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "멀쩡한 이들은 다 잠들었소, {name}. 엘룬과 나는 이 편이 좋소."
L["Moonlight suits you, {name}. This is merely a second layer."] = "달빛이 잘 어울리는구려, {name}. 이건 한 겹 더 입혀 드리는 것뿐."
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "드디어 어둡구려, {name}. 이제 난 다 보이고, 나머지는 짐작해야 하오."
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "만 년 전에 본 그 별들이오, {name}. 나보다 곱게 늙었구려."
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "달이 뜨오, {name}. 칼도레이는 다들 조금 깨어났고, 조금 으쓱해졌소."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "아침이구려, {name}. 우린 수천 년간 아침엔 잤소. 적응 중이오."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "새벽이오, {name}. 엘룬께서 주무시러 가셨으니 내가 대신하리다."
L["The sun's up, {name}, and so, reluctantly, am I."] = "해가 떴소, {name}. 나도 마지못해 일어났소."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "너무 눈부시오, {name}. 실눈 뜨고 버티리다. 엘룬께선 실눈도 용서하시니."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "동틀 녘이오, {name}. 나이트 엘프가 딱 눈에 띄는 시간이지. 어서 받으시오."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "일찍 일어났소, {name}? 난 늦게까지 깨어 있었소. 이걸로 중간에서 만납시다."
L["The shadows remember kindness, {name}. So do I."] = "그림자는 친절을 기억하지요, {name}. 저도 마찬가지고요."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "고마워요, {name}. 렌도레이는 받은 호의를 잊지 않아요."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "고마워요, {name}. 속삭임들까지 마음에 들어 하네요. 솔직히 좀 불안해요."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "고마워요, {name}. 이렇게 불길하게 빛나는데 선물이라니, 드문 일이에요."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "공허에선 친절이 귀해요, {name}. 공허가 눈치채기 전에 얼른 갚을게요."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "실버문은 우릴 쫓아냈죠, {name}. 이런 분들 덕에 아쉬울 게 없네요."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "고스란히 갚았어요, {name}. 살짝 보랏빛일 수 있어요. 정상이에요."
L["The Void only takes, {name}. I, however, give back."] = "공허는 빼앗기만 하죠, {name}. 하지만 저는 돌려드려요."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "고마워요, {name}. 속삭임이 조용해졌어요. 진심이었다는 증거죠."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "고마워요, {name}. 웃고 싶지만 제 미소는 섬뜩하대요. 상상으로 봐 줘요."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "갚았어요, {name}. 손은 차갑게, 마음은 따뜻하게. 렌도레이 한 줄 요약이죠."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "갚았어요, {name}. 두 번 들릴 수도 있어요. 요즘 제 주문은 메아리쳐요."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "공허는 금단의 지식을 주겠대요, {name}. 이쪽 선물이 훨씬 좋네요."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "알레리아 님은 공허도 다스릴 수 있대요, {name}. 친절이 더 쉽던데요."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "신세 졌어요, {name}. 다들 우릴 피해 가는데, 이렇게 주고 가시네요."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "고마워요, {name}. 제 그림자도 절했어요. 원래 안 그러는데. 반했나 봐요."
L["As you wish, {name}. The shadows answer kindly today."] = "원하는 대로, {name}. 오늘은 그림자도 순순히 응하네요."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "맡겨 둬요, {name}. 공허는 우리를 따르지, 그 반대가 아니에요."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "그럼요, {name}. 속삭임들이 하지 말래서, 고민할 것도 없어요."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "물론이죠, {name}. 공허로 살짝 간을 한 {buff} 하나요."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "물론이죠, {name}. 가만히요. 그림자가 낯을 가려서."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "기꺼이요, {name}. 렌도레이 예절이죠. 공허는 줄 서서 기다려요."
L["Asked so nicely, {name}? The Void never says please. Here."] = "이렇게 공손하게요, {name}? 공허는 부탁할 줄 모르거든요. 여기요."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "물론이죠, {name}. 밝은 데 서 주세요. 공허는 구석에서 딴생각을 하거든요."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "물론이죠, {name}. 공허가 왜냐길래 '예의'라 했더니, 아직도 갸웃해요."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "기꺼이요, {name}. 다들 우리한텐 '그만 좀 속삭여'밖에 부탁을 안 하거든요."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "좋아요, {name}. 저랑 말다툼 좀 끝내고요. 됐어요. 제가 이겼어요."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "그럼요, {name}. 균열 타고 건너갈 수도 있지만, 좀 과시 같아서요."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "질문했다가 추방당했죠, {name}. 대답은 꽤 안전하다더군요."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "물론이죠, {name}. 살짝 오싹하고 희미한 합창이 들려도 정상이에요."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "{name}, 그림자를 살짝 드릴게요. 안전해요. 대체로요."
L["Walk carefully in the dark places, {name}."] = "어둠 속에선 발밑을 조심해요, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "텔로그루스 균열에서 온 작은 선물이에요, {name}. 생각보다 깨끗해요."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "받아요, {name}. 촉수가 보여도 그냥 장식이에요."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "그림자들이 안부를 묻더군요, {name}. 매너 좀 지키라고 했어요."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "여기요, {name}. 공허엔 우리가 대신 들어갔으니, 안 가셔도 돼요."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "그림자를 살펴봤는데, {name}, 숨은 건 없네요. 그래도 받아요."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "엄브릭이 안부 전하래요, {name}. 그런 말은 안 했지만, 했을 거예요."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "받아요, {name}. 칭찬을 속삭일지도 몰라요. 못 들은 척해 줘요."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "여기요, {name}. 보기엔 불길해도 효과는 훌륭해요. 저처럼요."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "받아요, {name}. 공허가 더 나쁜 걸 준비했길래, 제가 가로챘어요."
L["If something in the dark whispers your name, {name}, relax. That was me. Here."] = "어둠 속에서 누가 이름을 속삭여도, {name}, 놀라지 마요. 저였어요. 여기요."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "여기요, {name}. 렌도레이가 반가운 깜짝선물이 될 일은 흔치 않거든요."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "쿠엘탈라스를 떠날 때 가진 건 어둠의 재주뿐이었죠, {name}. 그걸 드려요."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "여기요, {name}. 그림자한텐 고마워하지 마요. 뭘 바랄 테니. 저한테 해요."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "불길한 눈빛 한 번에 친절 한 번씩 갚기로 했거든요, {name}. 한참 밀렸어요."
L["We ren'dorei look after our own, {name}."] = "우리 렌도레이는 동족을 챙기죠, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "실버문만 손해죠, {name}. 우린 없어도 아주 잘 지내요."
L["Your whispers and mine should really meet sometime, {name}."] = "우리 속삭임들끼리 언제 한번 인사시켜요, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "렌도레이가 둘이나, {name}. 얼른 음울한 표정 지어요. 다들 기대하니까."
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "이 머리색은 우리끼리만 알죠, {name}. 한땐 금발이었어요. 아마도요."
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "결국 텔로그루스가 집 같더라고요, {name}. 외풍 심하고 아주 어두운 집."
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "렌도레이끼리니까요, {name}. 그쪽 속삭임은 뭐래요? 제 건 수프 타령이에요."
L["Stay close, {name}. The whispers are much quieter in company."] = "곁에 있어요, {name}. 함께 있으면 속삭임이 훨씬 조용해요."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "그림자가 명령하기 시작하면, {name}, 무시해요. 저도 보통 그래요."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "제 그림자 좀 봐 줘요, {name}. 싸움만 나면 딴 데로 새거든요."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "제가 보랏빛으로 빛나도, {name}, 신경 쓰지 마요. 의욕이 넘쳐서 그래요."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "렌도레이는 좋은 동료예요, {name}. 숨을 어둠을 직접 챙겨 오거든요."
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "제가 허공에 말을 걸어도, {name}, 괜찮아요. 허공이 대답하면 그땐 걱정해요."
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "일이 꼬이면 균열을 열게요, {name}. 아쉽게도 1인용이지만, 손은 흔들어 줄게요."
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "즐겨 봐요, {name}. 렌도레이는 두 번 초대받는 일이 드물거든요."
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "등불은 켜 둬요, {name}. 전 필요 없는데, 그래야 그림자들이 얌전하거든요."
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "구석을 잘 봐요, {name}. 구석에 있는 건 제가 볼게요."
L["The Void promised me power, {name}. It never mentioned company this good."] = "공허는 힘을 약속했죠, {name}. 이렇게 좋은 동료 얘긴 없었는데."
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "싸우다 속삭임이 들리면, {name}, 응원이에요. 아마 우리 편이요."
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "뭔가 기괴한 게 나타나면, {name}, 제가 말 걸어 볼게요. 조금 할 줄 알거든요."
L["Night suits the ren'dorei, {name}. We match the decor."] = "밤은 렌도레이와 잘 어울려요, {name}. 인테리어랑 깔맞춤이죠."
L["The shadows are longest now, {name}, and in a very generous mood."] = "지금 그림자가 가장 길어요, {name}. 마음씨도 가장 넉넉하고요."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "늦었냐고요, {name}? 속삭임은 밤늦게 수다스러워지죠. 요즘은 저도요."
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "자정이에요, {name}. 제 그림자랑 제 의견이 맞는 유일한 시간이죠."
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "별이 떴네요, {name}. 별 사이에 뭐가 있는지 봤는데, 별이 낫더라고요."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "고마워요, {name}님! 호의 수신, 분류, 반송 완료!"
L["Reciprocity engaged! Much obliged, {name}."] = "상호 호혜 모드 가동! 감사해요, {name}님."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "계산해 보니, {name}님께 정확히 {buff} 하나를 드려야 하네요."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "고마워요, {name}님! 감사 기계를 만들어 드리고 싶지만, 터질 거예요."
L["Thank you, {name}! This calls for a celebration. Stand back, I'll build one."] = "고마워요, {name}님! 축하해야겠어요. 물러서세요, 하나 조립할게요."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "너무 친절하세요, {name}님! 보답하는 데 설계도 네 장밖에 안 들었어요."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "이런, {name}님! '고마움'을 발명하려던 참인데 선수를 치셨네요."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "어머, {name}님, 친절하셔라! 심장이 또 윙윙 돌아가요."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "연구 일지 400쪽에 적었어요, {name}님. '사람들은 다정하다'."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "멋져요, {name}님! 바로 돌려드릴게요. 개조하고 싶어지기 전에요."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "고마워요, {name}님! 친절은 가역 반응이에요. 확인했어요. 여기요."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "제 기계타조도 경례하고 싶겠지만, {name}님, 걔는 넘어지는 것밖에 몰라요."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "순간이동기로 보냈으면 가젯잔에 갔을 거예요, {name}님. 그래서 직접 배달!"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "어머, 고마워요, {name}님! 트로그 사태 이후로 이렇게 좋긴 처음이에요."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "다음 발명품엔 {name}님 이름을 붙일게요! 아주 작은 대포예요."
L["Thanks, {name}! Mind the whistle; that's just my gratitude valve venting."] = "고마워요, {name}님! 삐 소리는 신경 끄세요. 감사 밸브가 김 빼는 거예요."
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "{name}님은 제 최애 목록에 올랐어요! 짧아요. 거의 태엽 장치지만."
L["Request received, {name}! Processing... done!"] = "요청 접수, {name}님! 처리 중... 끝!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "업그레이드 하나 나갑니다, {name}님! 보정할 테니 가만히!"
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "물론이죠, {name}님! 이거 하는 기계도 만들었는데, 박살 나서 손으로 할게요."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "그럼요, {name}님! X 표시에 서세요. X가 없네요. 아무 데나 서세요."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "바로 할게요, {name}님! 고글 착용! 필요는 없고, 그냥 좋아서요."
L["{buff}, {name}? Simple in theory AND practice. Suspicious!"] = "{buff} 말이죠, {name}님? 이론도 실전도 간단하다니. 수상해요!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "기꺼이요, {name}님! 손발이랑 눈썹은 멀찍이 떨어뜨리세요."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "바로 할게요, {name}님! 세 걸음 물러서세요. 넷. 다섯. 네, 완벽해요."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "기꺼이요, {name}님! 용수철 크기별 정리보다 재밌죠. 그것도 재밌지만요."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "탁월한 주문이에요, {name}님! 움직이는 부품이 없네요. 다음엔 달아 볼게요."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "일반형이요, 디럭스요, {name}님? 똑같아요. 디럭스가 있어 보이죠."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "나갑니다, {name}님! 작업대에서 갓 나와 따끈해요. 연기는 살짝만 나요."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "승인, {name}님! 도장 쾅, 서명 끝, '당연하죠' 폴더에 보관!"
L["Of course, {name}! Adjust the gyromatic... no, wait, that's the squirrel's."] = "물론이죠, {name}님! 자이로매틱을 조정하고... 아, 그건 다람쥐 거네요."
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "노움은 문제를 거절 안 해요, {name}님. 가끔 일으키긴 하죠. 여기요!"
L["Hold still, {name}, this is perfectly safe. Probably!"] = "가만히 계세요, {name}님. 완벽하게 안전해요. 아마도요!"
L["Science says you need this, {name}. Who am I to argue?"] = "과학이 필요하다잖아요, {name}님. 제가 어쩌겠어요?"
L["A small upgrade for you, {name}. No cogs required."] = "{name}님께 작은 업그레이드! 톱니바퀴는 필요 없어요."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "받으세요, {name}님. 여분 있어요. 전 뭐든 여분이 세 개씩 있거든요."
L["Try this, {name}! Version one had legs. Version two is much better."] = "써 보세요, {name}님! 1호기엔 다리가 달렸었는데, 2호기가 훨씬 나아요."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "대땜장이님이 천재성을 나누랬어요, {name}님. 샘플 드릴게요!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "놈리건이여 영원하라, {name}님! 이건 영원까진 아니지만 공짜예요."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "전 작아도, {name}님, 선물은 풀사이즈예요. 받으세요!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "걱정 마세요, {name}님! 닭한테 써 봤는데, 닭이 아주 신났어요."
L["Field test, {name}! You're the lucky volunteer. Everyone's a volunteer, really."] = "실전 테스트예요, {name}님! 자원해 주셨죠? 안 하셨어도 한 걸로 칠게요."
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "프리사이즈예요, {name}님. 노움부터 타우렌까지 재 봤죠. 타우렌이 잘 참더군요."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "받으세요, {name}님! 제 그물 발사기와 달리 이건 저한테 안 떨어져요."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "노움 만능칼은 재주가 열둘인데 다 어설퍼요, {name}님. 이건 하나를 잘하죠."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "트로그, 용의 불길, 과한 열정에 닿으면 A/S 불가예요, {name}님. 즐기세요!"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "소매엔 아무것도 없어요, {name}님! 음, 스패너랑 퓨즈 두 개. 수상한 건 없어요."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "여기요, {name}님! 작죠? 쐐기돌도 작은데, 뭘 떠받치는지 보세요."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "원리를 설명드리고 싶지만, {name}님, 사흘이랑 칠판이 필요해요."
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "째깍 소리가 나면, {name}님, 제 회중시계예요. 거의 확실히요."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "놈리건을 위하여, {name}님! 눈높이 맞는 상대라 반가워요."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "노움 동지네요, {name}님! 설계도는 제가 들게요, 양동이는 부탁해요."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "살이든 톱니든, {name}님, 우린 다 노움이에요. 기름칠이 필요할 뿐."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "노움끼리 묻는 건데요, {name}님. 원자로는 끄고 오셨죠?"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "노움 둘이네요, {name}님! 목말 타면 나이트 엘프 키 거의 나와요."
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "서로 검산해 드려요, {name}님. 그리고 둘 다 속으로 삐지죠."
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "톱니바퀴 하나 아직 안 갚으셨죠, {name}님? 노움은 다 저한테 하나씩 빚졌어요."
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "언젠가, {name}님, 같이 놈리건에 돌아가요. 불 켜고요."
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "노움끼리 말인데요, {name}님. 터질 거 알죠? 우리 둘 다 구경하고 싶잖아요."
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "뭔가 거대한 걸 만들까요, {name}님? 키 큰 분들 표정 보려고요."
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "파티 전체 보정 완료예요, {name}님! 반짝이는 건 아무도 만지지 마세요."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "계산해 봤는데요, {name}님. 우리가 이겨요. 반올림했지만요."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "제가 '앉아!' 하면, {name}님, 의자 찾지 마세요. 지난번에 큰일 났어요."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "대형은요, {name}님. 키 큰 분들은 앞, 저는 안전하고 똑똑한 어딘가."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "하나씩 다 드려요, {name}님! 좋은 기계의 비결은 표준 부품이죠."
L["My plan, {name}: step one, survive. Step two is still in development."] = "제 계획은요, {name}님. 1단계, 살아남기. 2단계는 아직 개발 중이에요."
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "당황 마세요, {name}님. 뭐가 잘못돼도 해결할 장치가 나와요. 다음 주에."
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "제가 안 보이면, {name}님, 가까운 신발 밑을 보세요. 정중히 여쭤보고요."
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "끝나면, {name}님, 샘플 채취할래요. 전부 다요. 큰 놈부터."
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "오늘 폭발은 전부 의도한 거예요, {name}님. 어느 건지는 나중에 정할게요."
L["Group trial under way, {name}! No control group. Everybody gets the good stuff."] = "단체 임상 시험 시작, {name}님! 대조군은 없어요. 전원 진짜 약이에요."
L["If we get separated, {name}, follow the smoke. It'll be me."] = "흩어지면, {name}님, 연기를 따라오세요. 그게 저예요."
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "다들 손가락 잘 챙기세요, {name}님. 세어 뒀어요. 끝나고 또 셀 거예요."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "좋은 아침, {name}님! 세 시부터 깼어요. 토스터에 엔진 새로 다느라."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "좋은 아침이에요, {name}님! 커피가 혼자 내려져요. 스스로 터득했대요. 불안해요."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "일찍 시작하시네요, {name}님! 좋은 아이디어는 아침 전에 와요. 폭발도요."
L["Morning, {name}! My alarm clock went off at six. Exploded, I mean. Effective!"] = "좋은 아침, {name}님! 알람이 여섯 시에 터졌어요. 진짜로요. 효과 만점!"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "일찍 나오셨네요, {name}님? 더 좋은 톱니바퀴 꿈을 꿔서 못 참았어요. 여기요!"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "좋은 아침, {name}님! 오늘 해가 좀 흐리네요. 고쳐야지 하던 참이에요."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "빛은 친절에 보답합니다, {name}. 저는 가장 빠른 배달부일 뿐이지요."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. 받은 선물을 돌려드립니다."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "감사합니다, {name}. 엑소다르에 태워 드리고 싶지만, 착륙하는 꼴을 보셨지요."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "아낌없는 선물이군요, {name}. 나루의 노래가 조금 커졌습니다. 보답하지요."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "고맙습니다, {name}. 아르거스였다면 수정에 새겼을 겁니다. 받으십시오."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "수많은 세계를 떠돌았지만, {name}, 친절만은 배울 필요 없는 언어였습니다."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "이런 친절이라니, {name}. 군단 일이 거의 잊힐 정도입니다. 거의요."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "감사합니다, {name}. 드레나이어로 하면 11분이 걸려서요."
L["Thank you, {name}. The Exodar crashed; my manners didn't. Here."] = "감사합니다, {name}. 엑소다르는 추락했어도 예의는 추락하지 않았지요."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "살게라스도 선물을 내밀었지요, {name}. 우린 도망쳤고요. 이건 받겠습니다."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "감사합니다, {name}. 악마는 별 너머로 피했어도 빚은 피한 적이 없습니다."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "감사합니다, {name}. 기도 목록에 올리지요. 아르거스 때부터 이어진 목록입니다."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "군단은 우리 세계를 앗아 갔지요, {name}. 그대 같은 이들이 조금씩 돌려줍니다."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "먼저 베푸셨군요, {name}. 예언자는 징조라 하겠지만, 저는 예의라 부르지요."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "빛이 안부를 전합니다, {name}. '잘하셨다'고 꼭 덧붙이랍니다."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "물론입니다, {name}. 나루께선 길을, 저는 발걸음을 가볍게."
L["Gladly, {name}. The Light answers those who ask."] = "기꺼이, {name}. 빛은 구하는 이에게 응답합니다."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "벨렌께선 청하실 걸 예견하셨지요, {name}. 저는 승낙을 예견했고요."
L["The Light is not rationed, {name}. Take as much as you like."] = "빛은 배급제가 아닙니다, {name}. 마음껏 받으십시오."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "물론입니다, {name}. 불타는 군단한테서도 도망쳤는데, 이쯤이야."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "즉시 하지요, {name}. 발굽 고정, 수정 공명, 갑니다."
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "기꺼이요, {name}. 말하는 수정을 따라 별을 건넜는데, 이쯤은 쉽지요."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "물론입니다, {name}. 벨렌께 인내를 배웠지만, 다행히 이건 쓸 일이 없군요."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "기꺼이, {name}. 나루는 거절하지 않습니다. '흐으음' 하시는데, 그게 승낙이지요."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "엑소다르에선 수정 셋에 기도 하나가 필요했지요, {name}. 자, 기도 쪽입니다."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "물론입니다, {name}. 거절하는 건 악마뿐인데, 그들은 '부탁'을 통 안 하지요."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "기꺼이, {name}. 오래 떠돌아 봐서 청하기가 얼마나 어려운지 압니다."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "물론입니다, {name}. 우린 벗을 찾아 별을 건넜지요. 하나 찾았군요."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "드레나이에게 청하면요, {name}. 승낙 하나, 축복 하나, 어쩌면 역사 강의."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오. 안 되면 대비라도 하고."
L["Walk in the Light, {name}. May it shelter you always."] = "빛 속을 걸으십시오, {name}. 빛이 늘 그대를 지켜 주기를."
L["Take this, {name}. My people always travel Light."] = "받으십시오, {name}. 우린 가진 게 빛뿐이라 짐이 늘 가볍지요."
L["Take this, {name}. The Legion is always coming. I'd know."] = "받으십시오, {name}. 군단은 늘 옵니다. 제가 잘 알지요."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "오늘치 기적은 다 썼습니다, {name}. 대신 {buff}, 괜찮겠습니까?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "가는 길에 쓰십시오, {name}. 제 길은 2만 5천 년째입니다."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "나루의 축복입니다, {name}. 음, 나루 옆에 서 있었지요. 그것도 치는 겁니다."
L["Take this, {name}. It glows a bit. Everything we own does."] = "받으십시오, {name}. 좀 빛납니다. 우리 물건은 다 그렇지요."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "받으십시오, {name}. 드레나이는 늘 종말 대비 짐을 쌉니다. 연습을 좀 했지요."
L["Take this, {name}. I've stayed a step ahead of demons for ages. Now you're two."] = "받으십시오, {name}. 전 늘 악마보다 한 걸음 앞섰지요. 이제 그대는 두 걸음."
L["The naaru shine on all, {name}. They're dreadful at aiming. I'm helping."] = "나루는 만인을 비추지요, {name}. 조준이 영 형편없으셔서 제가 돕습니다."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "하늘안개 섬에서 낯선 이가 빵을 나눠 줬지요, {name}. 아직 갚는 중입니다."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "벨렌께선 천 가지 미래를 보시지요, {name}. 전 하나만 봅니다. 든든해진 그대."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "핏빛안개 섬 개울물은 마시지 마십시오, {name}. 이건 받으시고요."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "타락 이전 에레다르의 마법입니다, {name}. 좋은 것만 챙겨 왔지요."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! 아르거스의 자손은 서로를 돌보지요."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "드레나이 둘이 만나는 곳이 곧 고향이지요, {name}. 오늘은 여기입니다."
L["Horns high, {name}. Two draenei, and nobody's mentioned the Legion. Progress."] = "뿔을 높이, {name}. 드레나이가 둘인데 아무도 군단 얘길 안 꺼냈군요. 발전입니다."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "꼬리를 세우십시오, {name}. 아르거스가 봐도 자랑스러운 망명이지요."
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "드레나이가 둘이군요, {name}. 합치면 걱정만 5만 년 가까이 했겠지요."
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "뿔, 발굽, 그리고 희망, {name}. 군단도 셋 다 못 고쳤지요."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "우린 벨렌의 자손이지요, {name}. 쫓겨났고, 희망차고, 지독히 예의 바른."
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "삼세번이라 했지요, {name}. 이번 세계는 제자리에 좀 있어 줘야 합니다."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "곁에 계십시오, {name}. 세계를 한 번 잃었으니, 이 파티만은 꼭 붙잡겠습니다."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "2만 5천 년을 도망쳤지요, {name}. 벗들과 걷는 게 훨씬 낫습니다."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "나루께선 이걸 동행이라 하시겠지요, {name}. 저는 행운이라 부릅니다."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "세계가 끝나는 것도 봤습니다, {name}. 앞에 뭐가 있든 걱정 없습니다."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "뭉쳐 다닙시다, {name}. 한데 모여 있어야 빛이 찾기 쉽지요."
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "가까이 계십시오, {name}. 드레나이는 급히 떠나는 데 아주 능하거든요."
L["We draenei take the long view, {name}. From up here, this fight is very short."] = "드레나이는 멀리 봅니다, {name}. 이 높이에서 보면 이 싸움은 아주 짧지요."
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "제가 앞장서지요, {name}. 지켜보는 놈들 눈엔 키 큰 낙천가가 보일 겁니다."
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "드레나이는 예언자를 따릅니다, {name}. 오늘은 그대를 따르는 걸로 족하지요."
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "엑소다르엔 수천이 탔지요, {name}. 그래도 이 작은 파티가 더 든든합니다."
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "어깨를 나란히, {name}. 제 어깨가 좀 높지만, 뜻은 같습니다."
L["A prayer for the party, {name}. The short one. The long one ends next age."] = "파티를 위한 기도입니다, {name}. 짧은 걸로요. 긴 건 다음 시대에 끝나거든요."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소. 내 코도 그렇고."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "고맙소, {name}. 감사의 마음과 회심의 울음소리를 바치오."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "고맙소, {name}. 늑대인간에게 꼬리가 있었다면 지금 흔들고 있을 거요."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "평생 친구가 생겼구려, {name}. 충성은 우리 특기라오."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "내 안의 짐승은 으르렁대라 하고, 길니아스인은 감사하라 하는군, {name}."
L["Much appreciated, {name}. I'd shake your hand, but, claws. Here instead."] = "고맙소, {name}. 악수하고 싶지만, 발톱이 있어서. 대신 이걸 받으시오."
L["We walled ourselves off for years, {name}. You make that look silly."] = "성벽 쌓고 숨어 산 세월이 우스워지는군, {name}. 그대 덕에."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "고맙소, {name}. 난롯가 자리를 드리리다. 제일 좋은 자리로."
L["Thank you, {name}. In return, I'll never chase your mount. Well, rarely."] = "고맙소, {name}. 보답으로 그대 탈것은 절대 안 쫓겠소. 뭐, 거의."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "보답하오, {name}. 점잖은 미소요. 송곳니가 보이거든 못 본 척하시오."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "고맙소, {name}. 모자라도 벗어 인사하고 싶은데, 요즘은 귀 때문에 안 맞소."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "고맙소, {name}. 다들 귀나 긁어 주고 무사하길 빌 뿐인데."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "보답하오, {name}. 길니아스인은 빚을 갚고, 늑대인간은 전력 질주로 갚소."
L["Spoiled twice today, {name}, and the first time was a biscuit. Thank you."] = "오늘 두 번째 호강이오, {name}. 첫 번째는 비스킷이었소. 고맙소."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "그러리다, {name}. 가만히 계시오. 물지 않소. 세게는."
L["Right you are, {name}. Stand steady now."] = "좋소, {name}. 자, 흔들리지 말고 서 계시오."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "바로 하리다, {name}. 자, '기다려.' 늘 해 보고 싶던 말이오."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "기꺼이, {name}. 비가 오든 해가 뜨든. 길니아스에선 늘 비지만."
L["Certainly, {name}. I'll try not to shed on you."] = "그러리다, {name}. 털 안 날리게 조심하겠소."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "말할 것 없소, {name}. 청하기로 마음먹기도 전에 이 귀가 들었소."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "물론이오, {name}. 지난번에 막대기 던진 녀석보다 훨씬 정중하구려."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "기꺼이, {name}. 2미터 늑대한테 부탁하는 이는 드물지. 아주 좋소."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "그러리다, {name}. 이 모습 그대로 하겠소. 다른 모습은 소란이 나서."
L["Tea first? No? Straight to business, {name}. How very un-Gilnean. Here."] = "차부터? 아니오? 바로 본론이군, {name}. 참 길니아스답지 않구려. 여기 있소."
L["Of course, {name}. Excuse the damp. Nothing smells quite like a wet worgen."] = "물론이오, {name}. 좀 젖어서 미안하오. 젖은 늑대인간 냄새는 각별하지."
L["Of course, {name}. I'll try not to sniff. I will fail, but I'll try."] = "물론이오, {name}. 킁킁대지 않게 애쓰겠소. 실패하겠지만, 애는 쓰겠소."
L["Of course, {name}. Anything but a bath."] = "물론이오, {name}. 목욕만 빼고 뭐든."
L["Stay off the moors after dark, {name}. Take this."] = "해 지면 황야엔 가지 마시오, {name}. 이걸 받으시오."
L["Keep your wits about you, {name}. Something is always hunting."] = "정신 바짝 차리시오, {name}. 늘 뭔가가 사냥 중이니."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "더 일찍 가져오려 했소, {name}. 뭘 좀 쫓느라 늦었지만."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "받으시오, {name}. 아니, 간식은 필요 없소. 음. 작은 거라면 몰라도."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "길니아스인은 늘 먼저 베푸오, {name}. 발톱은 그냥 옷차림의 일부요."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "길니아스 전통 비방이오, {name}. 감기, 우울, 웬만한 저주에 좋소. 내 건 빼고."
L["Run with this, {name}. Trust me, I know about running."] = "이걸 갖고 달리시오, {name}. 달리기라면 내가 좀 알지."
L["Fetched this for you, {name}. Don't make a thing of it."] = "물어 왔소, {name}. 호들갑 떨지 마시오."
L["Here, {name}. That's why I was following you. Honestly. I'll stop now."] = "받으시오, {name}. 그래서 따라다닌 거요. 정말이오. 이제 그만하겠소."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "받으시오, {name}. 어슬렁대는 것들이 다 나처럼 교육받진 않았으니."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "명문가 길니아스인이 드리오, {name}. 털은 새것이지만 예법은 오래됐소."
L["I thought of this in a dream, {name}. I was also chasing a rabbit. Here."] = "꿈에서 떠올렸소, {name}. 토끼도 쫓고 있었지만. 받으시오."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "리암이라면 '길니아스를 위하여!' 외쳤겠지, {name}. 난 그냥, 그대를 위하여."
L["Tal'doren's druids taught me to leash the beast, {name}. Now it fetches. Here."] = "탈도렌 드루이드 덕에 짐승을 길들였소, {name}. 이젠 물어 오기도 하오."
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "밖에선 조심하시오, {name}. 한 번 물려 본 사람이 하는 말이오."
L["Here, {name}. I'd leave it on your doorstep, but that frightens people."] = "받으시오, {name}. 문간에 두고 가려 했지만, 그러면 다들 기겁해서."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "받으시오, {name}. 외투라도 벗어 주고 싶지만, 이건 몸에 붙은 거라."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "받으시오, {name}. 고개는 들고, 털은 눕히고. 좌우명으로 삼을 만하오."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "저주보다 길니아스가 우릴 더 단단히 묶는다오, {name}."
L["No need to explain the ears to you, {name}."] = "그대에겐 이 귀를 설명할 필요가 없겠구려, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "털, 안개, 비, {name}. 셋 다 이해하는 건 길니아스인뿐이오."
L["Pack looks after pack, {name}. Always has."] = "무리는 무리를 챙기는 법이오, {name}. 늘 그래 왔소."
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "그대도 털이 이리 빠지오, {name}? 둘이 모으면 늑대인간 하나 더 짜겠소."
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "늑대인간이 둘이오, {name}. 어디선가 고양이 하나가 운수 사나운 날이겠군."
L["Honestly, {name}, do you ever forget which form you left home in?"] = "솔직히, {name}, 집 나설 때 무슨 모습이었는지 잊을 때 없소?"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "길니아스인끼리 하는 말이오, {name}. 우린 아제로스에서 가장 예의 바른 늑대요."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "무리 규칙이오, {name}. 아무도 떨어지지 말 것. 벼룩 얘기는 금지."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "다시 무리가 생겼구려, {name}. 이렇게 그리웠는지 몰랐소."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "위험 냄새는 내가 먼저 맡으리다, {name}. 저주의 유일한 장점이오."
L["If I howl, {name}, it's a battle cry. Probably. Don't look at me like that."] = "내가 울부짖으면, {name}, 함성이오. 아마도. 그런 눈으로 보지 마시오."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "앞장서시오, {name}. 난 네 발로 뛰겠소. 체면은 없어도 훨씬 빠르오."
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "내가 벽을 노려보면, {name}, 뒤에 뭔가 있는 거요. 아니면 그냥 벽이고."
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "그레이메인 성벽을 몇 년이나 지켰소, {name}. 그대와 지키는 전선은 휴가요."
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "끝나면, {name}, 제대로 된 차 한 잔. 그 전에, 제대로 된 물어뜯기."
L["If I limp back, {name}, I'll make big sad eyes. Don't fuss. I'm fine."] = "절뚝이며 오면, {name}, 불쌍한 눈을 할 거요. 호들갑은 마시오. 멀쩡하오."
L["Short rest? I'll curl up, {name}, after three turns. The turns aren't optional."] = "잠깐 쉬오? 세 바퀴 돌고 웅크리겠소, {name}. 도는 건 생략 불가요."
L["Stay together, {name}. I was a lone wolf once. Dreadful pay, nobody talks."] = "뭉쳐 다니시오, {name}. 외로운 늑대 해 봤소. 박봉에 말동무도 없소."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "또 밤이구려, {name}. 내가 가장 좋고도 가장 나쁠 때요. 이건 좋은 쪽이오."
L["Look at that moon, {name}. Don't mind me; I'm not howling. Much."] = "저 달 좀 보시오, {name}. 신경 쓰지 마시오. 안 울부짖소. 많이는."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "밤의 길니아스는 안개와 발소리뿐이었소, {name}. 요즘은 내가 그 발소리요."
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "길니아스의 통금은 해 질 녘이었소, {name}. 다 이유가 있었더군."
L["Something out there keeps rustling, {name}. I'm not going to look. I'm looking."] = "저기서 계속 부스럭대는군, {name}. 안 볼 거요. ...보고 있소."
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "해가 졌소, {name}. 귀는 쫑긋, 코는 킁킁, 예의는 반듯. 셋 중 둘이면 되오."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "좋은 아침이오, {name}. 더 일찍 일어났을 텐데, 난롯가 깔개가 너무 따뜻해서."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "아침부터 비 냄새가 나는군, {name}. 길니아스는 뭐든 비 냄새가 났지."
L["Up already, {name}? I've chased two rabbits. For exercise. Purely."] = "벌써 일어났소, {name}? 난 토끼 두 마리를 쫓았소. 운동 삼아. 순전히."
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "좋은 아침이오, {name}. 차, 토스트, 면도. 요즘은 면도가 좀 오래 걸리오."
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "좋은 아침이오, {name}. 새들이 날 깨우길래 나도 새들을 깨웠소. 공평하게."
L["Morning, {name}. The squirrels are taunting me. Quickly, before I'm distracted."] = "좋은 아침이오, {name}. 다람쥐들이 날 놀리는군. 어서, 정신 팔리기 전에."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! 명예로 갚는다!"
L["You give freely, {name}. I return the favour."] = "선뜻 베풀었군, {name}. 나도 갚아 주지."
L["Orcs keep their thanks short, {name}. Thanks."] = "오크는 감사도 짧다, {name}. 고맙다."
L["Orcs return every blow twice, {name}. The kind ones too."] = "오크는 한 대 맞으면 두 대로 갚는다, {name}. 호의도 마찬가지다."
L["You helped me, I help you. Orc poetry, {name}. It doesn't rhyme."] = "네가 도왔으니, 나도 돕는다. 오크의 시다, {name}. 운율은 없다."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "옛날 같으면 멧돼지로 갚았겠지, {name}. 이건 안 썩는다."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "빚지면 듀로타 모래보다 더 근질거린다, {name}. 됐다. 이제 안 가렵다."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "센 거로군, {name}. 코도랑 씨름도 하겠다. 너도 이제 된다."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "친절에 기습당했다, {name}. 오크도 그건 훈련 안 한다. 그대로 갚는다."
L["Honour is a debt, {name}. Orcs pay on the spot, before we forget what for."] = "명예는 빚이다, {name}. 오크는 바로 갚는다. 뭘 갚는지 잊기 전에."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "오크는 친절을 흉터처럼 기억한다, {name}. 애틋하게, 평생."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "도끼를 주고 싶지만, {name}, 아직 그만큼 친하진 않다. 이거나 받아라."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "고맙다, {name}. 내 늑대가 으르렁댔지? 그게 걔 인사다."
L["I've had gifts from shamans, chieftains and one lost kodo, {name}. Yours wins."] = "주술사, 족장, 길 잃은 코도한테도 선물을 받아 봤다, {name}. 네 게 최고다."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "한때 우린 악마한테 힘을 받았다, {name}. 네 건 조건이 훨씬 낫군."
L["The spirits saw that, {name}. My shaman says they approve. Of you, anyway."] = "정령들이 봤다, {name}. 주술사 말로는 흡족해한단다. 너한테는."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "도끼 자루에 새겨 두마, {name}. 처치 표시들 옆에. 고맙다."
L["A kindness, {name}? Hm. My face is doing something. I think it's a smile."] = "친절이라, {name}? 흠. 얼굴이 이상하게 움직인다. 웃는 건가 보다."
L["In my clan a gift gets a bigger one back, {name}. Don't make me escalate."] = "우리 부족은 선물을 더 크게 갚는다, {name}. 판 키우게 만들지 마라."
L["Dabu, {name}. It is done."] = "Dabu, {name}. 다 됐다."
L["Hold still, {name}. Strength for the fight ahead."] = "가만있어라, {name}. 다가올 싸움을 위한 힘이다."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "오크한테 도움을 청하면 바로 준다, {name}. 섬세함을 청하면 기다려야 하고."
L["Help, yes. Hugging, no. Hold still, {name}."] = "도움은 준다. 포옹은 안 한다. 가만있어라, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "{buff} 원하나, {name}? 옜다, {buff}. 다음."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "움찔하지 마라, {name}. 돕는 얼굴이 싸우는 얼굴이랑 똑같을 뿐이다."
L["Short question, short answer, {name}: yes."] = "짧은 질문엔 짧은 대답이다, {name}. 그래."
L["Work complete, {name}. I started out as a peon; the words never leave you."] = "작업 완료다, {name}. 일꾼 출신이라 입에 붙었다."
L["A challenge, {name}? Oh, a request. Close enough. I accept either way."] = "도전이냐, {name}? 아, 부탁이군. 그게 그거다. 어느 쪽이든 받는다."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "그래, {name}. 도끼 갈던 참이지만 괜찮다. 어차피 맨날 간다."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "명예의 골짜기라면 결투 한 판감이다, {name}. 넌 끄덕 한 번이면 된다."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "지금, {name}? 지금 한다. 오크는 '나중에'란 말을 안 배웠다."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "{buff} 하나다, {name}. 오크식이다. 빠르고, 곧고, 좀 세게."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "가만있어라, {name}. 투척 도끼처럼 던진다. 빗나가는 일은 드물다."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar, {name}. '승리'란 뜻이다. 오늘은 '그래'란 뜻도 된다."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name}! 이걸 품고 전장으로 가라. 술집 싸움도 전장이다."
L["Blood and thunder, {name}! Go and earn your glory."] = "피와 천둥이여, {name}! 가서 영광을 쟁취해라!"
L["Among orcs, {name}, making you stronger is how we say we like you."] = "오크들 사이에선, {name}, 강하게 만들어 주는 게 좋아한다는 뜻이다."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "오크가 먼저 선물을 줬다고? 아무한테도 말하지 마라, {name}. 이미지 망친다."
L["I was told to be more diplomatic, {name}. This is me being diplomatic."] = "외교적으로 굴라더군, {name}. 이게 내 외교다."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "가서 뭐든 한 대 때려라, {name}. 아니면 불태우든가. 오크는 안 가린다."
L["Don't thank me, {name}. Just win, and do it loudly."] = "고마워하지 마라, {name}. 이기기만 해라. 요란하게."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "연설이라도 하고 싶지만, {name}, 대부분 고함이다. 그냥 받아라."
L["You looked like you needed an orc, {name}. Everybody does, sooner or later."] = "오크가 필요해 보이더군, {name}. 누구나 언젠간 필요하다."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "'먼저 쳐라.' 그롬이 늘 하던 말이다, {name}. 그래서 청하기 전에 준다."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "받아라, {name}. 전우를 지나치는 그런트는 혼난다. 나한테."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "서리늑대는 사냥감을 나눈다, {name}. 오늘은 빈손이라 이거라도 나눈다."
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "듀로타 식으로 걸어라, {name}. 고개는 들고, 햇볕은 목덜미에, 전갈은 발밑에."
L["Here, {name}. The spirits love generosity. My axe says nothing; it sulks."] = "받아라, {name}. 정령은 베푸는 걸 좋아한다. 내 도끼는 말이 없다. 삐졌다."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "오크가 공짜로 주는 건 둘이다, {name}. 충고랑 이거. 충고는 넘겨라."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "불모의 땅엔 끝이 없다, {name}. 얼룩말만 늘어난다. 이거 받아라."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "팔에 힘을 주마, {name}. 명예는 이미 챙겨 왔군."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "내 늑대가 너한테 뼈다귀를 주고 싶어 했다, {name}. 이걸로 합의 봤다."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! 네 안에 부족의 피가 힘차게 흐르는군."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "오크로군, {name}! 드디어 나랑 목청이 맞는 녀석이다."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "서리늑대든 전쟁노래든 검은바위든, {name}, 싸우는 건 다 가족 같다."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "오크끼리는 말이 필요 없다, {name}. 다행이다. 할 말도 떨어졌다."
L["Green skin or brown, {name}, it's the same stubborn blood."] = "초록 피부든 갈색 피부든, {name}, 똑같이 고집 센 피다."
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "오크 둘인데 아직 아무도 안 소리쳤다, {name}. 주술사들이 징조라 하겠군."
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "우리 부족끼리 한때 원수였을 거다, {name}. 다들 그랬다. 퉁치자."
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "오크끼리는, {name}, '승리 아니면 죽음'이 그냥 '또 보자'다."
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "네 엄니도 내 엄니도 험한 날 많이 봤다, {name}. 오늘은 좋은 날이다."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "작전이다, {name}. 때린다. 질문? 없나? 좋은 작전이다."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "진짜 전투부대다, {name}. 시끄럽고, 성났고, 웬일로 다 한편이다."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "부대에서 떨어지지 마라, {name}. 힘은 머릿수에서 나온다. 도끼 수에서도."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "쓰러지면, {name}, 내가 업고 나간다. 내내 투덜대겠지만, 업는다."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "잘 싸우면, {name}, 오늘 밤 우리 모닥불에 끼워 주마. 허풍도 같이."
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "아무도 도망 안 친다, {name}. 빠른 걸음으로 멀어지는 건 된다. 겨우."
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "내가 먼저 간다, {name}. 여기서 내가 제일 돌머리다. 자랑이다."
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "전쟁의 북이 울리면, {name}, 돌격해라. 북은 없다. 내가 흥얼거리마."
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "내 등을 맡아라, {name}. 앞은 보인다. 그쪽은 내가 때린다."
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "오늘은 한 부족이다, {name}. '온 놈들' 부족. 최고의 부족이다."
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "저 문으로 큰 놈이 오면, {name}, 내 거다. 더 큰 놈은 우리 거다."
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "흉터는 이야기다, {name}. 다들 짧은 이야기만 들고 나가자."
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "옛 족장들은 작전 회의를 했다, {name}. 우린 내가 저기 가리키면 끝이다."
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "내가 먼저 돌격해도, {name}, 성급한 게 아니다. 전통이다."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "고맙군, {name}. 심장이 아직 뛴다면 따뜻해졌을 텐데."
L["Such warmth, for one so cold? Returned in full, {name}."] = "이리 차가운 자에게 온기라니? 고스란히 돌려주지, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "고맙군, {name}. 얼굴이라도 붉히고 싶지만, 피가 거기까지 안 올라가서."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "죽어도 잊지 못할 은혜요, {name}. 이번만은 말 그대로요."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "친절하군, {name}. 덕분에 '사망'에서 '약간 사망'이 됐소."
L["You've added years to my life, {name}. Shame it already ended."] = "수명이 몇 년은 늘었군, {name}. 이미 끝난 수명이라 아쉽지만."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "느껴지는군, {name}. 요즘 느끼는 게 별로 없는데. 자, 이것도 느껴 보시오."
L["I'd shake your hand, {name}, but I'm not sure mine is still attached."] = "악수라도 하고 싶지만, {name}, 내 손이 아직 붙어 있는지 모르겠군."
L["Thank you, {name}. I'd send a bat with a proper note, but they eat the notes."] = "고맙군, {name}. 박쥐 편에 쪽지를 보내고 싶지만, 놈들이 먹어 버려서."
L["You've spoiled me, {name}. The pleasant kind of spoiled, for once."] = "덕분에 호강하는군, {name}. 썩지 않는 쪽으로는 오랜만이오."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "마지막으로 받은 선물이 역병이었소, {name}. 이건 장족의 발전이군."
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "고맙군, {name}. 로데론 몰락 이후 이리 신선한 건 처음이오."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "실바나스는 빚은 다 갚으라 하지, {name}. 좋은 빚을 말하는 일은 드물지만."
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "자세가 좋아졌군, {name}. 3차 대전쟁 이후 쭉 구부정했는데. 고맙소."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "바로 갚소, {name}. 포세이큰은 빚을 묵히지 않소. 썩으니까."
L["Thank you, {name}. Unpaid debts in Undercity end up in the canal. Not yours."] = "고맙군, {name}. 언더시티에서 못 갚은 빚은 수로행이지. 그대 건 아니오."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "고맙군, {name}. 안전한 데 두겠소. 갈비뼈 사이에 자리가 넉넉하니."
L["Thank you, {name}. I'd bake you something, but everything I touch goes off."] = "고맙군, {name}. 뭐라도 구워 주고 싶지만, 내 손이 닿으면 다 상해서."
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "어둠의 여왕께 그대 얘기를 하겠소, {name}. 그분은 관심 없어도 난 있소."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "친절을 돌려주오, {name}. 내 주위 파리들도 감동한 눈치군."
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "스컬지에 있던 그 세월 동안 이 말 해 준 놈이 없었소, {name}. 고맙소."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "오늘 밤 그대를 위해 한잔하겠소, {name}. 다 새어 나가도 마음이 중요하니."
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "여왕님은 선물을 믿지 말라 하셨지, {name}. 모험 삼아 받고 하나 돌려주겠소."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "고맙군, {name}. 계속 버틸 이유 목록에 올랐소. 목록이 짧긴 하지만."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "고맙군, {name}. 계약서도 깨알 조항도 없다니. 바리마트라스가 배워야겠군."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "무덤 흙과 고마움, {name}. 내 재산은 그게 다요. 고마움 쪽이 낫겠지."
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "고맙군, {name}. 영원은 지루하오. 이번 십 년 중 최고의 순간이었소."
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "파라넬이라면 방금 반응을 기록하려 들겠군, {name}. 난 그냥 돌려주겠소."
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "고맙군, {name}. 로데론에도 예절이 있었지. 누군가 간직해 줘서 다행이오."
L["The Deathguard would salute you, {name}, but it's hard on their arms. Thanks."] = "죽음의 경비대가 경례하고 싶겠지만, {name}, 팔이 떨어질까 봐. 고맙소."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "로데론의 종을 울려 주고 싶지만, {name}, 요즘은 장례식에만 울리오."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "고맙군, {name}. 브릴에 가면 호박 하나에 그대 이름을 붙이겠소."
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "고맙군, {name}. 덕분에 내 사후가 좀 사람 사는 꼴이 됐소."
L["Certainly, {name}. Try not to die. It's overrated."] = "그러지, {name}. 죽지는 마시오. 생각보다 별거 없으니."
L["You need only ask, {name}. The dead are patient."] = "말만 하시오, {name}. 죽은 자는 인내심이 많으니."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "부탁은 죽은 자에게 하시오, {name}. 우린 딱히 다른 약속이 없거든."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "그러지, {name}. 좀 떨어지시오. 뭐가 떨어지기라도 하면 곤란하니."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "잠깐, {name}. 사후 경직 때문에 시전하는 손이 뻣뻣해서."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "무덤 가는 길 말고 다른 걸 물어 주니 반갑군, {name}."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "기꺼이, {name}. 냄새 생각을 잊게 해 주니까. 내 냄새 말이오."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "그러지, {name}. 가만있으시오. 눈알이 돌아가면 조준도 돌아가니."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "언더시티에선 '부탁'이란 말 대신 꾸르륵거리오, {name}. 자, 받으시오."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "{buff}만이오, {name}? 약제사들은 꼭 표본도 한 점 떼어 가던데."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "부르면 늘 일어나는 몸이오, {name}. 좀 불행한 전력이라. 받으시오."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "뭐든 하겠소, {name}. 이성이 허락하는 선에서. 남은 게 별로 없지만."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "물론이오, {name}. '내 눈에 흙이 들어가기 전엔' 하려 했는데, 이미 들어갔군."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "바로 하지, {name}. 죽은 자는 꾸물대지 않소. 목적 있게 비틀거릴 뿐."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "물론이오, {name}. 자유 의지는 선물이지. 난 이런 데 쓰오."
L["Coming up, {name}. Quicker than a bat out of Undercity, and it doesn't bite."] = "곧 가오, {name}. 언더시티 박쥐보다 빠르고, 물지도 않소."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "물론이오, {name}. 역병지대에서 겨울을 나 봤으면 이건 휴가요."
L["{buff}, {name}? Sorry, my good ear's in my other pocket."] = "{buff} 말이오, {name}? 미안하오, 성한 귀를 딴 주머니에 뒀소."
L["Of course, {name}. No sleep, no meals, no plans. I'm extremely available."] = "물론이오, {name}. 잠도, 끼니도, 약속도 없소. 아주 한가하지."
L["I'm dying to help, {name}. Figure of speech. I've done the real one."] = "죽도록 돕고 싶소, {name}. 비유요. 진짜는 이미 해 봤으니."
L["Stay among the living a little longer, {name}."] = "산 자들 곁에 조금 더 머무시오, {name}."
L["Take this, {name}. The grave can wait."] = "받으시오, {name}. 무덤은 기다려 줄 거요."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "로데론에선 의사였소, {name}. 버릇은 나보다 끈질기게 안 죽더군."
L["No charge, {name}. The apothecaries would have made you sign something."] = "공짜요, {name}. 약제사들이었으면 뭔가에 서명부터 시켰을 거요."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "무덤에서 온 선물이오, {name}. 걱정 마시오, 씻어 왔으니."
L["Every body needs a little help, {name}. Mine mostly needs stitches."] = "몸 가진 자라면 다 도움이 필요하오, {name}. 내 몸은 주로 바느질이지만."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "영웅들이 결국 어디로 가는지 봤소, {name}. 내가 사는 곳이오. 받으시오."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "받으시오, {name}. 저승엔 못 가져간다는 걸 몸소 배웠소."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "받으시오, {name}. 내 물건 중 유일하게 눅눅하지 않은 거요."
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "몸 잘 간수하시오, {name}. 흘린 조각은 찾기 힘드오. 경험담이오."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "받으시오, {name}. 역병지대엔 안 받은 자들이 가득하오."
L["A small kindness, {name}. My bat got the last one, and it never said thanks."] = "작은 친절이오, {name}. 지난번 건 내 박쥐가 받고 고맙단 말도 없었지."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "티리스팔 안개는 어디든 스며드오, {name}. 이것도 그렇소. 기분 좋게."
L["Here, {name}. I kept it cool for you. I keep everything cool. Can't help it."] = "자, {name}. 차게 보관했소. 내 손에 닿으면 뭐든 식어 버려서."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "아는 이는 다 먼저 보냈소, {name}. 그대까진 싫소. 받으시오."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "실례하오, {name}. 어슬렁댄다는 말을 듣지. 도움 되게 어슬렁대는 중이오."
L["Out of my own pocket, {name}. What's left of the pocket, anyway."] = "내 주머니를 털었소, {name}. 구멍 안 난 쪽으로."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "최악의 날은 난 이미 겪었소, {name}. 그대 건 면해 봅시다."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "역병지대에서 바람이 부오, {name}. 받으시고, 입으로 숨 쉬시오."
L["The crows have been watching you, {name}. Let's disappoint them."] = "까마귀들이 그대를 노리고 있소, {name}. 실망시켜 줍시다."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "자, {name}. 티리스팔엔 호박과 원한만 자라오. 이건 둘 다 아니오."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "받으시오, {name}. 언더시티에서 유일하게 안 끓여도 되는 거요."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "영원은 길다오, {name}. 이걸 연습하느라 꽤 썼소."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "가는 길에 쓰시오, {name}. 언더시티산이니 불 근처는 피하시오."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "받으시오, {name}. 냄새가 안 나오. 내 장점 중 최고라더군."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "포세이큰은 인내심으로 유명하오, {name}. 이건 못 참고 드리지만."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "대가도, 조종 줄도 없소, {name}. 리치 왕 줄은 진작 끊었지."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "티리스팔에서 갓 가져왔소, {name}. 티리스팔치곤 싱싱하단 뜻이오."
L["Take this, {name}. I was saving it, but I'm bad at keeping things. Look at me."] = "받으시오, {name}. 아껴 두려 했지만, 난 뭘 잘 간수 못 하오. 날 보시오."
L["We Forsaken must look after each other, {name}."] = "우리 포세이큰끼리는 서로 챙겨야지, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "시체끼리 하는 말인데, {name}, 보존 상태가 아주 훌륭하구려."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "손가락 떨어지면 말하시오, {name}. 여분 있소. 포세이큰은 나누는 법."
L["Is your jaw clicking too, {name}, or is that just me?"] = "{name}, 그대도 턱에서 딸깍 소리가 나오, 아니면 나만 그렇소?"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "실바나스께 승리를, {name}. 이번엔 작은 승리지만, 우리 거요."
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "{name}, 어디서 깨어났소? 난 눅눅한 지하 묘지 당첨이었소."
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "스컬지가 찾아와도, {name}, 우린 집에 없소. 다시는."
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "방벽은 아직 버티오, {name}. 우리도 버티지. 꿰맨 채로지만."
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "로데론이 우릴 두 번 낳았소, {name}. 한 번은 아이로, 한 번은 포세이큰으로."
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "노스렌드 어딘가에서, {name}, 리치 왕이 우리 때문에 삐쳐 있을 거요. 잘됐지."
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "어둠의 여왕께선 우리가 온전하길 바라시오, {name}. 대충 온전하면 되지."
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "티리스팔 냄새가 나는군, {name}. 우리끼린 칭찬이오."
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "우린 둘 다 영원이 있소, {name}. 승강기 기다리다 다 쓰진 맙시다."
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "포세이큰끼리 하는 말인데, {name}, 하수도 지름길은 지름길이 아니오."
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "죽음의 경비병이 물으면, {name}, 순찰 중이라 하시오. 아주아주 느린 순찰."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "우리 같은 자들은 친절받을 일이 드물지, {name}. 식구끼리 나눕시다."
L["The bats in the Trade Quarter know us both by now, {name}. That's fame, nearly."] = "상업 지구 박쥐들이 이제 우릴 둘 다 알아보오, {name}. 거의 유명인이지."
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "믿음을 지키시오, {name}. 서로에 대한 믿음 말이오. 그쪽이 응답이 잦지."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "죽은 자는 죽은 자를 챙기오, {name}. 산 자들도 좀 배워야 할 텐데."
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "우리 둘 다 무덤 속에 있어 봤지, {name}. 서비스 엉망에 전망도 없더군."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "살아 있으시오, {name}. 언더시티 입주 대기자가 이미 넘치오."
L["If I fall down, {name}, give it a minute. Old habit."] = "내가 쓰러져도, {name}, 잠깐 기다리시오. 오랜 버릇이라."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "앞은 내가 맡지, {name}. 최악이래 봐야 뭐겠소? 또 죽는 거?"
L["Keep upwind of me, {name}. It's better for morale."] = "내 바람 위쪽에 서시오, {name}. 사기에 좋으니."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "지난번 파티에선, {name}, 깨어나 보니 지하 묘지였소. 이번엔 좀 낫게 해 봅시다."
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "무는 놈은 내게 보내시오, {name}. 나한텐 먹을 게 안 남았소."
L["Spare the heals for the others, {name}. I run on spite and embalming fluid."] = "치유는 딴 사람들한테 쓰시오, {name}. 난 앙심과 방부액으로 굴러가오."
L["If this goes badly, {name}, don't worry. I know the way back. Intimately."] = "일이 틀어져도, {name}, 걱정 마시오. 돌아오는 길은 눈 감고도 아니."
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "스컬지 편에서도 반대편에서도 싸워 봤소, {name}. 이쪽 동료가 낫군."
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "가까이 있으시오, {name}. 구울 보고 비명 안 지를 사람은 나요. 옛 이웃이라."
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "밤의 역병지대도 걸어 봤소, {name}. 이건 산책이오."
L["The corpse at the back is me, {name}. Please don't loot it."] = "뒤에 있는 시체가 나요, {name}. 전리품은 뒤지지 마시오."
L["Stay together, {name}. It's easier than putting somebody back together."] = "뭉쳐 다니시오, {name}. 흩어진 사람 다시 꿰매는 것보단 쉬우니."
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "날 기다리지 마시오, {name}. 느려도 영원히 걷소. 결국 따라잡지."
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "횃불은 내게서 멀리, {name}. 오래되고 바싹 말라서 잘 타오."
L["Don't check me for a pulse after, {name}. It only worries people."] = "끝나고 내 맥박은 재지 마시오, {name}. 괜히 걱정들 하니."
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "초록 웅덩이 조심하시오, {name}. 그게 뭘 하는지 아오. 그 결과가 나요."
L["Send anything scary to me, {name}. I've been dead; it's got nothing."] = "무서운 건 내게 보내시오, {name}. 죽어도 봤는데 뭐가 무섭겠소."
L["Stick together, {name}. The apothecaries pay well for strays."] = "떨어지지 마시오, {name}. 약제사들이 낙오자를 비싸게 사 가오."
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "물속에서 끝나도, {name}, 난 신경 쓰지 마시오. 숨은 이제 선택 사항이라."
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "어둠의 여왕께선 아무도 안 믿으시오, {name}. 난 이 파티만 예외로 했소."
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "이기면, {name}, 브릴 여관에서 한잔하지. 계산은 내가, 위험은 그대가."
L["Don't mind the bats, {name}. They follow me everywhere. They think I'm a cave."] = "박쥐는 신경 쓰지 마시오, {name}. 날 동굴로 아는지 어딜 가든 따라오오."
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "후방은 내가 맡지, {name}. 눈을 못 깜박이니 기습도 안 통하오."
L["Any blood on the floor after, {name}, it isn't mine. I stopped carrying any."] = "끝나고 바닥에 피가 보여도, {name}, 내 피는 아니오. 난 피가 없어서."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "죽은 자들은 생활 리듬이 엉망이오, {name}. 모처럼 말동무가 있어 좋군."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "자정이오, {name}. 일어나 있으면 안 될 자가 돌아다니기 딱 좋은 시간."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "산 자들은 다 잠들었소, {name}. 포세이큰은 이걸 조용한 야간 근무라 부르지."
L["Late, {name}? In Undercity, this is lunchtime."] = "늦었다고, {name}? 언더시티에선 지금이 점심시간이오."
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "스컬지가 돌아다니던 시각이오, {name}. 이젠 우리 시간이지."
L["Night, {name}. The one time nobody can tell I'm pale."] = "밤이오, {name}. 내가 창백한 걸 아무도 모르는 유일한 때지."
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "언더시티만큼 어둡군, {name}. 드디어 제대로 된 조명이오."
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "안개, 달빛, 곰팡내 약간이라, {name}. 제대로 된 티리스팔 날씨군."
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "밴시들이 노래할 시간이오, {name}. 걱정 마시오. 연습일 뿐이니."
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "티리스팔의 별들이오, {name}. 저 위에서 유일하게 안 썩은 것들이지."
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "자정이 지났소, {name}. 무덤가가 조용하군. 괜찮은 무덤들은."
L["An owl just saw me and left, {name}. They're sensible birds."] = "부엉이가 날 보더니 떠났소, {name}. 눈치 빠른 새들이지."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "벌써 아침이오, {name}? 밤을 꼬박 새웠소. 지난 십 년도."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "해가 떴군, {name}. 그늘에 서 있겠소. 이것저것 벗겨져서."
L["Early start, {name}. The dead never sleep in. Or at all, really."] = "이른 출발이군, {name}. 죽은 자는 늦잠을 안 자오. 사실 잠 자체를."
L["Sunrise, {name}. My least favourite colour. I'm off to find some shade."] = "해돋이군, {name}. 제일 싫어하는 색이오. 그늘 찾으러 가겠소."
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "티리스팔의 새벽이오, {name}. 잿빛, 그다음 조금 덜 잿빛. 장관이지."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "좋은 아침이오, {name}. 여관 죽이 또 꿈틀댔소. 대신 이걸 드시오."
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "브릴 수탉들은 아직도 우오, {name}. 차마 말해 줄 사람이 없어서."
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "좋은 아침이오, {name}. 죽음의 경비병 교대 시간이오. 그냥 뒤로 돌지."
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "승강기는 천천히 타시오, {name}. 서두른 마지막 자는 아직도 내려가는 중이오."
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "언더시티엔 다 있소, {name}. 은행, 여관, 하수도의 말 많은 것들까지."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "여기선 쥐도 어둠의 여왕께 절하오, {name}. 쥐가 달라기 전에 받으시오."
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "수로 조심하시오, {name}. 초록색인 데는 이유가 있소. 이끼는 아니고."
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "언더시티는 이맘때가 좋소, {name}. 늘 이맘때지만."
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "로데론 지하실로 이사 왔소, {name}. 좋은 은식기는 챙겼지."
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "왕실 지구는 저쪽이오, {name}. 깊이 절하시오. 밴시들이 점수를 매기니."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "박쥐 조련사는 순하다고 맹세하오, {name}. 확인하기 전에 이것부터 받으시오."
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "마법 지구는 저쪽이오, {name}. 빛나는 웅덩이는 마시는 게 아니오."
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "왕좌의 방은 바로 위층이오, {name}. 아무도 안 앉소. 기억이 안 좋아서."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "다들 포세이큰은 성수로 맞이하지, {name}. 그대는 반가운 예외요."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "포세이큰 앞에서 멈추는 이는 드물지, {name}. 그대는 멈췄소. 고맙소."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "소문과 달리, {name}, 포세이큰이 주는 게 다 역병은 아니오."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "포세이큰은 매혹이 안 통한다지, {name}. 공손한 부탁은 통하오."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "잡담 대신 이걸 받으시오, {name}. 내 잡담은 다들 불편해하니."
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "포세이큰은 친구가 없다더군, {name}. 지금 모집 중이오."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "받으시오, {name}. 누가 물으면 포세이큰이 아주 매력적이었다 하시오."
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "살아 있으시오, {name}. 반대쪽도 해 봤는데, 추천은 못 하겠소."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "대지모신께서 그대의 친절을 보셨소, {name}. 날 쿡 찌르시더군. 꽤 세게."
L["Thank you, {name}. May the winds guide you."] = "고마운 일이오, {name}. 바람이 그대를 이끌기를."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "고맙소, {name}. 마음이 움직였소. 타우렌을 움직이기란 쉽지 않은데."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "타우렌의 심장까진 한참 올라가야 하오, {name}. 그대가 찾아냈구려."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "뿔부터 발굽까지 느꼈소, {name}. 발굽부터 뿔까지 돌려드리리다."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "베푼 선물은 심은 씨앗이오, {name}. 여기 그 수확이오."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "잔치를 열 일이오, {name}. 잔치는 나중에, {buff} 먼저."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "고맙소, {name}. 숨을 벽이 필요하면 말하시오. 난 늘 한가하오."
L["I'd dance for joy, {name}, but last time Bloodhoof lost a roof. This instead."] = "춤추고 싶지만, {name}, 지난번에 블러드후프 지붕이 무너졌소. 대신 이걸."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "윈드라이더보다 빨리 돌려드리오, {name}. 꽥꽥대지도 않고."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "갚았소, {name}. 가시멧돼지는 갚을 줄 몰라서 저 꼴이오."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "고맙소, {name}. 조상님들이 다들 고개를 끄덕이시오. 끄덕임이 어마어마하오."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "멀고어에선 선물 밑 풀이 다시 자라기 전에 보답하오, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "고맙소, {name}. 다음 새끼 코도에 그대 이름을 붙이리다. 아주 귀엽소."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "친절은 불모의 땅 그늘보다 귀하오, {name}. 여기 좀 돌려드리오."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "토템에 새겨 두리다, {name}. 타우렌은 천천히 새기니, 봄쯤 되겠소."
L["Folk give directions by me, {name}: 'left at the tauren.' You gave me a gift."] = "다들 날 이정표로 쓰오, {name}. '타우렌에서 왼쪽.' 그대는 선물을 줬구려."
L["Cairne taught us to honour every kindness, {name}. I'd been hoping for one."] = "케른께선 모든 친절을 기리라 하셨소, {name}. 하나 오길 기다렸지."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "여부가 있겠소, {name}. 마음 편히 계시오. 우뚝 서는 건 내가 하리다."
L["Ask and it is given, {name}. The herd shares what it has."] = "청하면 주는 법이오, {name}. 무리는 가진 것을 나누니."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "물론이오, {name}. 한 걸음 물러서시오. 난 온몸으로 하니까."
L["Gladly, {name}. Mind the tail."] = "기꺼이, {name}. 꼬리 조심하시오."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "대지모신께선 아낌없이 주시오, {name}. 그분의 가장 큰 자식들도 그렇고."
L["Gladly, {name}. Tauren are slow to anger and quick to help. Quick-ish."] = "기꺼이, {name}. 타우렌은 화는 느리고 돕기는 빠르오. 빠른 편이오."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "거절이라니, {name}? 조상님들 잔소리를 영원히 들을 거요."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "물론이오, {name}. 타우렌의 '예'는 평원의 풀처럼 쉽게 돋아나오."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "물론이오, {name}. 잠시만. 손은 크고 주문은 작아서."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "코도 떼를 한 철 몰고 나면, {name}, 공손한 부탁은 휴가요. 여기."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "대지모신께선 나누라 하시고, {name}, 배는 밥 달라 하오. 서열은 그분이 위지."
L["Of course, {name}. You get the help and a tauren proverb. Proverb: hold still."] = "물론이오, {name}. 덤으로 타우렌 격언도 드리지. 격언: 가만있으시오."
L["Spirits of the plains, lend me a hand. ...Ah, I have two. Here, {name}."] = "평원의 영령이여, 손을 빌려주소서. ...아, 내 손이 둘 있군. 여기, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "마가타라면 대가를 바랐겠지, {name}. 베인 족장이라면 그냥 해 주오. 그러니: 예."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "가만있으시오, {name}. 코도로 연습했는데, 걔들은 훨씬 버릇이 없소."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "물론이오, {name}. 슈할로는 나그네를 거절 않소. 한 그릇 더도."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "대지모신과 함께 걸으시오, {name}. 어디에나 계시니 길 잃을 일은 없소."
L["May An'she light your path, {name}."] = "안셰께서 그대의 길을 비추시기를, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "친구가 필요해 보였소, {name}. 난 아주 큰 친구라오."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "받으시오, {name}. 그냥 지나쳤다간 대지모신께 혼나오."
L["Tread lightly, {name}. Take it from someone who never has."] = "사뿐히 걸으시오, {name}. 평생 그래 본 적 없는 자의 조언이오."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "바람이 그대가 지나갈 거라 하더군, {name}. 바람은 입이 가볍소."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "받으시오, {name}. 코도도 빌려주고 싶지만, 그 녀석은 나만큼 너그럽지 않소."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "슈할로는 남을 위해 질 수 있는 만큼 지라 하오, {name}. 난 많이 질 수 있소."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "받으시오, {name}. 켄타우로스가 귀찮게 하면 썬더 블러프가 안부 전한다 하시오."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "자, {name}. 평원 새들은 괜히 날 보면 도망가오. 그대는 안 그래도 되오."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "그대에게, {name}. 언제 멀고어에 오시오. 풀은 부드럽고 아무도 서두르지 않소."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "자, {name}. 할머니는 나그네를 축복하고 먹이셨소. 난 빵이 떨어졌소."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "영령들이 그대를 돌보라 하셨소, {name}. 말씀 끝나기도 전에 예 했지."
L["Here, {name}. Better a gift than a war stomp. Both leave an impression."] = "자, {name}. 전투 발구르기보단 선물이 낫지. 둘 다 깊이 남긴 하오."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "자, {name}. 타우렌은 세상을 조금 낫게, 그리고 조금 밟힌 채로 남기오."
L["You look weary, {name}. The Earth Mother would offer a nap. I offer this."] = "피곤해 보이오, {name}. 대지모신께선 낮잠을 주시겠지만, 난 이걸 드리오."
L["Sunwalkers call it a blessing, hunters luck, {name}. Tauren call it manners."] = "태양걸음이는 축복, 사냥꾼은 행운이라 하오, {name}. 타우렌은 예의라 하지."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "받으시오, {name}. 하피가 꽥 소리치면 같이 꽥 하시오. 질색하오."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "자, {name}. 타우렌의 축복이오. 튼튼하고, 오래가고, 세이지 향이 은은하지."
L["The Earth Mother watches over us both, {name}."] = "대지모신께서 우리 둘을 지켜보신다오, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "문틀들한테 경고 좀 해 주시오, {name}. 이제 우리가 둘이오."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "평원이든 산이든, {name}, 슈할로의 심장은 크다오."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "뿔과 투구라, {name}. 이 고통은 타우렌만 알지."
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "털에 밴 빗물은 마르는 데 일주일이오, {name}. 타우렌만 믿어 주지."
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "타우렌끼리 얘기요, {name}. 썬더 블러프 승강기는 분명 작은 자가 만들었소."
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "조상님들이 우리 둘을 보고 계시오, {name}. 보기 좋은 걸 보여 드립시다."
L["From Mulgore to Highmountain, {name}, the herd always finds itself."] = "멀고어에서 높은산까지, {name}, 무리는 늘 서로를 찾아내오."
L["Get behind me, {name}. There's room back there for the whole party."] = "내 뒤로 오시오, {name}. 파티 전체가 들어가고도 남소."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "무리는 함께 움직이오, {name}. 내 발굽 조심하시오. 무리는 이미 배웠소."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "앞에 천장이 낮소, {name}? 제일 먼저 알게 될 건 나요. 받으시오."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "난 쉽게 화내지 않소, {name}. 하지만 원한은 파티 몫까지 품지."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "숨을 벽이 필요하오, {name}? 내가 거의 벽이오. 오시오."
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "내가 전투 발구르기를 하면, {name}, 다들 앉으시오. 넘어질 수고는 덜 테니."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "다들 먹었소? 축복도 받았소? 좋소, {name}. 타우렌은 굶은 무리를 이끌지 않소."
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "타우렌은 헤엄 안 치오, {name}. 걸어서 건너지. 깊으면 내 등에 타시오."
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "가까이 오시오, {name}. 조상님들도 함께 걸으시오. 그대들보다 조용하시지."
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "내가 쓰러지면, {name}, 업으려 하지 마시오. 끌고 가시오. 다정하게."
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "우린 코도 떼처럼 움직이오, {name}. 다 함께, 그리고 꽃들에겐 미안하게."
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "뒤에서 혼자 걷는 이는 없소, {name}. 내가 거기서 다정하게 우뚝 서 있을 테니."
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "돌격할 때 말해 주시오, {name}. 타우렌은 출발도 느리고 멈추긴 더 느리오."
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "딴 데로 새지 마시오, {name}. 불모의 땅에서 그랬던 파티는 아직도 걷는 중이오."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "안셰께서 떠오르시오, {name}. 우리도 일어나야지. 난 좀 느리지만."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "해는 안셰의 눈이오, {name}. 지켜보고 계시니 바쁜 척합시다."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "좋은 아침이오, {name}. 코도는 일어났고, 풀은 젖었고, 이건 그대 것이오."
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "좋은 아침이오, {name}. 해와 바람, 새 두 마리에게 인사했소. 이제 그대요."
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "좋은 아침이오, {name}. 풀에도 이슬, 내 털에도 이슬. 정오까진 눅눅하겠소."
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "이른 아침이오, {name}. 새벽 멀고어의 안개? 대부분 코도 입김이오."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "무샤께서 밤을 지키시오, {name}. 그대를 잘 봐 달라고 말씀드리리다."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "달이 떴소, {name}. 무샤께서 그대를 보시고 좋다 하시오. 내가 여쭤봤소."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "밤이 깊었소, {name}. 코도들이 천둥처럼 코를 고는군. 받으시오."
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "별이 떴소, {name}. 별마다 조상님이라 하지. 저분이 그대에게 윙크하시오."
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "밤이 깊었소, {name}. 멀고어의 밤은 풀들 말다툼까지 들릴 만큼 조용하오."
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "쉿, {name}. 이 시간엔 내 발굽도 까치발을 드오."
L["Ya be too kind, {name}! Dis one be from me."] = "친절하기도 하지, {name}! 이건 내가 주는 거라고."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "고맙다, 친구! 영혼들이 너한테 미소 짓는다고, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "좋은 기운 줬으니, {name}, 매운맛으로 돌려준다고."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "브원삼디가 엄청 실망하겠네, {name}. 고맙다, 친구."
L["Dat be some fine work, {name}. Almost as fine as me. Almost."] = "솜씨 좋은데, {name}. 거의 나만큼. 거의."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "트롤은 손이 다시 자란다고, {name}. 명예는 안 자라. 자, 갚는다."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "트롤을 웃게 만들었네, {name}. 우리 이빨 많다고."
L["Da loa keep a tally, {name}, and now ya on da good side of it."] = "로아가 장부를 적는다고, {name}. 이제 넌 좋은 쪽에 있어."
L["Ya beat me to it, {name}! Darkspear hate bein' second. Now we even."] = "선수 쳤네, {name}! 검은창은 두 번째를 싫어한다고. 이제 비겼다."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "이제 빚졌네, {name}. 트롤은 로아한테만 빚지고 싶다고. 자, 청산."
L["I be tellin' da whole Echo Isles 'bout ya, {name}. All dey talk 'bout is crabs."] = "메아리 섬에 네 얘기 쫙 퍼뜨릴 거라고, {name}. 거기 화제는 맨날 게뿐이거든."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "머리카락이 더 솟았다고, {name}. 이게 더 되는 줄 몰랐네. 고맙다, 친구."
L["Da spirits say 'give it back', {name}. Da spirits nag, but dey right."] = "영혼들이 '돌려줘'래, {name}. 잔소리꾼들이지만 맞는 말이라고."
L["Mojo for mojo, {name}: oldest trade in da jungle. Second oldest be bananas."] = "주술엔 주술, {name}. 정글에서 제일 오래된 거래라고. 두 번째는 바나나."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "볼진이 친절은 빨리 갚으랬어, {name}. 말이 많았지. 그건 기억난다고."
L["Dat deserve a dance, {name}. Lucky ya, ya get {buff} instead."] = "춤출 일이다, {name}. 다행인 줄 알아. 춤 대신 {buff} 준다고."
L["Jungle rule, {name}: what ya give come back, usually wit' teeth. Dis one don't."] = "정글 법칙이다, {name}. 준 건 돌아온다고. 대개 이빨 달고. 이건 안 물어."
L["A gift for a troll? Careful, {name}. We follow nice folk home."] = "트롤한테 선물? 조심해, {name}. 우린 착한 사람 집까지 따라간다고."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "암, 그렇고말고, {name}. 가만있어. 주술은 움직이는 과녁을 싫어한다고."
L["No worries, {name}. Da loa got ya covered."] = "걱정 마, {name}. 로아가 챙겨 줄 거라고."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "부두는 가까이하지 마, {name}. ...이 부두만 빼고. 이건 괜찮다고."
L["Close ya eyes, {name}. Da mojo be shy when people watch."] = "눈 감아, {name}. 주술이 누가 보면 부끄럼 탄다고."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "두 번 말할 필요 없어, {name}. 한 번도 겨우 필요하다고."
L["Sure, {name}. Bein' a troll be mostly swagger. Da rest be dis."] = "그래, {name}. 트롤은 대부분 허세라고. 나머진 이거고."
L["Ya asked real polite, {name}. Polite get da good stuff."] = "예의 바르게 물었네, {name}. 예의 바르면 좋은 걸 받는다고."
L["Ya came to da right troll, {name}. Da wrong troll be over dere, fishin'."] = "제대로 된 트롤한테 왔네, {name}. 잘못된 트롤은 저기서 낚시 중이라고."
L["Yes, {name}. Da loa owe me a favour, and I be spendin' it on you."] = "그래, {name}. 로아가 나한테 빚진 게 있는데, 너한테 쓴다고."
L["No problem, {name}. Got a pouch fulla mojo. Don't touch da other pouch."] = "문제없어, {name}. 주머니에 주술이 가득하다고. 다른 주머니는 만지지 마."
L["Anyting for ya, {name}. Well, not my hair. Da hair be sacred."] = "뭐든 해 줄게, {name}. 머리카락만 빼고. 머리는 신성하다고."
L["Troll magic, {name}, served hot. Blow on it first."] = "트롤 주술 나왔다, {name}. 뜨거우니 호호 불어 먹어."
L["Right away, {name}. In Zandalar dis need a priest, a pyramid and a week."] = "바로 간다, {name}. 잔달라였으면 사제랑 피라미드랑 일주일 걸린다고."
L["Easy one, {name}. Hard one be gettin' a raptor to sit still."] = "쉬운 거지, {name}. 어려운 건 랩터 가만 앉히기라고."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "트롤 규칙이다, {name}. 친구는 조르게, 랩터는 기다리게 하지 말 것. 자."
L["Hold still, {name}. Last one who wiggled got da spell and a new haircut."] = "가만있어, {name}. 지난번에 꼼지락댄 놈은 주문에 새 머리까지 받았다고."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "로아가 널 지켜보고 있다고, {name}. 참견쟁이들이거든."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "눈 크게 뜨고 다니라고, {name}. 이거 챙겨 가."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "품질 좀 알아보게 생겼네, {name}. 자, 품질."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "이거 받아, {name}. 정글 주인처럼 걸으라고. 나처럼."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "누구나 주술 기운이 필요하다고, {name}. 난 너무 많아서 나눠 줘야 해."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "작은 선물이다, {name}. 로아가 어디서 났는지는 묻지 마."
L["Go on, {name}. Anyting try to eat ya now gonna get indigestion."] = "가 봐, {name}. 이제 널 먹으려는 놈은 체할 거라고."
L["Ya lookin' dangerous now, {name}. Almost troll-level dangerous."] = "이제 좀 위험해 보이네, {name}. 거의 트롤급으로."
L["Somethin' for ya, {name}. No, ya don't owe da loa nothin'. Probably."] = "선물이다, {name}. 아니, 로아한테 빚지는 거 없어. 아마도."
L["Raptors out dere got bigger teeth den me, {name}. Now dey got a problem."] = "밖에 랩터들은 나보다 이빨이 크다고, {name}. 이제 걔들이 큰일이지."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "트롤식 대접이다, {name}. 주술 주고, 미소 주고, 내 생선은 안 줘."
L["Walk wit' mojo, {name}. Everybody else just be walkin'."] = "주술 두르고 가라고, {name}. 남들은 걷는 거고, 넌 납시는 거지."
L["Free mojo, {name}! Quick, before da witch doctor find out I give it away."] = "공짜 주술이다, {name}! 부두술사가 알기 전에 얼른."
L["Da loa said give dis to da next good soul, {name}. Ya da next good soul."] = "로아가 다음 착한 영혼한테 주라더라, {name}. 그게 너다."
L["Here, {name}. Hakkar never shared, and look what happen to him."] = "자, {name}. 학카르는 나눌 줄 몰랐지. 그 꼴 봐라."
L["Jungle got two kinds of folk, {name}: da ready and da lunch. Now ya ready."] = "정글엔 두 부류가 있다고, {name}. 준비된 놈, 도시락. 넌 이제 준비됐고."
L["Easy, {name}. Dis mojo tickle goin' in. Don't laugh; it get offended."] = "살살, {name}. 이 주술 들어갈 때 간지럽다고. 웃지는 마. 삐친다."
L["'Nobody badduh dan me,' Zul'jin said, {name}. Dis let ya argue da point."] = "'나보다 센 놈은 없다!' 줄진이 그랬지, {name}. 이제 너도 따져 볼 만해."
L["Hey, {name}! Always good to see family, mon."] = "어이, {name}! 가족을 보니 늘 반갑다고, 친구."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "아제로스 딴 녀석들은 허리 펴고 선다고, {name}. 우리가 더 멋있지."
L["Hey, {name}, ya tusks be lookin' sharp. Mine too, obviously."] = "어이, {name}, 엄니 날 잘 섰는데. 내 것도 물론이고."
L["Every troll be family, {name}. Even da ones who still owe me gold."] = "트롤은 다 가족이라고, {name}. 아직 돈 안 갚은 녀석들까지."
L["Island or pyramid, {name}, a troll be a troll. Zandalari just wear more gold."] = "섬이든 피라미드든, {name}, 트롤은 트롤이라고. 잔달라는 금붙이만 더 걸쳤지."
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "트롤이 둘이네, {name}. 방 평균 키도, 느긋함도 확 올랐다고."
L["Da loa can't tell us apart, {name}. Dat be why dey bless us both. Cheaper."] = "로아는 우릴 구분 못 한다고, {name}. 그래서 둘 다 축복하지. 묶음 할인."
L["Troll to troll, {name}: nobody else know how hard it be to buy boots."] = "트롤끼리 얘긴데, {name}. 신발 사기가 얼마나 힘든지 아무도 몰라."
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "조상들은 제국을 가졌지, {name}. 우린 서로를 가졌고. 남는 장사라고."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "붙어 있어, {name}. 트롤은 재생되지만, 너희는 조심해야 한다고."
L["Dis crew got style, {name}. Now it got mojo too."] = "이 패거리 멋있다고, {name}. 이제 주술 기운까지 있고."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "같이 들어가서 같이 나온다, {name}. 그게 작전 전부라고, 친구."
L["Nobody fallin' today, {name}. Bwonsamdi can wait for da next group."] = "오늘은 아무도 안 쓰러진다고, {name}. 브원삼디는 다음 파티나 기다리라 해."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "넌 고개 숙여, {name}. 난 들고 있을게. 누군간 멋있어야지."
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "랩터 대형이다, {name}. 빠르게, 시끄럽게, 뒤는 아무도 안 본다."
L["Big snake show up, {name}, don't run. Ya run, it chase. Stand behind me."] = "큰 뱀 나오면, {name}, 뛰지 마. 뛰면 쫓아온다. 내 뒤에 서."
L["Anybody need more mojo, {name}, just shout. Not too loud; da loa nappin'."] = "주술 더 필요하면, {name}, 불러. 너무 크게는 말고. 로아 낮잠 중이다."
L["We gonna be a story at Sen'jin, {name}. Let's make it one wit' a happy endin'."] = "우린 센진 마을 이야깃거리가 될 거라고, {name}. 해피엔딩으로 가자."
L["Stick close, {name}. My tusks be sharp, but dey can't be everywhere."] = "붙어 있어, {name}. 내 엄니가 날카롭긴 한데, 어디에나 있을 순 없다고."
L["Nobody panic, {name}. Panic be bad mojo. Swagger be good mojo."] = "아무도 겁먹지 마, {name}. 겁은 나쁜 주술, 허세는 좋은 주술이다."
L["See a big idol wit' glowin' eyes, {name}? Don't touch it. Trust me on dis."] = "눈 빛나는 큰 우상 보이지, {name}? 만지지 마. 경험담이다."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "밤이 주술엔 최고라고, {name}. 어디서 오는지 아무도 못 보거든."
L["Da jungle wake up at night, {name}. So do I. Here, dis one fresh."] = "정글은 밤에 깨어난다고, {name}. 나도. 자, 갓 뽑은 거다."
L["Moon be high, {name}, spirits be restless. Dis keep dem off ya."] = "달이 높다, {name}. 영혼들이 들썩인다고. 이게 막아 줄 거야."
L["Hir'eek, da bat loa, keep late hours too, {name}. Dis from da both of us."] = "박쥐 로아 히리크도 밤을 샌다고, {name}. 이건 우리 둘이 주는 거다."
L["Dis late, {name}, only trolls and trouble be awake. I be da nice one."] = "이 시간엔, {name}, 트롤이랑 말썽만 깨어 있다고. 난 착한 쪽이고."
L["Stars be out, {name}. Every one a loa, my granny say. Dat a lotta watchers."] = "별이 떴다, {name}. 할머니가 별마다 로아랬지. 보는 눈 참 많다."
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "그 예의, 그대를 빛내 주는군요, {name}. 날 빛내는 것만은 못해도."
L["How gracious, {name}. Allow me to return the favour."] = "품위 있는 행동이군요, {name}. 나도 호의로 답하지요."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "고마워요, {name}. 이렇게 눈부신 기분은... 음, 오늘 아침 이후 처음이네요."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "친절하군요, {name}. 신도레이는 공짜 마법은 절대 사양 안 해요. 소문났죠."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "훌륭하군요, {name}. 난 훌륭한 것만 받으니 확실하죠."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "근사하네요, {name}. 오늘 하루 종일 이걸로 으스댈 거예요. 평소보다 더."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "고마워요, {name}. 내 금장식과도 어울리네요. 안목이 있으시군요."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "같은 걸로 보답하죠, {name}. 좀 더 예쁜 걸로요. 어쩔 수 없네요."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "고마워요, {name}. 실버문에 오면 살인자 골목만 빼고 다 보여 줄게요."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "갚았어요, {name}. 캘타스와 달리 난 받은 건 돌려주거든요."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "고마워요, {name}. 귀 끝까지 전해졌어요. 꽤 먼 길인데."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "고마워요, {name}. 너무 친절해서 눈 색깔이 또 바뀔 뻔했어요."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "청하지도 않은 선물? 원정순찰대라면 매복이라 하겠군요. 근사한 매복이에요, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "마나 수정보다 낫네요, {name}. 그건 끊었어요. 대체로요. 고마워요."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "빠르군요, {name}. 수백 년 사는 엘프보다 먼저라니."
L["Charming, {name}. I don't say it lightly. I say it constantly, but not lightly."] = "매력적이군요, {name}. 쉽게 하는 말 아니에요. 자주 할 뿐이죠."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "고마워요, {name}. 궁정에서 그대 얘길 할게요. 음, 아주 격조 높은 소풍에서요."
L["Thank you, {name}. You've been added to my list of people who deserve me."] = "고마워요, {name}. '날 누릴 자격 있는 사람' 명단에 올렸어요."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "청하지도 않은 친절이라니, {name}! 롬마스한테 알려요. 연구하고 싶어 할 테니."
L["Naturally, {name}. Only the finest for you."] = "당연하지요, {name}. 그대에겐 최고만 드리죠."
L["For you, {name}? Of course. The sun gives freely."] = "{name}, 그대에게요? 물론이죠. 태양은 아낌없이 베푸니."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "서두르지 마요, {name}. 광채는 재촉하는 게 아니라 감상하는 거예요."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "물론이죠, {name}. 흠잡을 데 없는 자세로 {buff} 대령이에요."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "정중하게 청하셨군요, {name}. 실버문에선 그게 전부죠."
L["One moment, {name}. I never cast anything without checking my hair."] = "잠시만요, {name}. 머리 모양을 확인하지 않고는 아무것도 시전 안 해요."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "당장 하죠, {name}. 남을 기다리게 하는 건 너무 촌스러우니까."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "물론이죠, {name}. 한 걸음 물러서요. 내 소매는 마법에 걸렸고 아주 넓거든요."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "마법학자는 청구서를, 피의 기사단은 설교를 주겠죠, {name}. 난 빛날 뿐."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "당장 하죠, {name}. 잘되면 내 덕, 못되면 로브 탓이에요."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "당장 하죠, {name}. 용매는 기다려도 돼요. 내가 옷 입을 때마다 기다리거든요."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "기꺼이요, {name}. 한때 나루에게서 빛을 빼앗았죠. 부탁이 훨씬 낫네요."
L["Three centuries of casting, {name}, and you're the first to say please."] = "삼백 년을 시전했는데, {name}, '부탁해요'라고 한 건 그대가 처음이에요."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "기꺼이요, {name}. 실버문 빗자루는 알아서 쓸거든요. 손이 한가해요."
L["Of course, {name}. Arcane Torrent is for the rude. You asked nicely."] = "물론이죠, {name}. 비전 격류는 무례한 자들 몫이에요. 그대는 정중했으니."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. 태양이 그대를 인도하고, 잘 나온 쪽을 비추기를."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. 우아하게 싸우시길."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "받으세요, {name}. 밖에서 무슨 일이 생기든 잠깐의 후퇴일 뿐이에요."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "누구나 빛날 자격이 있죠, {name}. 물론 나보다 조금 덜."
L["The sun is with you, {name}. I simply held the door for it."] = "태양이 그대와 함께해요, {name}. 난 문만 열어 줬을 뿐이죠."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "어서 받아요, {name}. 태양샘도 돌아왔으니 이 정도 인심은 쓰죠."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "{name}, 그대에게. 실버문 향을 살짝 입힌 {buff}."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "여기요, {name}. 실버문 수제 주문이니까 흠집 내지 않게 조심해요."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "태양샘 한 조각이에요, {name}. 고생 많이 한 샘이니 살살 다뤄 줘요."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "대비하세요, {name}. 우린 못 했다가 죽음의 흉터를 길로 쓰게 됐거든요."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "여기요, {name}. 자격 있는 자에게만 줘요. 마침 그대가 지나가다니, 편리하네요."
L["Take this, {name}. It's been in my family for moments."] = "받아요, {name}. 우리 가문에 대대로 내려온 거예요. 몇 초 동안."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "우리 신도레이는 많은 걸 잃었죠, {name}. 너그러움만은 빼고요. 광대뼈도요."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "받아요, {name}. 마나 벌레가 따라오면, 그냥 질투하는 거예요."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "너그러움을 완성하는 데 칠천 년이죠, {name}. 우린 지난주에 시작했어요."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "받아요, {name}. 언더시티 구슬을 타고 와서 좀 어지러워해요."
L["For you, {name}. It matches everything. I checked, obviously."] = "그대에게요, {name}. 어디에나 어울려요. 당연히 확인했죠."
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "구울이 막아서면, {name}, 실버문은 건재하다고 해요. 그 말 질색하거든요."
L["The Sunwell shines for us both, {name}."] = "태양샘은 우리 둘 모두를 비추지요, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "신도레이가 둘이라니, {name}. 오늘 하루가 두 배로 우아해졌네요."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "그대도요, {name}? 신도레이 둘에 거울은 하나. 번갈아 써야겠네요."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "불사조처럼요, {name}. 우린 계속 되살아나죠. 그것도 멋지게."
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "신도레이끼리 말인데요, {name}. 네, 호드는 시끄러워요. 네, 이젠 익숙해요."
L["Sin'dorei to sin'dorei, {name}: shall we pretend neither of us had a fel phase?"] = "신도레이끼리, {name}. 서로의 지옥 마력 흑역사는 모른 척해요."
L["Sunstrider or Farstrider, {name}, we all stride beautifully."] = "선스트라이더든 원정순찰대든, {name}, 우린 걸음걸이부터 우아하죠."
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "스컬지 이전의 쿠엘탈라스, 둘 다 기억하죠, {name}. 그 이후는 우리가 만들어요."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "보조 좀 맞춰 줘요, {name}. 우린 도착도 아름답게 하기로 유명하니까."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "조명 좋은 데 서요, {name}. 싸워야 한다면 근사해 보여야죠."
L["A party at last, {name}. I did dress for one."] = "드디어 파티네요, {name}. 파티 옷차림으로 왔거든요."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "태양은 우리 모두를 비춰요, {name}. 주로 나를 비추지만, 나눠 주긴 하죠."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "하나는 그대에게, {name}. 하나는 파티 이미지를 위해서. 그건 내가 맡았어요."
L["If I fall, {name}, arrange me attractively. The rest I leave to the healer."] = "내가 쓰러지면, {name}, 예쁘게 눕혀 줘요. 나머진 치유사한테 맡길게요."
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "마법 유물엔 아무도 손대지 마요, {name}. 음, 난 돼요. 교육받았거든요."
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "원정엔 순찰자가 필요하죠, {name}. 난 아니지만 장화는 있어요."
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "함께 싸우고 아름답게 전하죠, {name}. 전하는 건 내가 맡을게요."
L["The healer is to be thanked and the tank adored, {name}. Me, admired. Carry on."] = "치유사에겐 감사를, 탱커에겐 사랑을, {name}. 나에겐 감탄을. 계속해요."
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "일이 틀어지면, {name}, 스컬지 탓으로 해요. 전통이거든요."
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "마나 물약은 비상용이에요, {name}. 오늘만 비상사태가 열한 번이었죠."
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "잿더미에서도 걸어 나왔죠, {name}. 앞에 뭐가 있든 또 걸어 나갈 거예요."
L["The sun has risen, {name}, and so have I. We coordinate."] = "해가 떴어요, {name}. 나도 일어났죠. 우린 맞춰 움직이거든요."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "쿠엘탈라스의 새벽만은 못해도, {name}, 봐줄 만하네요. 겨우."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "아침 햇살이네요, {name}. 가장 잘 나오는 시간이죠. 물론 우리 둘 다."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "영원노래 숲의 아침은 과일, 차, 비전이죠, {name}. 비전부터 가요."
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "새벽이네요, {name}. 하늘 가득 붉은색과 금색. 누가 우릴 따라 했군요."
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "좋은 아침이에요, {name}. 이 시간에 깨어 있는 건 실버문 비전 수호자뿐이죠. 그리고 나."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "그 아량, 기록해 두죠, {name}. 세 부로. 수라마르는 벗을 잊지 않으니."
L["Most gracious, {name}. Allow me to repay you in kind."] = "참으로 고상하시군요, {name}. 같은 것으로 보답하지요."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "고마워요, {name}. 만 년을 보호막 아래 살아서, 이 말은 아직 연습 중이에요."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "대가 없는 선물이라니요? 궁정이 기절하겠군요. 고마워요, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "갚았어요, {name}. 우린 친절을 꼼꼼히 장부에 적거든요. 모욕도요."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "탈리스라 님께 그대 얘기를 하죠, {name}. 좋게 말이에요."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "친절하시군요, {name}. 수라마르라면 연회를 열었겠죠. 연 걸로 치세요."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "정식 감사 서한을 보내려 했지만, {name}, 이게 더 빠르겠더군요."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "엘리산드의 궁정에선 선물에 칼이 숨어 있었죠, {name}. 그대 건 아니네요. 고마워요."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "고마워요, {name}. 내 마나세이버가 그대를 인정했어요. 아무도 인정 안 하는 애가요."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "절묘하군요, {name}. 예전 같으면 '쓸 만하다' 했겠죠. 세상이 날 겸손하게 했어요."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "한때 굶주렸던 정신을 채워 줬군요, {name}. 그런 이는 결코 잊지 않아요."
L["Centuries of court etiquette, {name}, and 'thank you' still outperforms it all."] = "수백 년 궁정 예법도, {name}, '고마워요' 한마디를 못 이기네요."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "고마워요, {name}. 다음 가면무도회에 초대할게요. 가면은 필수예요."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "고마워요, {name}. 오큘레스라면 차원문부터 열었겠죠. 난 그냥 시전할게요."
L["Of course, {name}. A little arcane polish, just for you."] = "물론이죠, {name}. 그대만을 위한 비전의 광택을 살짝."
L["A reasonable request, {name}. Granted."] = "합당한 요청이군요, {name}. 들어드리죠."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "그러죠, {name}. 짧은 버전으로요. 긴 버전은 한 달이 걸리거든요."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "부탁이라니, 신선하군요. 궁정은 요구만 했거든요. 여기요, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "됐어요, {name}. 공짜로요. 엘리산드였다면 대가를 요구했을 거예요."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "됐어요, {name}. 절할 필요는 없어요. 가볍게 고개만 끄덕여 주면 좋겠지만."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "물론이죠, {name}. 대부분의 도시에 성벽도 없던 시절부터 갈고닦았거든요."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "들어드리죠, {name}. 대가를 청하고 싶지만, 덜 수라마르스럽게 사는 중이라."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "그러죠, {name}. 손짓이 과해도 이해해요. 수수하게는 안 되더군요. 해 봤어요."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "당장 하죠, {name}. 엘리산드는 시간을 멈췄지만, 난 1초면 돼요."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "물론이죠, {name}. 여기 지맥은 얕지만, 어떻게든 해 보죠."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "좋아요, {name}. 달빛 아래 서요. 아니면 저 등불 옆에. 등불도 돼요."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "당연하죠, {name}. 수라마르엔 모든 일에 주문이 있었죠. 몇 개는 기억나요."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "받으세요, {name}. 비전의 선물은 게으른 자에겐 낭비니까요."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "수라마르 비전의 불꽃 한 점이에요, {name}. 현명하게 쓰시길."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "마법 없이 지내 본 적이 있어요, {name}. 추천은 안 해요. 받으세요."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "보호막 밖 세상은 참 넓네요, {name}. 마법은 너무 부족하고. 여기요."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "비전술이 전통이지만, {name}, 들고 다니기엔 {buff} 쪽이 낫죠."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "받으세요, {name}. 수라마르의 환대를 거절하는 건 무례해요. 아주 무례하죠."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "여기요, {name}. 바깥에선 이렇게 인사한다더군요. 매력적인 풍습이에요."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "받으세요, {name}. 쌓아 둔 마법은 썩는 법이죠. 수라마르가 배웠듯이."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "예전 같으면 이걸 주고 절을 받았을 거예요, {name}. 우리 모두 컸죠."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "키린 토도 이걸 하죠, {name}. 기특하게도. 신참치곤 꽤 잘해요."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "보호막 아래서 온 선물이에요, {name}. 아주, 아주 오래 신선하게 보관했죠."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "즐겨요, {name}. 예전엔 귀족에게만 시전하던 거예요. 그대 쪽이 낫네요."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "바깥세상에 연회 가듯 짐을 쌌어요, {name}. 망토만 넷. 이거 받아요."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "여기요, {name}. 수라마르 솜씨죠. 과한 설계, 과한 장식, 그리고 완벽."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "여기요, {name}. 수라마르에선 현악 사중주가 딸려 나왔죠. 콧노래라도 불러 줘요."
L["Suramar's children shine together again, {name}."] = "수라마르의 자손들이 다시 함께 빛나는군요, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "샬도레이군요, {name}! 비전술 챙겼어요? 바깥 술은 그냥... 포도예요."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "수라마르 사람이군요, {name}. 바깥세상에 너무 감탄하지는 말아요."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "군단도 메마름도 버텨 냈죠, {name}. 나머진 잡담거리예요."
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "우리 재단사들도 수라마르를 빠져나왔죠, {name}. 별들에게 감사를."
L["We both remember going hungry, {name}. Never again, for either of us."] = "우리 둘 다 굶주림을 기억하죠, {name}. 다시는 없어요, 둘 다."
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "보호막 밖으로 나왔네요, {name}. 그대에게도 하늘이 아직 이렇게 커 보여요?"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "샬도레이가 둘이라니, {name}. 여기 사람들은 연회라도 열린 줄 알겠어요."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "원정이군요, {name}! 수라마르라면 허가증 여섯 장에 가면무도회까지 필요했죠."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "보호막이 우릴 지켜 줬죠, {name}. 이젠 서로가 지켜야죠. 기꺼이."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "모두에게 비전 마법을, {name}. 궁정은 낭비라 하겠지만, 난 동료애라 부르죠."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "나를 따라와요, {name}. 만 년 동안 발맞춰 걷는 연습을 했거든요."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "파티에선 마법을 나누는군요, {name}. 참 새롭네요. 꽤 마음에 들어요."
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "원정은 가면무도회 같아요, {name}. 웃고, 계속 움직이고, 칼을 조심하고."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "내 주문 빛 안에 있어요, {name}. 이 파티에서 제일 잘 받는 조명이에요."
L["After Elisande's court, {name}, a party of five is a holiday. Nobody plots."] = "엘리산드의 궁정에 비하면, {name}, 5인 파티는 휴가예요. 음모가 없으니."
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "길을 잃었어요? 빛나는 쪽을 따라와요, {name}. 나예요. 언제나 나죠."
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "내가 지맥 강의를 시작하면, {name}, 끊어 줘요. 정중하게요."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "내 백성이 메말라 가는 걸 봤어요, {name}. 벗은 안 보내요. 아무도 안 쓰러져요."
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "내가 거드름 피우면 말해 줘요, {name}. 가끔 잊어요. 천 년 단위로 살다 보니."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "드디어 밤이네요, {name}. 등불 몇천 개만 달면 거의 수라마르예요."
L["Under the dome it was always night, {name}. I feel quite at home."] = "보호막 아래선 늘 밤이었죠, {name}. 집에 온 기분이에요."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "별이 떴네요, {name}. 수라마르 별이 더 예뻤지만, 이 정도면 됐어요."
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "나이트본에게 밤이 왔네요, {name}. 드디어 시간대에 맞는 옷차림이에요."
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "이 시간이면, {name}, 수라마르는 이제 막 저녁 먹으러 차려입을 때였죠."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "햇빛이네요, {name}. 만 년을 보호막 아래 살아서, 아직도 깜짝 놀라요."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "이른 아침이네요, {name}. 궁정은 정오까지 잤죠. 전 개과천선 중이에요."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "좋은 아침이에요, {name}. 여기 태양은 참... 마법이 없네요. 대신 이걸 받으세요."
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "좋은 아침이에요, {name}. 수라마르엔 온갖 결계를 쳤는데, 해만 빠뜨렸죠."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "새벽이네요, {name}. 궁정 소문도 잠드는 시간이죠. 내 소문은 이거예요. 그대, 좋아 보여요."
L["A favour for a favour, {name}! Pleasure doing business."] = "호의엔 호의로, {name}! 거래 즐거웠다고!"
L["Thanks, {name}! Consider your account settled in full."] = "고마워, {name}! 이걸로 계산 끝, 완납이야!"
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "아이고, {name}. 청구서 쓰려다 감성에 젖어서 참는다. 금방 깰 거야."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "고마워, {name}! 깨알 같은 약관 찾아봤는데 없더라. 이상하네!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "이자까지 쳐서 갚는다, {name}. 이자는 빼고. 익숙해지진 마."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "고마워, {name}! 방금 VIP 고객으로 승급됐어."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "네 이름 딴 로켓을 만들고 싶은데, {name}, 내 로켓은 오래 못 가서. 고마워!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "원래 50골드 받는 건데, {name}. 퉁치자고."
L["Gave first, {name}? Bold business model. I'll match it. Don't tell Undermine."] = "먼저 줬다고, {name}? 대담한 사업 모델인데. 나도 맞춰 주지. 언더마인엔 비밀이다."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "양쪽 다 이득 보는 거래라니, {name}! 소문으로만 들었지. 실물은 처음이야."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "케잔 터진 뒤 첫 공짜 선물이다, {name}. 값 매기기 전에 돌려줄게."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "고마워, {name}! 감정가는 '값을 매길 수 없음'. 같은 감정가로 돌려준다."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "친절 넣고 친절 받고, {name}. 카자마이트 호황 이후 최고 수익률이야."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "공정 거래라고, {name}? 우리 회계사 방금 기절했다. 공정한 거래만 보면 저래."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "고마워, {name}! 악수하고 싶은데, 하고 나면 손가락을 세거든. 습관이야, 너 때문 아니고."
L["No haggling at all? Thanks, {name}. I feel cheated. In a nice way."] = "흥정도 없이? 고마워, {name}. 사기당한 기분이야. 좋은 쪽으로."
L["You got it, {name}! Time is money, friend!"] = "알았어, {name}! 시간은 금이라고, 친구!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "거래 성사, {name}! 외상으로 달아 둘게. 농담이야!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "바로 간다, {name}! 불만족 시 {buff} 전액 환불!"
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff} 나왔다, {name}! 팁은 선택. 권장. 선택."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "빠르게, 싸게, 좋게 중 하나? {name}, 오늘은 셋 다야. 소문내지 마."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "물론이지, {name}! 이번엔 폭발 없어, 약속해. 거의 약속해."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "너한텐 공짜야, {name}. 문서로 남기면 발뺌할 거지만."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "좋아, {name}! 견적은 0골드. 내 평생 최저 견적이야. 좀 쓰리네."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "나간다, {name}! 완전 보증 포함. 보증 기간은 효과 끝날 때까지."
L["Sure, {name}! Sign here, initial there... joking. Mostly. Hold still."] = "좋아, {name}! 여기 서명, 저기 날인... 농담이야. 거의. 가만있어."
L["Free of charge, {name}. If anybody from Bilgewater asks, you paid double."] = "공짜야, {name}. 빌지워터에서 누가 물으면, 두 배 냈다고 해."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "가젯잔은 물장사, {name}. 난 이 장사. 마진이 더 좋지."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "케잔 표준이야, {name}. 빠르고, 시끄럽고, 약관 읽기 전에 끝."
L["Order received, {name}! Delivery instant, wrapping optional, refunds imaginary."] = "주문 접수, {name}! 배송은 즉시, 포장은 선택, 환불은 상상 속에서."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "이건 서비스야, {name}. 무역왕한텐 비밀이다?"
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "최고급 상품, 수수료 없음, {name}. 오늘만이야!"
L["Free sample, {name}! If you like it, you know where to find me."] = "무료 샘플이야, {name}! 마음에 들면 어디로 오면 되는지 알지?"
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "자, {name}. 오늘 근처에서 뭐가 터지면, 이거랑은 무관한 거다."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "호감도 자산이지, {name}. 장부 채우는 셈 치고 {buff} 받아."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "받아, {name}. 안전 제일! 아니, 제삼인가. 목록 어딘가엔 있어."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "신기록으로 시전 완료, {name}! 기록 보유자는 나. 방금 세웠어."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "카자콜라는 아이디어를 주지, {name}. 나머진 이게 해 줘. 받아!"
L["Limited-time offer, {name}! Limited mostly by how long it lasts."] = "기간 한정 특가야, {name}! 한정 기간은 효과 지속 시간."
L["Free trial, {name}! No obligation. Well, a small emotional one."] = "무료 체험이야, {name}! 부담 없어. 마음의 빚 쪼금만."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "자, {name}. 특허 출원 중. 써 보고 부자 친구들한테 소문내."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "투자라고 생각해, {name}. 너한테. 영웅급 수익 기대한다."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "받아, {name}! 지난 화물이 케잔 앞바다에 가라앉아서 전부 떨이야."
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "투자개발회사는 이거 돈 받아, {name}. 난 경쟁사고. 자."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "고블린도 약한 구석이 있어, {name}. 내 건 작고 경비도 삼엄한데. 네가 찾았네."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "받아, {name}. 내 물건 중 유일하게 저당 안 잡힌 거야."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "넌 언젠가 부자 될 거야, {name}. 딱 보여. 이거 누가 줬는지 기억해 둬."
L["Anything for a fellow entrepreneur, {name}!"] = "동료 사업가를 위해서라면 뭐든지, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "케잔의 인재들이 다시 뭉쳤네, {name}. 지갑은 꽉 쥐고 있어."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "고블린이야, {name}? 그럼 이게 아주아주 드문 할인인 거 알지?"
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "고블린은 고블린끼리 챙겨, {name}. 경비 고용하는 것보다 싸거든."
L["Kezan's gone, {name}, but the hustle made it out. Look at us."] = "케잔은 사라졌지만, {name}, 장사 수완은 살아남았지. 우리 좀 봐."
L["Between goblins, {name}, this never happened. I have a reputation."] = "고블린끼리니까, {name}, 이건 없던 일이다. 나도 체면이 있어."
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "빌지워터든 스팀휘들이든, {name}, 우린 늘 위로 뜬다. 기름처럼."
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "화산 기억나, {name}? 우리 그거 입장권 팔았잖아. 좋은 시절이었지."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "단체 할인이야, {name}! 전원 반값. 공짜의 반값."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "내 계약 기간엔 아무도 못 죽어, {name}. 서류 작업이 지옥이거든."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "전리품은 공평하게 나누자, {name}. 계산은 내가 할게. 믿어."
L["Team-building, {name}! You make everybody stronger, and they all owe you."] = "팀 빌딩이야, {name}! 다들 세지고, 다들 너한테 빚지는 거지."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "뭉쳐 다니자, {name}. 용병은 골드가 들지만, 친구는 이거면 돼."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "전원 보호 완료, {name}. 보장은 아니고 보호야. 요금제가 달라."
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "이번 원정 위험 보고서 읽었어, {name}. 금방 읽더라. '안 돼' 한 줄이야."
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "큰 빨간 레버는 아무도 건드리지 마, {name}. 꼭 큰 빨간 레버가 있거든."
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "일 틀어지면, {name}, 나한테 로켓 있어. 1인승. 개선 중이야."
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "우린 이제 회사야, {name}. 난 회계 담당. 만장일치였어. 내 한 표로."
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "살아 있어, {name}. 부활 파는 법은 아직 아무도 못 찾았어. 연구 중이야."
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "붙어 있어, {name}. 이번 여행 이야기는 벌써 팔았거든. 재밌게 만들어 줘."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "일찍 일어나는 새가 골드를 번다, {name}! 공짜 하나. 다른 새들한텐 비밀."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "좋은 아침, {name}! 한 시간 뒤 장 열린다. 그때까진 인심 좀 쓰지."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "일찍 일어났네, {name}? 똑똑하군. 시간은 금인데, 아침이 제일 싸거든."
L["Up early, {name}? Me too. Rich goblins sleep in. I'm working on it."] = "일찍 일어났네, {name}? 나도. 부자 고블린은 늦잠 자는데. 노력 중이야."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "새 날엔 새 장부지, {name}. 첫 줄은 너야. 수입 칸에."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요. 주로 끈으로요."
L["How kind, {name}! You're on the caravan's good list now."] = "다정하셔라, {name}님! 대상단 좋은 친구 명단에 올렸어요."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "어머, 이건 간직할게요, {name}님! 전 뭐든 간직하거든요. 이건 드릴게요."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "고마워요, {name}님! 돌려드릴게요. 아니, 새 거예요. 거의 안 썼어요."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "방금 귀가 쫑긋 섰어요, {name}님. 아주 기쁘다는 뜻이에요."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "오늘 밤 모닥불 앞에선, {name}님, 이 얘기에 모래벌레가 나올 거예요. 고마워요!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "포장해 드리고 싶은데, {name}님, 포장지가 전부 누군가의 옛 지도라서요."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "알파카들이 봤어요, {name}님. 좋은 분이라고 여기저기 소문낼 거예요. 고마워요!"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "고마워요, {name}님! 제일 아끼는 단추를 드리려다, 이게 더 나아서요. 쪼끔."
L["Ooh, a present! Swapsies, {name}. Here's mine. No takebacks."] = "우와, 선물이다! 바꿔요, {name}님. 이건 제 거예요. 무르기 없기!"
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "고마워요, {name}님! 이건 좋은 주머니에 넣을게요. 돌 주머니 말고 좋은 거요."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "볼던이었으면 물주머니 하나는 줘야 했을 거예요, {name}님. 고마워요!"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "고마워요, {name}님! 마차에 이름 새길게요. 알파카랑 찌그러진 자국 사이에."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "사막도 친절만은 묻지 못했어요, {name}님. 고마워요."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "라케라가 그랬어요, {name}님. 어느 주머니에 뒀는지 잊기 전에 빨리 갚으라고. 여기요!"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "제가 먼저 파내지 않은 걸 받은 건 처음이에요, {name}님. 고마워요!"
L["Of course, {name}! Shake the sand out and hold still."] = "물론이죠, {name}님! 모래 좀 털고 가만히 있어요."
L["Coming right up, {name}! Caravan service, no waiting."] = "바로 갑니다, {name}님! 대상단 서비스, 대기 없음!"
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "그럼요, {name}님! 잠깐 찾아볼게요... 밧줄, 돌, 예쁜 돌... 여기 있다!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "잠깐만요, {name}님! 꼬리가 걸려서, 잠시만... 됐다!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} 하나요, {name}님! 모래가 살짝 묻었어요."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "불페라한테 부탁하면 뭐든 나와요, {name}님. 대개 이상한 게. 오늘은 빼고요!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "받으세요, {name}님! 불페라는 주는 걸 좋아해요. 줍는 거 다음으로요."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "여기요, {name}님! 제가 직접 기웠어요. 보기보다 튼튼해요."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "그럼요, {name}님! 바람 부는 쪽에 서요. 지난주 모래 폭풍이 아직 털에서 떨어져요."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "좋아요! 앗, {name}님, 너무 컸죠? 사막은 넓어서 소리쳐야 들리거든요."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "물론이죠, {name}님. 대상단 규칙이에요. 물이든 도움이든 두 번 청하게 하지 않기."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "바로요, {name}님! 작은 주문, 큰 여우, 더 큰 귀. 잠깐, 거꾸로다."
L["For you, {name}? Easy! Easier than getting sand out of an alpaca."] = "{name}님 부탁이면 쉽죠! 알파카 털에서 모래 빼기보단 쉬워요."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님. 확인했어요, 돌 아니에요."
L["Keep this, {name}. The desert is long and the water is short."] = "챙겨 가요, {name}님. 사막은 길고 물은 부족하니까."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "길에서 주웠어요, {name}님. 농담이에요! 새 거예요. 받으세요!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "여기요, {name}님. 제 짐 중에 최고예요. 짐이 엄청 많은데도요."
L["In the dunes you share your shade and your spells, {name}. Here."] = "사막에선 그늘도 주문도 나누는 법이에요, {name}님. 여기요."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "{name}님, {buff} 드릴게요. 흥정하고 싶지만 바빠 보이셔서."
L["A gift from the whole caravan, {name}! They'll never know."] = "대상단 모두가 드리는 선물이에요, {name}님! 다들 모르겠지만요."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "가는 길에 쓰세요, {name}님. 여행은 길이 최고예요. 길이랑 간식이요."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "여기요, {name}님! 모자를 뭔가랑, 그 뭔가를 이거랑 바꿨어요. 남는 장사!"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "사막에선 아무도 그냥 지나치지 않아요, {name}님. 재수 없고 무례하거든요. 여기요."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "제 코가 앞에 말썽이 있대요, {name}님. 이거 받아요. 제 코는 틀린 적 없어요."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "가방에 주문이 너무 많아요, {name}님. 짤랑거려요. 하나 가져가 주세요."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "나중에 반짝이는 거 찾으면, {name}님, 제 귀가 어디 있는지 아시죠? 여기요!"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "잠깐요, {name}님! 이거 두고 갈 뻔했어요. 사막은 그런 사람을 잡아먹어요."
L["Stew's not ready yet, {name}, so this is the starter."] = "스튜가 아직이에요, {name}님. 그러니 이건 애피타이저예요."
L["A fellow wanderer! The caravan is never far, {name}."] = "같은 방랑자네요! 대상단은 늘 가까이 있어요, {name}님."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "귀 쫑긋, {name}님! 같은 여우랑 주문 나누는 건 언제나 좋아요."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "불페라끼리 말인데요, {name}님. 여분 숟가락 세 개 있어요. 하나 드려요?"
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "우린 둘 다 볼던이 키웠죠, {name}님. 털엔 모래, 짐엔 행운."
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "귀 대 귀로 말인데요, {name}님. 우리 둘이면 여기서 나온 말은 다 들었을 거예요."
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "대상단 모닥불 기억나요, {name}님? 다들 노래는 엉망이었죠. 완벽했어요."
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "볼던은 멀리 두고 왔죠, {name}님. 절반은 우리 털에 묻어 따라왔지만요."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "대상단 규칙이에요, {name}님. 함께 다니기, 물 나누기, 알파카 팔지 않기."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "반짝이는 건, {name}님, 제가 먼저 봤어요. 대상단 법이에요."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "파티에 하나씩요, {name}님! 대상단은 제일 느린 알파카만큼만 빠르거든요."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "가방 잘 닫으세요, {name}님. 제가 가져가는 게 아니라 물건이 절 따라와요."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "도시에선 길을 잃어도 동굴에선 안 잃어요, {name}님. 월세 없는 집이거든요."
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "전 작으니까, {name}님, 작은 굴을 볼게요. 큰 굴은 다들 맡아 주세요."
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "필요한 거 있으면 불러요, {name}님. 아마 있을 거예요. 아마 찌그러졌겠지만."
L["I'll walk at the back and pick up whatever we drop, {name}. Finders keepers."] = "전 맨 뒤에서 떨어진 걸 주울게요, {name}님. 주운 사람이 임자!"
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "수레 없는 대상단이네요, {name}님! 빠르고 가볍고, 낮잠 잘 데가 없어요."
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "앞길 정찰 끝, {name}님. 코로요. 위험 냄새랑 아주 오래된 치즈 냄새가 나요."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "다들 밥 먹었죠? 물 마셨죠? 좋아요. 이제 이거요, {name}님. 대상단 순서예요."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "불페라는 밤에 다녀요, {name}님. 모래는 시원하고, 전갈은 졸리고."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "사막의 밤은 추워요, {name}님. 여기, 따끈... 아니, 미지근한 거요."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "별이 떴어요, {name}님. 읽을 줄 알면 전부 이정표래요. 전 못 읽어요."
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "여우한테 딱 좋은 시간이에요, {name}님. 조용할 때 귀가 제일 잘 들리거든요."
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "해 지니까 이제 깼어요, {name}님. 사막에선 한낮이 낮잠 시간이거든요."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "이따 꼬리 덮고 잘 거예요, {name}님. 제일 좋은 이불이죠. 그 전에 이거요."
L["A kindness returned is a kindness doubled, {name}."] = "돌려준 친절은 두 배가 되는 법이라네, {name}."
L["Thank you, {name}. You have restored my balance."] = "고맙네, {name}. 덕분에 내 균형이 돌아왔다네."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "어딘가에서 샤 하나가 굶게 됐구먼. 고맙네, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "고맙네, {name}. 아이사는 절을, 지는 환호를 했겠지. 난 둘 다 하겠네. 서툴게."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "고맙네, {name}. 다음 끼니 때 자넬 생각하겠네. 그다음 끼니 때도."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "첸이 늘 말했지. 선물은 거절 말라고. 술도. 고맙네, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "막 낮잠 자려던 참이었네, {name}. 그런데 이게 더 좋군. 조금. 고맙네."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "호젠이었다면 뭘 던졌을 걸세, {name}. 난 제대로 배웠지. 고맙네."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "참 판다렌다운 일일세, {name}. 만두 하나만 곁들이면 완벽하겠군."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "언덕골이었다면 상으로 순무를 받았을 걸세, {name}. 내 건 집에 두고 왔네. 고맙네."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "할머니는 친절을 항아리에 모으셨지, {name}. 자네 걸 넣고, 이걸 꺼내네."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "고맙네, {name}. 비취 숲에 오면 우리 집 문은 활짝, 찬장은 더 활짝일세."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "음영파처럼 움직이는군, {name}. 오는 줄도 몰랐네. 고맙네."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "논에 내린 단비 같군, {name}. 논은 고맙단 말을 안 하지만, 난 하네."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "고맙네, {name}. 리리라면 여행 일지에 적었을 걸세. 그림까지 그려서."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "고맙네, {name}. 천신들께서 바쁘시니, 네 분 몫까지 내가 인사하네."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "스톰스타우트 술은 판다렌도 뻗게 하지, {name}. 자네 친절도 그렇군. 고맙네."
L["Now we are square, {name}. The first time anyone has called a pandaren square."] = "이걸로 셈이 딱 맞았네, {name}. 판다렌한테 뭐가 딱 맞는 건 처음일세."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "물론이지, {name}. 조금만 참으면 다 된다네. 참는 게 느려서 그렇지."
L["With pleasure, {name}. A kind deed is never wasted."] = "기꺼이 하지, {name}. 선행은 결코 헛되지 않다네."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "당장 하지, {name}. 판다렌치고는 빠르게. 그래 봐야 별거 아니지만."
L["Master Shang Xi said: help whoever asks, {name}. He also said: duck."] = "샹 시 사부께선 청하면 도우라 하셨네, {name}. '숙여!'라고도 하셨고."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "투슈이 사부라면 명상부터 시켰을 걸세, {name}. 그건 건너뛰세."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "자네를 위해서라면 뭐든지, {name}. 마지막 만두만 빼고. 실없는 소린 말게."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} 한 잔, 진하게 우렸네, {name}. 비법은 비밀일세."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "학처럼 서게, {name}. 한 다리로, 평온한 얼굴로. 두 다리도 괜찮네."
L["We never refuse a request, {name}. Only second helpings. No, not those either."] = "부탁은 절대 거절 안 하네, {name}. 거절하는 건 한 그릇 더뿐... 아니, 그것도 안 하지."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "지난번에 도와 달라던 건 섬만 한 거북이었네, {name}. 자네가 훨씬 수월하군."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "판다렌은 요리하듯 돕지, {name}. 천천히, 넉넉히, 그리고 지나치게 많이."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "물론이지, {name}. 그릇 좀 내려놓고... 됐네. 이게 제일 어려운 부분이었지."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "그러지, {name}. 할아버지께선 손님이 두 번 청하게 하지 말라 하셨네. 두 번이나."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "가만있게, {name}. 나도 평온, 자네도 평온, 주문도 평온. 아무도 당황 말게."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "받게, {name}. 그리고 끝나면 차 한잔 어떤가?"
L["Balance in all things, {name}. Now go with a light heart."] = "모든 일엔 균형이라네, {name}. 이제 가벼운 마음으로 가게."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "받게, {name}. 그러믈이었으면 행운 부적 받고 팔았을 걸세."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "진유는 물이 이걸 예언했다 하더군, {name}. 늘 그 소리지만."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "후오진은 행동 먼저, 투슈이는 생각 먼저. 난 이것 먼저일세. 받게, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "판다렌이 일어나서까지 주는 걸세, {name}. 소중히 여기게."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "수도사처럼 싸우게, {name}. 차분히, 재빨리, 그리고 긴 점심."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "천천히 가게, {name}. 거북이는 한 번도 안 서둘렀어도 갈 곳에 닿았다네."
L["You looked like you needed a hug, {name}. This is next best, and less furry."] = "포옹이 필요해 보였네, {name}. 이건 그다음으로 좋은 걸세. 털도 덜 날리고."
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "싸움이 자넬 찾아오면, {name}, 굴러서 피하게. 구르기는 너무 저평가됐네."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "자네 주려고, {name}. 따뜻하고 둥글고 선의로 꽉 찼지. 나처럼."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "받게, {name}. 연이 나무에 걸려서 착한 일 할 시간이 생겼다네."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "판다리아에서부터 들고 왔네, {name}. 술통도 하나. 술통은 내 걸세."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "토깽이들이 내 당근은 훔쳐 갔지만, {name}, 이건 못 가져가지. 받게."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "유랑도에선 나그네에게 국을 대접하지, {name}. 이건 들고 다니기 더 좋네."
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "판다렌은 물렁해 보이지, {name}. 쌀가마니도 그렇다네. 자네 위로 떨어지기 전까진."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "치지께선 희망은 늘 있다 하셨지, {name}. 난 여분은 늘 있다 하네. 받게."
L["We must share a brew when the road allows, {name}!"] = "길이 허락하면 술 한잔 나누세, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "셴진 수도 흐뭇해할 걸세, {name}. 아니면 자는 중이거나. 구분이 안 가지."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "판다렌이 둘이나 모였군, {name}. 어디선가 여관 주인이 오싹했을 걸세."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "리우 랑도 좋아하겠군, {name}. 우리 둘 다 고향에서 멀리 왔으니."
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "투슈이든 후오진이든, {name}, 둘 다 거북을 떠났고, 둘 다 그곳 밥이 그립지."
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "판다렌끼리 말인데, {name}, 여기 술은 밍밍하네. 나중에 내 걸 나눠 마시세."
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "우리 둘 다 쌀술과 흙먼지 냄새가 나는군, {name}. 고향 냄새지."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "판다렌은 판다렌을 챙기지, {name}. 주로 먹여서. 이건 전채일세."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "싸움 다음에 밥일세, {name}. 그게 올바른 순서지. 절대 반대로는 안 되네."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "찜기 속 만두처럼 붙어 있게, {name}. 따끈하게, 준비된 채로."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "우린 한 몸처럼 움직이네, {name}. 좀 느릴지언정, 한 몸처럼."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "균형일세, {name}. 하나는 싸우고, 하나는 치유하고, 하나는 간식을 들지. 나."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "쓰러지면, {name}, 다 같이 쓰러져서 낮잠이나 자세. 아니, 그러지 마세."
L["Stay behind me, {name}. I am soft, but I am very wide."] = "내 뒤에 있게, {name}. 난 물렁하지만 품이 아주 넓다네."
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "이기면 내가 요리하지, {name}. 지면 그때도 요리하네. 울면서."
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "다들 숨 쉬게, {name}. 들이쉬고, 내쉬고. 이제 차분하게 패게."
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "따라오게, {name}. 내가 서두르는 중이네. 판다렌에겐 십 년에 한 번 있는 일이지."
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "파티는 술 빚기와 같네, {name}. 별난 재료가 섞여야 맛나지. 대개는."
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "내가 쓰러지면, {name}, 안전한 데로 굴려 주게. 업는 건 꿈도 꾸지 말고."
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "판다렌은 물처럼 싸우지, {name}. 고요히, 끈기 있게, 그러다 갑자기 사방에서."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "차보다 먼저 일어났나, {name}? 용감하군. 자, 차 대신 이걸 받게."
L["Morning, {name}. First this, then breakfast, then the second breakfast."] = "좋은 아침일세, {name}. 먼저 이거, 그다음 아침, 그다음 두 번째 아침."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "새날이 밝았네, {name}. 아직 아무도 뭘 쏟지 않았군. 살살 시작하세."
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "언덕골 농부들은 몇 시간 전에 일어났네, {name}. 난 몇 분 전에."
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "아침 안개로군, {name}. 꼭 고향 같았네. 코볼트가 지나가기 전까진."
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "좋은 아침일세, {name}. 배가 먼저 깨서 그때부터 계속 명령 중이네."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "첫 낮잠은 지났고 두 번째 낮잠 전일세, {name}. 깨어 있을 때 얼른."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "밤이 깊었네, {name}. 양조사들은 잠들었지. 술은 아직 안 자는 것 같네만."
L["Midnight snack time, {name}. This is the appetiser."] = "야식 시간일세, {name}. 이건 전채 요리고."
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "벌써 어두워졌나, {name}? 고향이었으면 할아버지 옛날이야기가 막 시작될 참이네."
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "오늘 밤 달은 둥글고 꽉 찼군, {name}. 나랑 닮은 데가 많네."
L["Your kindness is noted, {name}. Dragons do not forget."] = "그대의 친절, 새겨 두겠소, {name}. 용은 잊지 않소."
L["Thank you, {name}. Returned on swift wings."] = "고맙구려, {name}. 날랜 날갯짓으로 갚겠소."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "날개도 불도 비늘도 있는데, {name}, 그래도 도와주다니. 감동이구려."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "절이라도 하고 싶소, {name}. 지난번엔 날개로 식탁을 쓸어 버렸지만. 고맙소."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "곧장 내 보물 더미에 넣겠소, {name}. 내가 모으는 금은 선행뿐이오."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "난 무기로 만들어졌소, {name}. 이쪽이 훨씬 마음에 드오. 고맙소."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "고맙소, {name}. 래시온이었다면 연설을 했을 거요. 난 안 하겠소."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "불기를 살짝 담아 돌려드리오, {name}. 아주 살짝. 연습 중이라."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "필멸자의 선물이구려, {name}. 작고, 짧고, 다정하오. 셋 다 좋아지는 중이오."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "고맙소, {name}. 필멸자 풍습은 낯설구려. 값을 치러야 하오? 아니오? 그럼 이걸로."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "고맙소, {name}. 마음 대신 비늘이 있는 몸인데, 그걸 뚫고 들어왔소."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "그대는 '아끼는 필멸자' 명단에 올랐소, {name}. 오늘까지 비어 있던 명단이오."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "내 안의 붉은 용은 고맙다 하고, {name}, 검은 용은 수상하다 하오. 붉은 용 승."
L["Thank you, {name}. My wings would clap, but wings don't do that. I checked."] = "고맙소, {name}. 날개로 박수라도 치고 싶소만, 날개는 그게 안 되오. 해 봤소."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "용의 감사엔 포효가 따르는 법이오, {name}. 이웃을 생각해 생략하리다."
L["Very well, {name}. Stand still, I would hate to singe you."] = "알겠소, {name}. 가만히 계시오. 그을리게 하고 싶진 않으니."
L["Granted, {name}. A dragon keeps its word."] = "들어주겠소, {name}. 용은 약속을 지키는 법."
L["Certainly, {name}. Stand clear of the tail."] = "그러겠소, {name}. 꼬리에서 떨어져 계시오."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "물론이오, {name}. 요즘도 이렇게 하는 거요? 잠깐 눈 좀 붙였더니만."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "기꺼이, {name}. 내 안의 다섯 용군단이 만장일치로 찬성이오."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "당장 하리다, {name}. 용만 한 도움을, 들고 다니기 좋은 크기로."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "물론이오, {name}. 넬타리온은 명령만 했지. 부탁이 훨씬 낫구려."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "당장 하리다, {name}. 조금 물러서시오. 내 덩치를 아직 익히는 중이라."
L["Certainly, {name}. Hold still. I have excellent aim and very little practice."] = "그러겠소, {name}. 가만히 계시오. 조준은 뛰어나오. 연습이 모자랄 뿐."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "물론이오, {name}. 원래 용은 공물을 받소. 이번 한 번은 면제해 드리리다."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "물론이오, {name}. 비명은 참아 주시오. 필멸자들이 자주 지르더군. 뿔 때문이오."
L["My breath is fire, {name}, so we will do this the other way."] = "내 숨결은 불이오, {name}. 그러니 이건 손으로 하겠소."
L["Gladly, {name}. In my day... no. I promised to stop saying 'in my day'. Here."] = "기꺼이, {name}. 나 때는 말이야... 아니, 그 말은 끊기로 했소. 여기."
L["A small magic, {name}, but I cast it with enormous dignity."] = "작은 마법이오, {name}. 하지만 엄청난 위엄을 담아 시전하오."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오. 이리 아담한 용이면 더더욱."
L["A gift from the Dragon Isles, {name}. Fly well."] = "용의 섬에서 온 선물이오, {name}. 멋지게 날기를."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "알렉스트라자께선 모든 생명이 소중하다 하셨소, {name}. 그대부터 시작하리다."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "만 년 치 선행을 자느라 놓쳤소, {name}. 지금 몰아서 하는 중이오."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "용이 해 줬다고 전하시오, {name}. 실제보다 훨씬 그럴싸하게 들리니."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "비늘사령관의 명령이오, {name}. 내가 비늘사령관은 아니지만, 아무튼."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "받으시오, {name}. 고대 용의 마법이오. 유통기한이 살짝 지났지만."
L["A dragon giving, {name}, not taking. I am trying something new."] = "용이 빼앗지 않고 베푸는 거요, {name}. 새로운 시도랄까."
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "사람 모습일 땐 무해해 보이오, {name}. 프레스터 여공도 그랬지. 난 진짜 무해하오."
L["A gift from above, {name}. I landed specially. It took two tries."] = "하늘에서 온 선물이오, {name}. 일부러 내려앉았소. 두 번 만에."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "받으시오, {name}. 용이라면 지킬 보물이 있어야 하오. 당분간은 그대로 정했소."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "받으시오, {name}. 다섯 용군단 합작이라 무슨 옷과도 색이 안 맞소."
L["I'd fly you there myself, {name}, but I'm told that is 'kidnapping'. Take this."] = "직접 태워 가고 싶소만, {name}, 그건 '납치'라더군. 이걸 받으시오."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "용들은 세상이 열릴 때 선물을 주었소, {name}. 내 건 좀 작고, 좀 늦었소."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "정수를 조금 드리오, {name}. 내 몸을 이루는 거니 살살 다뤄 주시오."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "받으시오, {name}. 따뜻할 거요. 내 손이 닿으면 대개 그렇소."
L["The Forbidden Reach feels far behind us now, {name}."] = "이제 금지된 해안도 먼 옛일 같구려, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "드랙티르 둘이 한자리라니, {name}. 날개 조심하시오. 날개 넷 펼 자리는 없소."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "세상 모든 게 낯설던 때 기억하오, {name}? 사실 아직도 대부분 낯설지만."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "사람 모습일 땐 아무도 모르지, {name}. 우리끼리 얘긴데, 비늘이 더 멋지오."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "전쟁용으로 빚어진 우리가, {name}, 나눔이라니. 누군가의 계획이 망했구려."
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "사람 모습이든 비늘이든, {name}, 동족은 어디서든 알아보오. 자세만 봐도 알지."
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "필멸자들은 늘 같은 걸 묻소, {name}. 태워 줄 수 있냐고. 여전히 안 되오."
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "드랙티르끼리 하는 말인데, {name}, 뿔 달고 모자 쓰기는 영영 안 쉬워지오."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "불 뿜을 때가 되면 말해 주시오, {name}. 뿜지 말아야 할 때도 꼭."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "눈 떠 보니 낯선 이들 가득한 동굴이었소, {name}. 여기가 훨씬 낫구려."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "넬타리온은 우릴 홀로 싸우도록 빚었소, {name}. 설계는 우리가 고쳤지."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "내 꼬리는 피하시오, {name}. 아직 누구 편인지 모르는 녀석이라."
L["A flight of our own, {name}. So this is what the dragons meant."] = "우리만의 용군단이오, {name}. 용들이 말하던 게 이런 거였구려."
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "내가 '엄폐'라 하면, {name}, 내 날개 뒤로 오란 뜻이오. 그러라고 있는 날개요."
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "옆에 서시오, {name}. 앞은 절대 안 되오. 내 숨결은 예의 바르게 조준이 안 되오."
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "큰 놈은 내게 맡기시오, {name}. 아, 나보다 작은 놈만. 그래도 대부분이오."
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "가까이 있으시오, {name}. 어디서든 다 같이 활강해 내려가 주겠소. 올라가는 건 알아서들."
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "계속 움직이시오, {name}. 서두르는 용은 웅장하오. 기다리는 용은 그냥 크기만 하오."
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "작전은 천천히 말해 주시오, {name}. 난 전투용이지 작전용이 아니오."
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "필멸자의 삶은 짧소, {name}. 오늘을 더 짧게 만들진 맙시다."
L["It is good to see one of our own, {name}."] = "동족을 만나니 반갑구려, {name}."
L["Our people are few, {name}. That makes each of us count."] = "우리 동족은 수가 적소, {name}. 그래서 하나하나가 소중하오."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오. 오늘은 나였구려."
L["Kindness answered, {name}. For the Alliance!"] = "호의에 보답하오, {name}. 얼라이언스를 위하여!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "스톰윈드엔 영웅마다 동상이 있소, {name}. 그대 동상도 건의해 두겠소."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "얼라이언스 방식이오, {name}. 그대가 돕고, 내가 돕고, 술은 드워프가 사고."
L["Genn would growl, Muradin would hug, {name}. I'll just return it."] = "겐이라면 으르렁, 무라딘이라면 와락. 난 그냥 갚겠소, {name}."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "얼라이언스가 예의 훈장을 준다면, {name}, 휘장이 하나 더 필요하겠구려."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "고스란히 갚았소, {name}. 먼저 베푸는 동료는 수비대 하나와 맞먹소."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "고맙소, {name}. 집에 보낼 편지에 쓰겠소. 어머니가 온 동네에 읽어 주시거든."
L["The Lion's Pride will hear of this, {name}. At length. Thank you."] = "사자의 자존심 여관에 소문내겠소, {name}. 아주 길게. 고맙소."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "이게 얼라이언스의 참모습이오, {name}. 아무도 청하지 않았는데 누군가 도왔지. 고맙소."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "깊은굴 지하철 승객 모두에게 말하겠소, {name}. 아주 긴 열차요. 고맙소."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "참으로 기사답구려, {name}. 내 휘장에 사자가 있었다면 가르랑거렸을 거요."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "왕들은 티격태격해도, {name}, 백성끼리는 사이가 참 좋소. 고맙소."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "얼라이언스는 약속을 지킨 이들이 세웠소, {name}. 내 약속은 이렇게 지키오."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "당연하오, {name}. 동맹은 서로 돕는 법. 이름부터 얼라이언스 아니오."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "곧바로 하겠소, {name}. 얼라이언스는 벗을 외면하지 않소."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "물론이오, {name}. 얼라이언스 헌장에 있는 조항이오. 한참 뒤쪽 어딘가에."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "얼라이언스 명령이오, {name}. {buff} 1건, 즉시 발효."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "동맹을 위해선 뭐든 하오, {name}. 상식선에서. 이건 충분히 상식선이오."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "당장 하겠소, {name}. SI:7은 그대가 부탁할 줄 알았다더군. 난 방금 알았소."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "곧바로 하겠소, {name}. 얼라이언스는 이런 부탁을 먹고 진군하오. 빵도 먹고."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "그러겠소, {name}. 스톰윈드부터 아이언포지까지, '부탁'이면 모든 성문이 열리오."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "당장 하겠소, {name}. 누가 부탁하길 바라며 온종일 파란 옷 입고 기다렸소."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "가만히 계시오, {name}. 이건 얼라이언스 찬가보다 빨리 익혔소."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "물론이오, {name}. 전쟁은 군대가 이기고, 동맹은 작은 친절이 얻소. 여기 하나."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오. 이제 더 굳건히."
L["Onward, {name}. The Alliance is with you."] = "전진하시오, {name}. 얼라이언스가 함께하오."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "받으시오, {name}. 노움이 만들었다면 레버가 열두 개는 달렸을 거요."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "얼라이언스가 드리는 거요, {name}. 2차 대전쟁 때부터 해 온 일이지."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "고개 드시오, {name}. 스톰윈드 어딘가서 음유시인이 이 얘길 쓰는 중이오."
L["Every ally counts, {name}. I counted, actually. You're my favourite so far."] = "동료 하나하나가 소중하오, {name}. 세어 봤는데, 아직까진 그대가 최고요."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "안두인이라면 나누라 했을 거요, {name}. 그분을 실망시킬 순 없지."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "받으시오, {name}. 스톰윈드 성벽은 따라갈 수 없으니, 이게 대신 가오."
L["Here, {name}. The gryphons get you there; this gets you back."] = "받으시오, {name}. 가는 건 그리핀이, 돌아오는 건 이게 책임지오."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "얼라이언스 규칙이오, {name}. 약속도, 성벽도, 벗도 지킬 것. 받으시오, 벗이여."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "동료라면 등 뒤에 사자 하나쯤 있어야지, {name}. 제일 가까운 사자가 나요."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "얼라이언스의 선물이오, {name}. 서명하고, 봉인하고, 직접 전해 드리오."
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "얼라이언스는 용사를 잊지 않소, {name}. 기억할 거리를 만들어 주시오."
L["Together we stand, {name}. For the Alliance!"] = "뭉쳐야 사는 법이오, {name}. 얼라이언스를 위하여!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "자, {name}. 방패는 들고, 고개는 숙이고, 작전보다 먼저 돌격하는 자 없기요."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "얼라이언스 역사상 최고의 부대요, {name}. 적어도 제일 가까이 있는 부대."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "모이니 거의 연대 규모요, {name}. 작지만 옷 잘 입은 연대."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "서로 등을 지켜 주시오, {name}. 얼라이언스는 그런 이들이 세운 거요."
L["Shields together, {name}. The Alliance never won anything in single file."] = "방패를 맞대시오, {name}. 얼라이언스가 한 줄로 서서 이긴 적은 없소."
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "역사책에 실린다면, {name}, 각주 말고 한 장을 차지합시다."
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "깃발 드는 자는, {name}, 초상화에 멋지게 그려지오. 지원자?"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "드워프의 배짱, 엘프의 인내, 인간의 고집. {name}, 이게 얼라이언스 비법이오."
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "사자답게 포효하시오, {name}. 속삭이듯. 잠입 중이오."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "힘과 명예, {name}. 알고 보니 친절도 있구려. 고스란히 갚았소."
L["The Horde takes care of its own, {name}."] = "호드는 제 식구를 챙기는 법이오, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "힘을 받았으면 힘으로 갚소, {name}. 호드 외교는 그게 전부요."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "오그리마 성문에 그대 이름을 새기고 싶지만, {name}, 빈자리가 없소. 고맙소."
L["Gallywix would've sent you an invoice, {name}. I'm sending this instead."] = "갤리윅스였다면 청구서를 보냈을 거요, {name}. 난 대신 이걸 보내오."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "안 해도 될 일이었소, {name}. 그래서 호드는 이걸 기억하오."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "호드는 고맙단 말을 두 번 하지 않소, {name}. 그러니 한 번, 진심으로."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "호드에선 빚도 도끼처럼 들고 다니오, {name}. 드러내 놓고, 오래 들지 않고."
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "성문 경비병들에게 그대 얘길 하겠소, {name}. 으르렁댈 거요. 존경한다는 뜻이오."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "호드는 명단이 둘이오, {name}. 원한과 은혜. 그대는 짧은 쪽이오."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "명예는 갚으라 하고, {name}, 예의는 웃으라 하오. 웃는 건 연습 중이오."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "내가 탄 어느 비행선보다 부드럽게 내려앉았소, {name}. 고맙소."
L["Thanks, {name}, in Orcish, Zandali, Thalassian and Gutterspeak. Pick one."] = "고맙소, {name}. 오크어, 잔달라어, 탈라시스어, 저속어로. 골라 들으시오."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "스랄은 호드에 명예를 가르쳤소, {name}. 그대는 배울 필요도 없었구려. 고맙소."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "먼저 베풀었구려, {name}. 호드에선 그러면 고기 첫 점이 그대 거요. 여기."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "대족장이 모두에게 직접 인사할 순 없소, {name}. 그래서 내게 위임했소."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "맡겨 두시오, {name}. 호드를 위하여, 그리고 예의 바른 모두를 위하여."
L["You only had to ask, {name}. The Horde answers."] = "말만 하면 되오, {name}. 호드는 응답하오."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "호드는 보통 도끼로 돕소, {name}. 오늘은 도끼 대신 {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "됐소, {name}. 연설은 생략하오. 호드엔 이미 차고 넘치니."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "청했으니 됐소, {name}. 오그리마에선 그게 정식 조약이오."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "청하는 건 약함이 아니오, {name}. 동료를 거절하는 게 약함이지."
L["No need to bang a war drum, {name}. You asked; it's done."] = "전쟁 북까지 칠 필요 없소, {name}. 청했으니 된 거요."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "물론이오, {name}. 호드에서 '부탁'보다 높은 건 대족장뿐이오."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "오그리마였으면 먼저 한바탕 싸웠을 거요, {name}. 전통이지. 여기."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "징발한 걸로 치시오, {name}. 병참장교는 몰라도 되오."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "됐소, {name}. 누가 물으면 내내 인상 쓰고 있었다 하시오. 내 평판이 있어서."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "물론이오, {name}. 호드식 환대요. 투박해도 양은 푸짐하지."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "호드는 누군가 늘 승낙했기에 뭉쳤소, {name}. 나도 승낙하오."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "호드를 위하여, {name}! 힘이 함께하기를. 방금 좀 넣어 드렸소."
L["Go with honour, {name}. Victory awaits."] = "명예롭게 가시오, {name}. 승리가 기다리오."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "노래가 될 일을 하시오, {name}. 시끄러운 노래로. 호드는 시끄러운 게 좋소."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "당당히 걸으시오, {name}. 호드는 늘 세상이 외면한 이들을 품었소."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "받으시오, {name}. 호드의 지혜도 하나. 먼저 치고, 사과는 하지 마시오."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "승리 아니면 죽음이오, {name}. 난 승리가 좋으니, 이걸 받으시오."
L["Like a mak'gora, {name}, except everybody wins. Here."] = "막고라 같은 거요, {name}. 다만 모두가 이기지. 받으시오."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "호드를 위하여, {name}, 그리고 그대를 위하여. 호드는 크고, 그대는 가깝소."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "받으시오, {name}. 뭉치면 강하다지. 내 몫은 방금 했소."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "이걸 지니시오, {name}. 호드 깃발보다 가볍고, 휘날림은 똑같이 당당하오."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "받으시오, {name}. 호드는 제 식구를 먹이고, 무장시키고, 이제 마법까지 걸어 주오."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "받으시오, {name}. 저 밖에 뭐가 있든 곧 호드를 만나게 될 거요."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "받으시오, {name}. 어디로 가든 호드가 보낸 사람처럼 도착하시오."
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "크로스로드는 나그네를 내친 적이 없소, {name}. 바가지는 좀 씌웠어도."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "호드는 강하게 키우오, {name}. 이건 강한 걸로 모자란 날을 위한 거요."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "받으시오, {name}. 호드식 선물이오. 리본 없음, 연설 없음, 환불 없음."
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "허리 펴시오, {name}. 더. 호드엔 키를 맞춰야 할 타우렌이 있소."
L["Our strength is each other, {name}. For the Horde!"] = "우리의 힘은 서로에게 있소, {name}. 호드를 위하여!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "전진하시오, {name}. 호드는 함께 전진하오. 후퇴는... 공식적으론 없소."
L["Together we're a war band, {name}. Apart, we're just loud."] = "뭉치면 전투부대요, {name}. 흩어지면 그냥 시끄러운 무리고."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "어깨를 나란히, {name}. 먼저 돌격하는 자가 술을 사는 거요."
L["Nobody gets left behind, {name}. I've counted us twice."] = "낙오자는 없소, {name}. 두 번이나 세어 봤소."
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "전투부대 규칙이오, {name}. 모두 돌아오기 전엔 아무도 안 먹소."
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "북을 울리시오, {name}. 조용히 못 할 바엔 무시무시하게 갑시다."
L["The Horde never won a thing alone, {name}. Let's not start now."] = "호드는 혼자서 이긴 적이 없소, {name}. 지금 시작하지도 맙시다."
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "호드답게 싸웁시다, {name}. 한꺼번에, 신호 따윈 아무도 기다리지 않고."
L["Right, {name}. Loot shared, blame shared, glory to whoever shouts first."] = "좋소, {name}. 전리품도 나누고 책임도 나누고, 영광은 먼저 외친 자의 것."
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "우릴 보시오, {name}. 대족장도 자랑스러워할 거요. 약간. 멀리서."
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "엄니, 뿔, 긴 귀, 앙상한 뼈라, {name}. 이만한 전투부대도 없소."
L["The war stories get bigger after, {name}. Let's give them a head start."] = "무용담은 끝나면 커지기 마련이오, {name}. 처음부터 크게 갑시다."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "고맙소, {name}. 선한 마음은 어느 편에나 있다더니, 여기도 있구려."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "고맙소, {name}. 편도 직함도 없이 친절 하나. 전설은 이렇게 시작하오."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "고맙소, {name}. 친절엔 진영이 없소. 마침 나도 없으니 잘됐구려."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "고맙소, {name}. 어느 편이 그대를 데려가든 횡재하는 거요."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "결국 어느 편에 서든, {name}, 그대를 제일 먼저 기억하리다. 고맙소."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "철저히 중립이오, {name}. 하지만 감사는 예외지. 고맙소."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "고맙소, {name}. 깃발을 안 드니 두 손 다 비어서 갚기 좋소."
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "스팀휘들 무역회사는 돈 때문에 중립이오, {name}. 난 이런 순간 때문이고."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "어느 편도 아직 감사 인사법을 안 알려 줬소, {name}. 그러니 담백하게, 고맙소."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "고맙소, {name}. 두 거대한 깃발 사이에 선 나를 알아봐 주다니."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "두 진영은 전쟁 중인데, {name}, 우린 한복판에서 훈훈하구려. 고맙소."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든. 난 깃발도 없지만."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "물론이오, {name}. 난 누구든 돕소. 그거 하나는 정했소."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "다들 어느 편이냐고만 묻더군, {name}. 도와 달란 말이 훨씬 반갑소."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "물론이오, {name}. 물어볼 전쟁 회의도 없소. 나 혼자고, 난 찬성이오."
L["Here you are, {name}. No oath, no colours, no fee."] = "여기 있소, {name}. 맹세도, 깃발도, 수수료도 없이."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "아직 편은 못 고르오, {name}. 하지만 좋은 일은 고를 수 있지. 이게 그거요."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "당장 하겠소, {name}. 설 편이 없으니, 지금은 온전히 그대 편이오."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "물론이오, {name}. 돈 받고 편드는 일은 없으니, 부탁이나 들어주오."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "중립이 무심하단 뜻은 아니오, {name}. 먼저 돕고 절대 안 따진단 뜻이지."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "벗은 어느 편에서든 오는 법이오, {name}. 나처럼 아무 편도 아닌 데서도."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "곧 우리도 휘장을 받겠지, {name}. 그때까진 서로 챙깁시다."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "아직 편을 안 골랐소, {name}. 그래서 양쪽 다 잘해 주는 중이오. 받으시오."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "아무 조건 없는 선물이오, {name}. 조건 걸 진영도 없는 몸이라."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "어서 가시오, {name}. 두 진영이 우릴 두고 다툴 날만 기다리오."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "아직 병참장교가 없어 아무도 안 세오, {name}. 넉넉히 받으시오."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "받으시오, {name}. 난 중립 지대를 달고 다니오. 그대는 지금 그 위에 서 있소."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "은빛 여명회는 필요한 이라면 누구든 돕소, {name}. 최고에게 배우는 중이오."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "무법항 규칙은 부두에서 싸움 금지요, {name}. 내 규칙은 선물 거절 금지."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "두 진영이 유일하게 뜻을 모을 물건이오, {name}. 본인들만 아직 모르지."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "어느 휘장에도 어울리오, {name}. 확실히 하려고 색을 아예 안 넣었소."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "받으시오, {name}. 오그리마도 스톰윈드도 안 보낸 거요. 그래도 효과는 좋소."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "받으시오, {name}. 아직 속한 나라가 없어서, 모두의 편이 되는 연습 중이오."
L["Side by side, {name}, whatever comes."] = "어깨를 나란히, {name}. 무엇이 닥치든."
L["No flag over this party, {name}, just us. That's plenty."] = "이 파티엔 깃발 대신 우리가 있소, {name}. 그걸로 충분하오."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "편 가르기는 나중에, {name}. 오늘은 함께 적을 가릅시다."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "세상이 어느 편에 서든, {name}, 난 이 파티 편이오."
L["Neutral in the war, {name}, but very partial to this group."] = "전쟁에선 중립이오, {name}. 하지만 이 파티엔 대놓고 편파적이오."
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "우릴 중립 파티라 부르더군, {name}. 조용한 파티라곤 안 했소."
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "오늘 누구랑 싸우든, {name}, 사적인 감정은 없소. 아주 철저할 뿐."
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "이 파티엔 편이 하나요, {name}. 우리 편. 아제로스에서 가장 작고, 가장 좋은 진영."
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "어느 수도의 명령도 없소, {name}. 길은 우리가 고르오. 빨리 고릅시다."
L["No war to win today, {name}, just this one fight. Much more manageable."] = "오늘 이길 전쟁은 없소, {name}. 이 전투 하나뿐. 훨씬 할 만하오."
L["One good turn deserves another, {name}."] = "은혜는 은혜로 갚는 법이오, {name}."
L["Have some {buff} in return, {name}."] = "답례로 {buff} 받으시오, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "친절은 오가야 하는 법, {name}. 고맙소."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "그대가 먼저 했으니, {name}, 내가 이어받으면 그게 우정이오."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "노래라도 지어 드리고 싶소만, {name}, {buff} 쪽이 음정은 덜 틀리오."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "선물엔 선물로, {name}. 이 기세면 저녁때쯤엔 천하무적이겠소."
L["All square, {name}. Unless you'd like to make it best of three."] = "이걸로 비겼소, {name}. 삼세판으로 가자면 몰라도."
L["You started it, {name}. I'm only finishing it."] = "먼저 시작한 건 그대요, {name}. 난 마무리만 하는 거고."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "고마운 일이오, {name}. 하루가 확 나아졌소. 이건 내 쪽 답례요."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "막 그대에게 해 주려던 참이었소, {name}. 진짜로. 여기 증거요."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "고맙소, {name}. 오늘 밤은 더 푹 자겠소. 도랑에서 자는 몸이지만."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "오늘 좋은 일이 둘이오, {name}. 그대의 친절, 그리고 그걸 갚을 기회."
L["You had me in your debt for all of three seconds, {name}. There."] = "내가 그대에게 빚진 시간은 고작 3초였소, {name}. 자, 갚았소."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "감사는 식기 전에 내야 제맛이오, {name}. 여기, 아직 따끈하오."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "이런, {name}, 이제 온종일 착하게 살아야 하잖소. 고맙구려."
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "허리 숙여 답례하오, {name}. 마음으로만. 허리가 예전 같지 않아서."
L["Thank you, {name}. I'd hoped somebody would start. I'm hopeless at starting."] = "고맙소, {name}. 누가 먼저 해 주길 바랐소. 난 먼저 하는 데 영 소질이 없어서."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "고맙소, {name}. 아침 먹다 포기한 하루를 그대가 살렸소."
L["You asked, {name}, and here it is."] = "청하신 대로요, {name}. 여기 있소."
L["{buff}, coming right up, {name}."] = "{name}, {buff} 바로 대령하오."
L["Gladly, {name}. One moment."] = "기꺼이 하리다, {name}. 잠시만 기다리시오."
L["Asked and answered, {name}. Next question?"] = "묻는 말에 답했소, {name}. 다음 질문?"
L["Say the word and it's yours, {name}. You said several. Here."] = "말 한마디면 그대 것이오, {name}. 몇 마디나 했으니, 여기."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "그대를 위해서라면, {name}, 기꺼이. 누가 부탁하길 기다렸소."
L["Of course, {name}. Easiest yes I'll say all day."] = "물론이오, {name}. 오늘 이보다 쉬운 대답은 없을 거요."
L["Right away, {name}. Finally, a question I know the answer to."] = "바로 하리다, {name}. 드디어 답을 아는 질문이 나왔구려."
L["Of course, {name}. Nobody asks me for anything these days. This is lovely."] = "물론이오, {name}. 요즘 내게 부탁하는 이가 없었소. 이거 참 좋구려."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "가만히 계시오, {name}. 꼼지락대지 않는 사람에게 잘 듣소. 그런 사람은 없지만."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "여기 있소, {name}. 뜸 들이면 극적이겠지만, 그건 실례라."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "좋소, {name}. 더 일찍 물었으면 더 일찍 답했을 거요."
L["Say no more, {name}. Well, say thank you. Then no more."] = "두말하면 잔소리요, {name}. 아, '고맙소'까진 하시오. 그다음은 됐소."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "됐소, {name}. 다음엔 묻지 말고 내 옆에서 초롱초롱한 눈빛만 보내시오."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "바로 가오, {name}. 오늘 하루 중 계획대로 되는 건 이것뿐이오."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "좋게 부탁하면 통하오, {name}. 널리 알리시오. 세상에 필요한 소식이오."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "당장 하리다, {name}. 가만있으시오. 안 그러면 그림자가 대신 받소."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "무사히 가시오, {name}. {buff}만큼 가벼운 짐도 없소."
L["A small blessing for the road, {name}."] = "가는 길에 작은 축복을, {name}."
L["Go well, {name}, and come back in one piece."] = "잘 다녀오시오, {name}. 몸 성히 돌아오고."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "이유는 없소, {name}. 그냥 {buff} 기분인 날이오."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "신경 쓰지 마시오, {name}. 남는 {buff} 들고 지나가던 길이오."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "선물이라 생각하시오, {name}. 포장하려 했는데 종이 너머로 빛이 새서."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "여기, {name}. 필요한 이를 만나면 그대도 건네주시오."
L["Whatever brings you here, {name}, may it go better than planned."] = "무슨 일로 왔든, {name}, 계획보다 잘 풀리길 바라오."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "이웃사촌끼리 정 나누는 거요, {name}. 아주아주 잠깐 이웃이지만."
L["You looked about to do something brave, {name}. Here, for that."] = "뭔가 용감한 일을 벌일 얼굴이구려, {name}. 그 일에 보태 쓰시오."
L["No need to stop, {name}. It works while you walk."] = "멈출 필요 없소, {name}. 걸으면서도 잘 듣소."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "청한 것도, 갚을 것도 없소, {name}. 남은 건 가서 멋지게 구는 것뿐."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "내기라 칩시다, {name}. 그대가 이걸로 뭔가 해낸다는 쪽에 걸었소."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "지나가던 나그네의 선물이오, {name}. 옛이야기에선 그게 최고의 선물이라오."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "인사도 없이 지나치는 건 실례요, {name}. 이게 내 인사요."
L["I'm not following you, {name}. We're just going the same way. Here."] = "따라오는 거 아니오, {name}. 가는 방향이 같을 뿐이오. 자, 받으시오."
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "오늘 잘 풀리면, {name}, 날 기억하시오. 망하면 난 여기 없었던 거요."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "잠깐 가만히, {name}. 됐소. 이 근방에서 제일 준비된 사람이오."
L["Everyone ready? You are now, {name}."] = "모두 준비됐소? 이제 {name}도 준비됐소."
L["A little something for the party, {name}."] = "파티를 위한 작은 선물이오, {name}."
L["Stay close, {name}. We go further together."] = "가까이 붙어 있으시오, {name}. 함께라면 더 멀리 가오."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "우리 규칙이오, {name}. 죽지 말 것, 삐치지 말 것, 끝나면 다 같이 밥 먹을 것."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "됐소, {name}. 이제 잘못돼도 내 탓은 아니오."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "준비 끝이오, {name}. 연설도 하고 싶지만 그러다 해 지겠소."
L["Look after that, {name}. It's the only one I brought for you."] = "잘 챙기시오, {name}. 그대 몫으로 가져온 건 그거 하나뿐이오."
L["Now we look the part, {name}. Let's go and be it."] = "이제 겉모습은 영웅이오, {name}. 가서 속까지 채웁시다."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff}도 새로 돌렸소, {name}. 나머진 운과 팔꿈치 싸움이오."
L["Right, {name}. If anyone has a plan, now's the time. No? Wonderful. Onward."] = "자, {name}. 작전 있는 사람? 없소? 훌륭하오. 전진!"
L["One each, {name}. Don't swap; they're fitted."] = "한 사람에 하나씩이오, {name}. 맞춤이니 바꿔 입지 마시오."
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "싸움을 먼저 거는 사람이, {name}, 나중에 무용담도 풀어야 하오."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "좋은 벗, 날 선 강철, 그리고 {buff}. 뭐가 더 필요하오, {name}?"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "내 눈에 보이는 데 있으시오, {name}. 못 찾으면 못 도와주오."
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "이게 전설이 되면, {name}, 내 대사도 한 줄 넣어 주시오. 딱 한 줄만."
L["Brace yourselves, {name}. And each other, if it comes to that."] = "다들 마음 단단히 먹으시오, {name}. 여차하면 서로 붙잡고."
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "고개 드시오, {name}. 앞에 뭐가 있든 이런 패거리는 처음 볼 거요."
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "부디 성한 몸으로 버티시오, {name}. 난 간단한 수리만 할 줄 아오."
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "자, {name}, 준비된 것 같소. 아니란 게 들통나기 전에 출발합시다."
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "길을 잃으면, {name}, 탐험 중인 거요. 탐험가를 혼낸 사람은 없소."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "고맙소, {name}. 답례를 창조하려 해도 나오는 건 물빵뿐이라."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "신세 졌소, {name}. 나중에 제대로 기록해 두겠소. 몇 장에 걸쳐."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "고맙소, {name}. 달라란에선 감사를 안 가르쳐서, 독학했소."
L["Kind of you, {name}. I'd say it went to my head, but that's my job."] = "고맙소, {name}. 콧대가 높아지겠구려. 원래 높아져야 할 건 지능인데."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "고맙소, {name}. 반사적으로 마법 차단할 뻔했소. 참길 잘했지."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "냉기 마법사도 녹겠구려, {name}. 고맙소."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "고맙소, {name}. 마법책에 적어 두겠소. 얼음 회오리와 점심 사이에."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "바로 갚겠소, {name}. 책방 앞을 지나면 몇 주씩 사라지는 몸이라."
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "도서관에서 이십 년, {name}, 그대 같은 사람은 어느 책에도 없었소."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "비전 이론상 공짜는 없다 했소, {name}. 이론이 틀렸구려. 고맙소."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "물론이오, {name}. 그리고 그래, 물도 달라는 거겠지."
L["As requested, {name}. Side effects may include footnotes."] = "요청하신 대로요, {name}. 부작용으로 각주가 생길 수 있소."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "당장 하겠소, {name}. 조심해서. 오늘만 점멸로 벽에 두 번 박았소."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "기꺼이, {name}. 지식은 나눠야 하오. 키린 토도 그러더군. 마지못해."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "물론이오, {name}. 천천히 시전하겠소. 손동작이 백미거든."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "물론이오, {name}. 숙제라 치시오. 내가 대신 해 뒀소."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "물론이오, {name}. 안토니다스께 배웠소. 몸 숙이는 법도 함께."
L["At once, {name}. Arcane, not fire. I did check. I always check. Nearly always."] = "당장 하겠소, {name}. 화염 말고 비전이오. 확인했소. 늘 하오. 거의 늘."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "물론이오, {name}. 이거 아니면 지맥 강의인데, 그대는 착하니 이걸로."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "마법사한테 청했구려, {name}. 주문은 즉시 시전, 설명은 긴 정신 집중이오."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "천 번은 시전해 봤소, {name}. 그중 구백구십 번은 멀쩡했소."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "물론이오, {name}. 가만히. 꼼지락대다 털이 복슬복슬해진 이들이 있었소."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "여기, {name}. 생각이 하나 남는데 둘 데가 없어서."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "받으시오, {name}. 빵도 얹고 싶지만, 마법으로 만든 빵은 아무 맛이 안 나오."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{name}, {buff} 받으시오. 차원문과 달리 공짜요."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "여기, {name}. 내가 가리키면 대개 양이 되는데, 오늘은 운 좋은 날이오."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "아무것도 안 태우고 안 얼렸소, {name}. 새 분야를 개척 중이오."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "받으시오, {name}. 연습 중이었는데 그대 머리가 제일 가까웠소."
L["Here, {name}. I'd have portalled it over, but you were standing right there."] = "여기, {name}. 차원문으로 보내려다 보니 바로 앞에 있더구려."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "옛날엔 왕들이 달라란에 돈 주고 맡기던 거요, {name}. 그대는 공짜요."
L["Take this, {name}. It wears off, unlike my last experiment."] = "받으시오, {name}. 효과가 사라지긴 하오. 지난번 실험과 달리."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "{name}, 달라란에서 배운 걸 몽땅 드리오. 과제 보고서만 빼고."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "여기, {name}. 비전 마법은 나눠야 좋소. 딴마음 먹기 전에."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "환기는 한세월 걸리오, {name}. 그러니 마나는 쓸 데에만 쓰오. 여기."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "여기, {name}. 돕지 않고 지나치는 마법사는 그냥 아주 높은 모자요."
L["Now that you're clever, {name}, stand between me and the angry things."] = "이제 똑똑해졌으니, {name}, 나와 화난 놈들 사이에 서 주시오."
L["For the record, {name}, I only blink away when it's tactically sound."] = "분명히 해 두겠소, {name}. 점멸로 빠지는 건 전술적 판단일 때뿐이오."
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "물은 끝나고 내가 쏘겠소, {name}. 제발 싸우는 도중엔 달라 마시오."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "머리는 맑아졌소, {name}. 화염, 냉기, 호들갑은 내가 맡지."
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "자, {name}. 내가 '얼음 회오리' 하면 뛰시오. '뛰어' 해도 뛰시오."
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "불덩이 작렬은 오래 걸리오, {name}. 그걸 끊는 놈은 내 원수요."
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "내가 얼음 방패를 써도, {name}, 겁에 얼어붙은 게 아니오. 일부러 언 거요."
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "귀환 차원문은 내가 맡겠소, {name}. 살아서 가는 건 다 같이 맡고."
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "싸우기 싫은 놈은 가리키시오, {name}. 차 마실 때쯤엔 양털이 돼 있을 거요."
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "놈들에게 눈보라를 내리겠소, {name}. 구경은 환영이오. 범위 밖에서."
L["If I start counting under my breath, {name}, that's mana, not nerves."] = "내가 중얼중얼 숫자를 세면, {name}, 긴장한 게 아니라 마나 세는 거요."
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "내가 조용해지면, {name}, 삐친 게 아니라 환기요. 대개는."
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "일이 틀어져도, {name}, 내겐 순간이동이 있소. 절대 안 쓰겠지만. 아마도."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "사려 깊구려, {name}. 빛은 장부를 적으니, 난 미리 갚아 두리다."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "고맙소, {name}. 빛께 좋게 말해 두리다. 빛이 내게 빚이 좀 있거든."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "고맙소, {name}. 작은 기적이구려. 기도도 안 했는데."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "고맙소, {name}. 사람을 향한 믿음이 돌아왔소. 잠깐 쉬고 있었을 뿐이오."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "고맙소, {name}. 오늘 밤 기도에 넣겠소. 꽤 앞쪽에."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "힐러가 받는 쪽에 설 일은 드물지, {name}. 이리 좋은 걸 잊고 있었소."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "고맙소, {name}. 덕분에 기도 하나 아꼈소. 늘 하나씩 모자라던 참이오."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "고맙소, {name}. 베풂에 대해 설교하려 했는데, 그대가 방금 몸소 했구려."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "고맙소, {name}. 그대를 위해 촛불을 켜겠소. 두 개. 오늘은 좀 과감하오."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "내 어둠의 면모도 웃고 있소, {name}. 얼굴이 없으니 내 말을 믿으시오."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "물론이오, {name}. 빛엔 퇴근이 없소. 슬프게도 나도 없고."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "바로 하리다, {name}. 기도는 보통 오래 걸리는데, 지름길을 찾았구려."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "물론이오, {name}. 빛은 구하는 이를 비추오. 난 조준만 할 뿐."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "기꺼이, {name}. 믿음은 산도 옮긴다지만, 난 작은 것부터 하겠소."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "물론이오, {name}. 고해는 별도 요금이오. 되도록 안 듣고 싶고."
L["Of course, {name}. Consider this sermon abridged. Very abridged. There, done."] = "물론이오, {name}. 설교는 요약본으로. 아주 짧게. 자, 끝."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "물론이오, {name}. 따스하게 빛나면 빛이오. 차갑게 빛나면 당장 말하시오."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "물론이오, {name}. 오래가게 기도하리다. 내가 위쪽에 연줄이 좀 있소."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "물론이오, {name}. 치유, 징벌, 장례까지 하오. 이건 그중 즐거운 일이오."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "축복을, {name}. 재채기는 안 했소? 그럼 다음 재채기 몫으로 미리."
L["Here, {name}. Think of it as a prayer that arrived early."] = "여기, {name}. 일찍 도착한 기도라 생각하시오."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "빛께서 이걸 전하라 하셨소, {name}. 대충 그런 뜻이었소."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "받으시오, {name}. 나중에 어색한 부활 장면을 서로 피할 수 있소."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "거저 드리오, {name}. 믿음은 공짜요. 이 로브는 아니었지만."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "여기, {name}. 걸어 다니는 작은 사원이라 생각하시오. 계단도 없소."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "낯선 이에게 축복을, {name}. 빛은 낯선 이란 없다고 우기지만."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "받으시오, {name}. 헌금 접시는 안 돌리오. 보시오, 빈손이오."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "여기, {name}. 설교하고 싶지만, 갈 길 바빠 보이는구려."
L["I do weddings, funerals and resurrections, {name}. Mostly the last. Here."] = "결혼식, 장례식, 부활 다 하오, {name}. 주로 마지막 거. 여기."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "여기, {name}. 우아하게 떠서 가고 싶지만, 공중 부양은 구경꾼이 몰려서."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "그대 차례요, {name}. 다들 제발, 내 일을 지루하게 만들어 주시오."
L["Everyone stay near me, {name}. The Light has a limited range."] = "다들 내 곁에 있으시오, {name}. 빛도 사정거리가 있소."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "됐소, {name}. 누가 쓰러지면 몹시 실망할 거요. 그다음에 살리고."
L["Done, {name}. I'll be at the back, praying loudly."] = "끝났소, {name}. 난 맨 뒤에서 큰 소리로 기도하겠소."
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "내가 절규하면, {name}, 주문이니 놈들이 도망갈 거요. 따라 뛰진 마시오."
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "내가 소실을 써도, {name}, 사라진 게 아니오. 몹시 재미없는 사람이 됐을 뿐."
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "보호막은 한 명에 하나씩이오, {name}. 그다음엔 영혼도 좀 누워야 하오."
L["Let's all come back from this the usual way, {name}: walking."] = "다들 늘 하던 대로 돌아옵시다, {name}. 두 발로 걸어서."
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "살리는 건 내가 하리다, {name}. 그대는 내 입에서 '내가 뭐랬소'만 안 나오게."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "이 파티를 두고 기도했소, {name}. 빛께서 '행운을 빈다' 하셨소. 그거라도 받겠소."
L["Thank you, {name}. I'd purr, but I'm not in the right shape for it."] = "고맙소, {name}. 가르랑거리고 싶지만 지금은 그럴 모습이 아니라서."
L["Thanks, {name}. My bear form sends a grateful grunt."] = "고맙소, {name}. 곰 모습의 내가 고맙다고 '크릉' 하는구려."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "신세 졌소, {name}. 표범 모습의 내가 토끼를 물어다 주겠다는 걸 말렸소."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "고맙소, {name}. 그대를 기려 나무를 심겠소. 백 년만 기다리시오."
L["Thank you, {name}. I'd send an owl with a note, but I'd have to be the owl."] = "고맙소, {name}. 부엉이 편에 편지를 보내고 싶지만, 그 부엉이가 나라서."
L["Kindly done, {name}. I felt that in my roots, and I haven't any at the moment."] = "고맙소, {name}. 뿌리까지 와닿았소. 지금은 뿌리도 없는데."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "자연은 결국 모든 걸 돌려주오, {name}. 난 좀 더 빠르지. 고맙소."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "나무껍질은 웬만한 건 다 막는데, {name}, 친절은 곧장 뚫고 들어오는구려."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "고맙소, {name}. 곰 모습이었으면 와락 끌어안았을 거요. 이 모습이라 다행이지."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "물론이오, {name}. 어느 모습에 손이 있었는지 잠깐 떠올려 보고."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "물론이오, {name}. 참나무처럼 가만히. 참나무는 그걸 기막히게 잘하오."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "기꺼이, {name}. 야생은 뭐든 나누오. 곰만 빼고."
L["Right away, {name}. Pardon the feathers; I've just come from being an owl."] = "바로 하리다, {name}. 깃털은 양해하시오. 방금까지 부엉이였소."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "물론이오, {name}. 자연은 주문을 안 받지만, 난 받소."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "기꺼이, {name}. 나무한테 부탁하면 일 년 걸리오. 드루이드는 지금 당장이고."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "물론이오, {name}. 균형이 그대 쪽으로 살짝 기울었소. 균형한텐 비밀이오."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "달려오려다 말았소, {name}. 치타가 덮치면 비명부터 지를 테니. 여기."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "물론이오, {name}. 야생은 청하는 누구에게나 너그럽소. 날파리만 빼고."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "에메랄드의 꿈에서 막 나온 거요, {name}. 하품하면 미안하오."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "받으시오, {name}. 자연이 베푸는 거고, 오늘 난 심부름꾼이오."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "이제 야생이 그대를 벗이라 부르오, {name}. 다행이오. 대개 이빨이 있으니."
L["I brought you flowers as well, {name}, but I was a stag at the time. Sorry."] = "꽃도 가져오려 했소, {name}. 사슴 모습이라 오다가 먹어 버렸지만."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "여기, {name}. 세나리우스께서도 그러길 바라셨을 거요. 아마 거의."
L["Nature wants you to have this, {name}. I'm its hands. Today I have hands."] = "자연이 이걸 그대에게 주라 하오, {name}. 난 그 손이오. 오늘은 손이 있거든."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "받으시오, {name}. 야생이 그대를 지켜보다가 쓸 만하다고 결론 냈소."
L["If a cat follows you today, {name}, it's only me checking this took."] = "오늘 고양이가 따라오면, {name}, 잘 들었나 확인하러 온 나일 뿐이오."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "받으시오, {name}. 달의 숲에서 안부를 전하오. 좀처럼 안 전하는 곳인데."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "자연은 잔혹하고, 아름답고, 축축하오, {name}. 이건 그중 둘에 도움이 되오."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "평소엔 낯선 이를 뿌리로 묶는 게 일이오, {name}. 이건 좋은 쪽 일이오."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "준비됐소, {name}? 무슨 일이 있어도 곰은 놀래지 마시오."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "됐소, {name}. 난 표범도, 곰도, 헤엄칠 일 생기면 바다표범도 되겠소."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "환생은 한 번뿐이오, {name}. 제발 누굴 살릴지 고르게 하지 마시오."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "대열을 좁히시오, {name}. 숲이 지켜보고 있소. 뿌리 깊이 응원하면서."
L["If I turn into a tree, {name}, things are going badly and I'm fixing them."] = "내가 나무로 변하면, {name}, 상황이 나쁜 거고 내가 수습 중인 거요."
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "정신 자극은 하나뿐이오, {name}. 제일 절박해 보이는 이에게 주겠소. 연기 금지."
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "내가 빛나며 부엉부엉 울면, {name}, 달빛야수요. 진지한 변신이오."
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "붐비면, {name}, 허리케인을 부르겠소. 모자 꽉 잡으시오."
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "우린 무리 지어 다니오, {name}. 좀 섞인 무리요. 가끔 하나는 곰이고."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "친절이라, {name}? 내가 가장 아끼는 미덕이오. 갑옷 광내기를 근소하게 앞서지."
L["For that, {name}, my best blessing. Not the second best. The best."] = "그 보답으로, {name}, 최고의 축복을. 두 번째 말고, 최고로."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "선행이 즉석에서 보답받는구려, {name}! 이런 순간이 참 좋소."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "고맙소, {name}. 내 맹세가 친절엔 보답하라 하오. 맹세 없어도 했겠지만."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "그대는 너그럽게 심판하겠소, {name}. 대개는 가혹하게 하는데. 고맙소."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "고맙소, {name}. 오라가 환해졌소. 감동하면 이러오."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "친절이라니, {name}! 방패에 새겨 두겠소. 찌그러진 자국 옆에."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "신세 졌소, {name}. 내 군마도 고맙다 하오. 그 녀석은 좀 내성적이라."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "선한 이를 지키겠노라 맹세했소, {name}. 방금 그대가 명단 맨 위로 올랐소."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "빛의 이름으로, {name}, 물론이오! 누가 부탁하길 고대했소."
L["You have my blessing, {name}. Literally, this time."] = "내 축복을 받으시오, {name}. 이번엔 말 그대로."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "물론이오, {name}. 원하면 무릎 꿇으시오. 강요는 않소. 기뻐는 하겠지만."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "기꺼이, {name}. 축복은 절대 안 모자라오. 마나는 가끔 모자라지만."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "물론이오, {name}. 가만히. 조준은 의롭지만 건틀릿이 둔하오."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "기꺼이, {name}. 돕는 건 맹세고, 번쩍이는 건 덤이오."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "물론이오, {name}. 바로 서서, 고개 들고, 받을 만한 표정을. 됐소. 딱 그거요."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "물론이오, {name}. 깡통한테 도움 청하는 사람이 얼마나 드문지 알면 놀랄 거요."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "물론이오, {name}. 축복 좀 고르겠소. 나도 아끼는 게 있어서."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "빛은 대가를 바라지 않소, {name}. 난 감사 인사 정도는 받지만."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "빛과 함께 가시오, {name}. 난 바로 뒤에서 철컹거리며 따라가겠소."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "축복은 공짜요, {name}. 설교는 봐 드리리다. 이번만."
L["There, {name}. It won't last forever, so be heroic while it does."] = "됐소, {name}. 영원하진 않으니, 효과 있을 때 영웅답게 구시오."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "허리를 펴시오, {name}. 빛이 함께 걷는데, 빛은 자세가 아주 바르오."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "받으시오, {name}. 망치도 드리고 싶지만, 이 녀석이 나한테 애착이 심하오."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "축복은 나누라고 있는 거요, {name}. 쌓아 두면 눈총받소. 나한테."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "악인에겐 정의를, 나머지에겐 축복을, {name}. 그대는 나머지요."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "받으시오, {name}. 내 성서가 나누라 하오. 말이 많은 책인데, 이 대목은 좋소."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "기사도는 죽지 않았소, {name}. 판금 갑옷을 입고 이걸 가져왔지."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "자부심을 가지시오, {name}. 너무 가지면 교만이지만, 조금은 괜찮소."
L["You're blessed, {name}. If I bubble later, it's strictly tactical."] = "축복을 내렸소, {name}. 나중에 내가 무적 쓰면 순전히 전술이오."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "버티시오, {name}. 우리에겐 빛이 있고, 내겐 아주 큰 망치가 있소."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "한 사람에 축복 하나씩이오, {name}. 빛은 너그럽지만 줄은 서야 하오."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "훌륭하오, {name}. 이제 아무도 날 똑바로 보지 마시오. 오늘 좀 눈부시오."
L["Stay inside my aura, {name}. It's warmer than it looks."] = "내 오라 안에 있으시오, {name}. 보기보다 따뜻하오."
L["If I stun something, {name}, hit it while it's thinking things over."] = "내가 뭔가를 기절시키면, {name}, 그놈이 생각 정리하는 동안 때리시오."
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "빛나는 바닥은 내 거요, {name}. 마음껏 밟으시오. 놈들만 무니까."
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "심판은 내가, {name}, 선고는 그대가. 아주 효율적인 법정이오."
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "내가 '빛을 위하여'를 외치면, {name}, 돌격이오. 아니면 기도. 대개 둘 다."
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "갑옷 광냈고, 망치 축복했고, {name}, 말은 삐쳤소. 준비 끝."
L["Righteous Fury's up, {name}. Everything wants to hit me now. That's the idea."] = "정의의 격노 켰소, {name}. 이제 다들 날 때리고 싶어 하오. 그게 노림수요."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "친절하구려, {name}. 내 임프도 고맙다 하오. 그놈은 거짓말이지만 난 진심이오."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "고맙소, {name}. 저주 안 걸린 걸 받아 본 게 얼마 만인지."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "고맙소, {name}. 지하 묘지에서 주운 게 아닌 걸로 갚겠소."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "고맙소, {name}. 공허방랑자한테 그대 곁에서 어른대지 말라 일러 뒀소."
L["Thank you, {name}. I'll tell my demons about you. They'll be baffled."] = "고맙소, {name}. 내 악마들한테 그대 얘기를 해 주겠소. 어리둥절해할 거요."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "피도, 계약도, 속박도 없이, {name}? 참 희한한 거래구려. 고맙소."
L["Thank you, {name}. I'll be nicer to my felhunter tonight, in your honour."] = "고맙소, {name}. 그대를 기려 오늘 밤엔 지옥사냥개한테 잘해 주겠소."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "사려 깊구려, {name}. 받은 건 다 돌려주오. 영혼만 빼고. 여기."
L["Of course, {name}. No soul required. This time."] = "물론이오, {name}. 영혼은 필요 없소. 이번엔."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "흑마법사한테 도움을 청하다니, {name}. 대담하군. 벌써 마음에 드오."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "물론이오, {name}. 임프가 돕겠다길래 말렸소. 우리 모두를 위해서."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "물론이오, {name}. 내 주문 중 잔치에서 써도 되는 건 이거 하나요."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "기꺼이, {name}. 선행 기록이 하나 늘었군. 어둠의 의회가 기겁하겠소."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "물론이오, {name}. 내가 든 책은 읽지 마시오. 그대를 위해서요."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "물론이오, {name}. 누가 보는 것 같소? 킬로그의 눈일 뿐이오. 가만히."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "물론이오, {name}. 저주는 무례한 이에게만 거오. 그대는 안전하오."
L["Yes, {name}, it's the one without screaming. Hold still."] = "그렇소, {name}. 비명 안 나오는 쪽 주문이오. 가만히."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "물론이오, {name}. 물 많은 데 가오? 안 묻겠소. 흑마법사는 원래 안 묻소."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "여기, {name}. 어디서 났는지는 묻지 마시오. 정말로."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "언젠가 호수에 빠지면, {name}, 날 좋게 떠올릴 거요."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "편히 숨 쉬시오, {name}. 물 따위 시시한 걸로 그대를 잃긴 싫소."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "여기, {name}. 영혼석도 필요하겠지만, 그건 긴 얘기가 될 거요."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "받으시오, {name}. 사제들이 인정하는 내 주문은 이거 하나요."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "받으시오, {name}. 어머니는 아직 내가 마법사인 줄 아오. 비밀로 해 주시오."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "여기, {name}. 초록색도 아니고, 속삭이지도 않고, 집까지 따라가지도 않소."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "여기, {name}. 좋은 일에 쓴 흑마법이오. 옛 스승께 꼭 일러 주시오. 질색할 거요."
L["Random acts of kindness, {name}. I'm trying them. The imp has complained."] = "이유 없는 친절이오, {name}. 요즘 시도 중인데, 임프가 불평하더군."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "여기, {name}. 내가 저주랑 공포뿐인 건 아니오. 대부분이긴 해도."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "내 마법서에도 친절 편이 있소, {name}. 짧지만 읽긴 읽었소."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "다들 준비됐소, {name}? 영혼은 멀쩡하고? 좋소. 계속 그렇게 갑시다."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "가까이 붙으시오, {name}. 맞는 건 공허방랑자, 공은 내가 챙기오."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "마음껏 헤엄치시오, {name}. 누가 떠내려가면 소환해 오겠소."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "지옥사냥개 쓰다듬어도 되오, {name}. 몸에 걸린 주문은 먼저 떼고."
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "내가 공포를 걸면, {name}, 쫓지 마시오. 돌아오오. 더 화나서."
L["If my health drops for no reason, {name}, it's Life Tap. Sorry, healer."] = "내 생명력이 괜히 줄면, {name}, 생명력 전환이오. 힐러, 미안하오."
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "생명석은 나중에 주겠소, {name}. 위급할 때 쓰시오. 간식 말고."
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "지옥의 불길 쓸 땐 비키시오, {name}. 나도 타오. 그게 비극이오."
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "내 임프는 원래 불타오, {name}. 우리 편이니 물 좀 그만 끼얹으시오."
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "하늘에서 초록 뭔가 떨어지면, {name}, 내 거요. 환호하시오."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "고맙소, {name}! 아, 시끄러웠소? 내 목소린 볼륨이 하나뿐이라."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "신세 졌소, {name}. 돌려줄 주문은 없지만, 진심 어린 외침은 있소."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "고맙소, {name}. 덕분에 분노가 두 배요. 좋은 쪽으로."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "고맙소, {name}. 내 바로 뒷자리를 내드리리다. 세상에서 제일 안전한 곳이오."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "고맙소, {name}. 친절에 마음이 물러지오. 다행히 갑옷은 두껍소."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "고맙소, {name}. 대장장이도 고맙다 하오. 그 집, 내 수리비로 지었거든."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "고맙소, {name}. 붕대라도 감아 주고 싶은데, 얄밉게도 멀쩡하구려."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "고맙소, {name}. 이걸 위해 감사 태세로 바꿨소. 거의 안 쓰는 태세요."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "마법을 받았구려, {name}. 둘 데를 모르겠으니 입고 다니겠소. 고맙소."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "빚지면 좀이 쑤시오, {name}. 좀이 쑤시면 아무 데나 돌진하고."
L["You want a shout, {name}? I was going to shout anyway."] = "외쳐 달라고, {name}? 어차피 외칠 참이었소."
L["Of course, {name}. Cover your ears; this is the only way I know how."] = "물론이오, {name}. 귀 막으시오. 난 이 방법밖에 모르오."
L["Right away, {name}. Stay in earshot. For me that's a generous distance."] = "당장 하리다, {name}. 들리는 데 있으시오. 내 목청이면 꽤 멀어도 되오."
L["Happily, {name}! Words aren't my strength. Volume is."] = "기꺼이, {name}! 말솜씨는 없소. 목청은 있지."
L["Right, {name}. Deep breath. Not you. Me."] = "좋소, {name}. 숨 크게 들이쉬고. 그대 말고. 나."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "기꺼이, {name}. 뭘 들어 올려 달라는 게 아닌 부탁은 오늘 처음이오."
L["Coming up, {name}. It's all in the diaphragm. And the anger. Mostly the anger."] = "바로 하리다, {name}. 비결은 횡격막이오. 그리고 분노. 주로 분노."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "물론이오, {name}. 다들 그만 좀 하라는 부탁만 하는데, 모처럼 좋구려."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "물론이오, {name}. 배우는 데 몇 년 걸렸소. 주로 나무한테 고함치면서."
L["Consider yourself shouted at, {name}. Affectionately."] = "방금 그대에게 외쳤소, {name}. 애정을 담아서."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "향도 기도도 없소, {name}. 그냥 내가 응원 삼아 소리칠 뿐."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "기운 내시오, {name}! 누가 귀찮게 하면 내가 돌진하리다."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "됐소, {name}! 주변에 아직 겁먹은 게 있다면 못 들은 거요."
L["Here, {name}, some courage. Warriors make it by yelling. Don't ask how."] = "여기 용기요, {name}. 전사는 고함쳐서 만드오. 어떻게냐고는 묻지 마시오."
L["Here, {name}. Something sharper than a whetstone: morale."] = "여기, {name}. 숫돌보다 날을 잘 세워 주는 것, 사기요."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "받으시오, {name}. 전사는 주문을 못 지니니, 서로를 짊어지오."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "여기, {name}. 뭔가 큰일에 뛰어들 얼굴이구려. 더 세게 뛰어드시오."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "여기, {name}. 마법은 없소. 그대를 아주 굳게 믿는 전사 하나뿐이오."
L["Take this, {name}. Trainers charge for it. I charge at things. Different job."] = "받으시오, {name}. 훈련사는 돈을 받고, 난 적을 들이받소. 업종이 다르오."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "여기, {name}. 누구랑 싸우든 전사가 보증했다고 전하시오."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "이건 그대 몫이오, {name}. 다음 건 그대 앞길 막는 놈 몫이고."
L["Listen up, {name}! That's it. That was the whole speech."] = "잘 들으시오, {name}! 끝. 이게 연설 전부요."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "위험이 어디 있소, {name}? 됐소, 내가 찾겠소. 얼굴부터 들이밀어서."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "좋소, {name}! 내가 먼저 가고, 제일 크게 외치고, 힐러는 아무도 못 건드리오."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "다들 화났소? 좋소. 전진이오, {name}. 내 휘두르는 반경은 조심하고."
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "난 좀 맞아야 쓸모가 생기오, {name}. 맞더라도 다들 당황하지 마시오."
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "붕대는 내 배낭에 있소, {name}. 매듭은 내가 묶었소. 절대 안 풀릴 거요."
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "자, {name}. 맞는 건 나, 공은 그대, 수리비는 반반이오."
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "내가 벌겋고 조용하면, {name}, 광전사의 격노요. 벌겋고 시끄러우면 평소고."
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "내 방패는 이보다 험한 꼴도 봤소, {name}. 내 얼굴도. 전진!"
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "더 예리한 머리를 드리오, {name}. 난 달라란에서 눈썹 한쪽을 대가로 치렀소."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "머리를 맑게 해 드렸소, {name}. 뭘 채울지는 그대 마음이오."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "머릿속이 웅웅거리오, {name}? 정상이오. 생각이 말대꾸하면 날 찾아오시오."
L["A little arcane for your thoughts, {name}. Keep the change."] = "그대 생각에 비전 한 스푼, {name}. 거스름돈은 넣어 두시오."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "총명함을 병에 담았소, {name}. 키린 토라면 병값까지 받았을 거요."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "머리가 좋아졌소, {name}. 주문에 쓰든 자물쇠든 수수께끼든, 참견 않겠소."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "보랏빛 성채 대출품이오, {name}. 연체하면 양이 되오."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "이제 함정은 알아볼 만큼 똑똑해졌소, {name}. 피하는 건 다른 주문이오."
L["There, {name}. Wiser already: look, you're standing further from me."] = "됐소, {name}. 벌써 현명해졌군. 보시오, 나한테서 멀찍이 서 있잖소."
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "내 주문 중 뭘 태워 먹은 적 없는 건 이거 하나요, {name}. 즐기시오."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "이제 노움 설명서도 이해될 거요, {name}. 그래도 따라 하진 마시오."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "인내란, {name}, '앞에 서시오'를 사제가 공손하게 하는 말이오."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "체력이 늘 때마다 내 다급한 기도가 하나씩 준다오, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "벌써 튼튼해졌소, {name}. 그렇다고 시험해 보진 마시오."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "신의 권능은 더 있소, {name}. '보호막', 급할 땐 '튀어'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "더 단단해졌소, {name}. 낙하도, 곰도, 잘못된 선택도 덜 아플 거요."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. '버텨' 두 글자면 될 걸 참 길게도 부르오."
L["A little more of you to go round, {name}. Spend it slowly."] = "그대가 조금 더 늘었소, {name}. 아껴 쓰시오."
L["Sturdier, {name}. Not invincible. I expect I'll be saying that again later."] = "튼튼해졌소, {name}. 무적은 아니오. 이 말, 이따 또 하게 되겠지."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "사실은 고집이오, {name}. 드워프는 타고나고, 우린 기도로 얻소."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "수리비 안 드는 유일한 갑옷이오, {name}. 대장장이들이 질색하오."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "정신 번쩍 들게 해 드렸소, {name}. 천상의 방식으로."
L["Like a good night's sleep, {name}, without all the lying down."] = "푹 자고 난 것 같을 거요, {name}. 누울 필요도 없이."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "정신 한 그릇 더, {name}. 빛은 할머니처럼 늘 더 먹으라 하오."
L["Keep your spirit where it is, {name}. The Spirit Healers are busy enough."] = "영혼은 제자리에 두시오, {name}. 영혼의 치유사는 안 그래도 바쁘오."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "기운 내시오, {name}. 이번엔 충고가 아니라 주문이오."
L["Recover faster, {name}: from fights, from long casts and from my jokes."] = "더 빨리 회복하시오, {name}. 전투에서도, 긴 시전에서도, 내 농담에서도."
L["A deep breath's worth of calm, {name}, without having to take one."] = "심호흡 한 번 한 만큼 차분해지오, {name}. 심호흡은 생략하고."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "빛이 불어넣는 새 기운이오, {name}. 말싸움에 낭비하진 마시오."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "암흑을 막아 줄 거요, {name}. 수법은 잘 아오. 몇 개 빌려 써 봤으니."
L["Should the Void call, {name}, you can now pretend you're out."] = "공허가 부르거든, {name}, 이제 부재중인 척하면 되오."
L["For when the dark gets personal, {name}. It usually does."] = "어둠이 사적으로 덤빌 때를 위해서요, {name}. 대개 그렇게 덤비오."
L["The shadows will have to knock first now, {name}."] = "이제 그림자도 노크부터 해야 할 거요, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "어둠이 여전히 물긴 하오, {name}. 이젠 꼭꼭 씹어야 하지만."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "어둠을 막는 안감이오, {name}. 망토인데 안쪽에 입는 거지."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "이제 저주가 미끄러져 나갈 거요, {name}. 광신도들이 서운해하겠구려."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "사제가 암흑을 공부하는 건 막기 위해서요, {name}. 대체로는."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "지하묘지, 광신도, 스칼로맨스용이오, {name}. 셋 다 어둠이 수다스럽지."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "우울함까진 못 막소, {name}. 그건 말동무가 있어야지. 여기 있잖소."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "야생의 징표요, {name}. 지나가면 사슴들이 뿔을 까딱여 인사할 거요."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "이끼 냄새가 살짝 날 거요, {name}. 효과가 있다는 증거지."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "야생의 징표요, {name}. 늑대가 물긴 하겠지만 미안해할 거요."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "야생이 보증하는 도장이오, {name}. 다람쥐들과도 협의했소."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "이제 그대 안에 야생이 좀 깃들었소, {name}. 울부짖고 싶어도 참으시오."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "질긴 가죽, 날카로운 발톱, 두툼한 털. 야생은 짐을 가볍고 꼼꼼히 싸오, {name}."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "하나하나 세나리우스가 서명한 거요, {name}. 뭐, 나무가 대필했지만."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "숲이 지은 갑옷이오, {name}. 철컹대지 않고 비 냄새가 나오."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "몇 초 만에 질긴 가죽이오, {name}. 수백 년 걸린 참나무들이 분개하오."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "야생에서 빌린 거요, {name}. 물어뜯긴 채로 돌려주진 마시오."
L["Anything that bites you now gets a mouthful, {name}."] = "이제 그대를 무는 놈은 입안 가득 가시를 머금을 거요, {name}."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "멧돼지더러 돌진하라 하시오, {name}. 후회와 가시를 잔뜩 안고 갈 테니."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "장미 같구려, {name}. 보기엔 곱지만 움켜쥐면 큰일 나오."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "가시요, {name}. 내가 직접 키웠으니 예쁘게 대해 주시오."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "입는 산울타리요, {name}. 단정히 다듬었소. 난 야만인이 아니니."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "자연은 다른 뺨을 내밀지 않소, {name}. 거기 가시를 기르지."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "랩터는 배우는 게 느리오, {name}. 이건 한 입씩 가르쳐 주지."
L["Prickly on the outside, {name}. What's inside is your own business."] = "겉은 까칠하게 해 드렸소, {name}. 속은 그대 사정이고."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "망토 조심하시오, {name}. 양털과 가시덤불은 늘 앙숙이오."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "왕의 축복이오, {name}. 왕관도, 옥좌도, 세금도 없소."
L["Long may you reign, {name}. For the next while, anyway."] = "{name} 만세! 효과가 끝날 때까지만."
L["A little more of everything, {name}. Kings never did settle for less."] = "모든 게 조금씩 더, {name}. 왕들은 원래 덜 받는 법이 없었지."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "왕의 축복이오, {name}. 나보다 나은 머리들이 썼던 거요. 못한 머리도 좀 있었고."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "모든 능력치를 조금씩 올렸소, {name}. 왕들은 분산 투자를 좋아하거든."
L["Crown not included, {name}. Everything else is, a little."] = "왕관은 별매요, {name}. 나머진 조금씩 다 들어 있소."
L["All of you, only more so, {name}. That's what they mean by the royal 'we'."] = "그대가 전부 한층 더, {name}. 이제 '짐'이라 하시오. 짐이 좀 늘었으니."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "왕족에게나 어울릴 축복이오, {name}. 손 흔드는 건 직접 하시오."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "더 세고, 똑똑하고, 튼튼하게, {name}. 왕에겐 신하가, 그대에겐 내가 있소."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "왕실 대접이오, {name}. 아첨꾼과 독 탄 술은 빼고."
L["Might doesn't make right, {name}, but it does help the argument."] = "힘이 정의는 아니오, {name}. 그래도 주먹은 법보다 가깝지."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "휘두르는 힘을 더해 드리오, {name}. 빛은 끝까지 휘두르는 걸 좋아하오."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "팔 힘이 세졌소, {name}. 부디 맞을 만한 놈에게만 쓰시오."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "힘의 축복이오, {name}. 그대도 놀라겠지만, 적은 훨씬 더 놀랄 거요."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "마음껏 휘두르시오, {name}. 잘되면 빛 덕, 못되면 조상 탓이오."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "더 세게 치시오, {name}. 적 말이오. 나 말고. 성기사는 절대 아니고."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "휘두를 때마다 힘이 실릴 거요, {name}. 빛은 그걸 신념이라 부르오."
L["Doors, crates and ogres will all give way easier now, {name}."] = "문짝, 궤짝, 오우거 모두 이제 쉽게 넘어갈 거요, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "무기가 가벼워진 느낌일 거요, {name}. 아니오. 그대가 거룩해진 거지."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "빛이 보태는 팔심이오, {name}. 쓸 데 쓰시오."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "지혜를 드리오, {name}. 내 몫도 조금 남겨 뒀소. 아주 조금."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "마나에 지혜를, {name}. 다른 지혜는 여전히 쓴맛을 봐야 생기오."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "이제 마나가 알아서 돌아오오, {name}. 삐졌다 풀린 고양이처럼."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "전투 사이에 물 마실 일이 줄 거요, {name}. 여관 주인들이 울겠구려."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "덜 마시고 더 시전하시오, {name}. 빛이 알려 주는 절약 비법이오."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "지혜의 축복이오, {name}. 본전 뽑는 유일한 축복이지."
L["Mana, {name}, not judgement. Judgement's a separate seal, and I'm keeping it."] = "드리는 건 마나지 심판이 아니오, {name}. 심판은 내가 내리오."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "지혜는 보통 나이 따라 오오, {name}. 이건 성기사 따라 오지. 더 빨리."
L["The blessing is wise, {name}. The decisions are still entirely ours."] = "축복은 지혜롭소, {name}. 선택은 여전히 우리 몫이지만."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "현명한 선택엔 지혜의 축복을, {name}. 성기사를 곁에 둔 선택 말이오."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "고요의 축복이오, {name}. 괴물들이 누구 탓이었는지 잊을 거요."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "구원의 축복이오, {name}. 이제 그대 문제는 남의 문제요."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "구원받았소, {name}. 영혼은 말고, 몸뚱이만."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "세게 치시오, {name}. 누가 돌아보면 모르는 척. 빛도 그럴 거요."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "이제 괴물들이 그대를 금세 잊을 거요, {name}. 오늘만은 칭찬이오."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "어서 치시오, {name}. 원망은 판금 제일 많이 입은 자가 듣소."
L["The art of being in the fight, {name}, and out of the argument."] = "싸움엔 끼되 시비엔 안 끼는 기술이오, {name}."
L["The Light's kindest alibi, {name}. Use it often."] = "빛이 서 주는 제일 다정한 알리바이요, {name}. 자주 쓰시오."
L["The Light will find you easier now, {name}. Try not to squint."] = "이제 빛이 그대를 더 쉽게 찾을 거요, {name}. 눈부셔도 찡그리지 마시오."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "이제 성스러운 빛이 더 잘 들을 거요, {name}. 증명할 일은 없게 해 주시오."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "치유가 잘 먹힐 거요, {name}. 빛은 협조적인 환자를 좋아하오."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "빛의 축복이오, {name}. 이제 살리기 쉬워졌소. 그럴 일은 없겠지만."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "이제 빛이 그대 집을 아오, {name}. 왕진 말고 마실만 오게 합시다."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "내 일을 덜어 주는 축복이오, {name}. 너그러우면서 게으르기까지."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "이제 성스러운 빛이 그대에게 착 붙소, {name}. 맞춤 휘장처럼."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "그대 고치는 값이 싸졌소, {name}. 청구서를 보낼 것도 아니지만."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "이제 공격을 막아 내면 빛이 대신 되갚아 주오, {name}. 뒤끝 있는 빛이지."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "이제 모든 타격이 약해질 거요, {name}. 불만은 빛에게 접수하시오."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "사원만큼 든든하오, {name}. 지붕 수리비는 없이."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "성역을 누리시오, {name}. 들고 다니니 훨씬 편하오."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "이제 모든 타격이 조금 덜 무례할 거요, {name}. 빛이 예절을 가르치거든."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "이 성역에선 아무도 그대를 못 쫓아내오, {name}. 등기부까지 확인했소."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "이제 오우거 몽둥이도 베개처럼 맞을 거요, {name}. 무겁고 성난 베개."
L["Instructions, {name}: hit things harder. There is no page two."] = "지시 사항이오, {name}. 더 세게 칠 것. 2쪽은 없소."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "칼 쥔 팔은 해결됐소, {name}. 나머지는 사제한테 가 보시오."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "전투의 외침이오, {name}. 주문이라기보단 아주 강력한 권유지."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "으아아아! 이건 그대한테 한 거요, {name}. 다른 이들은 엿들은 거고."
L["Priests pray, mages study, {name}. I clear my throat."] = "사제는 기도하고 마법사는 공부하오, {name}. 난 목을 가다듬지."
L["Words matter, {name}. Mostly the loud ones."] = "말에는 힘이 있소, {name}. 특히 큰 소리엔."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "외침은 몇 분 가오, {name}. 귀울림은 좀 더 가고."
L["There were words in that shout once, {name}. They slowed it down."] = "원래 그 외침엔 가사가 있었소, {name}. 느려서 뺐지."
L["A little breath from the damned, {name}. They weren't using it."] = "망자들의 숨을 좀 빌렸소, {name}. 어차피 안 쓰더군."
L["Unending Breath, {name}. The fish will have so many questions."] = "숨이 끝없이 이어질 거요, {name}. 물고기들이 물어볼 게 많겠구려."
L["Stay down as long as you like, {name}. Something else is holding its breath."] = "물속에 얼마든지 있으시오, {name}. 숨은 딴 녀석이 대신 참고 있으니."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "깊이 헤엄치시오, {name}. 멀록이 물으면 잠깐 놀러 왔다 하시오."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "공기가 딱히 공기가 아닌 곳에서 온 공기요, {name}. 그래도 들이쉬시오."
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "심해가 기다리오, {name}. 왜 '심해'인지는 알아내지 마시오."
L["Dropped something in a lake, {name}? Now's your chance."] = "호수에 도끼 빠뜨렸소, {name}? 산신령 말고 직접 건지시오."
L["No gills, {name}. I read the small print; gills were extra."] = "아가미는 없소, {name}. 약관 읽어 봤소. 아가미는 유료 옵션이더군."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "주고받는 걸 보면 결투하는 줄 알겠소, {name}. {gift} 고맙소."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} 받고 {buff} 드리오. 경매 수수료는 없소, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "선수를 뺏겼구려, {name}! 그대의 {gift}, 내 예의보다 빨랐소."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "{gift} 들어오고 {buff} 나가고. 아제로스 최고의 경제요."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, 날 위해? 줄 건 이것뿐이오, {name}. 그래도 진심이오."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "그대의 {gift}, 몸에 꼭 맞소, {name}. 치수라도 재 갔소?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "주문 조약을 맺읍시다, {name}. {gift} 대 {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! 벌써 키가 큰 기분이오. {buff}도 받으시오."
L["I was about to ask for {gift}, {name}. You read my mind."] = "막 {gift} 부탁하려던 참이오, {name}. 내 마음을 읽었구려."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "그대의 {gift}, 아직 톡톡 튀는구려, {name}. 나도 톡 쏘는 걸로 답하리다."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "다정하기도 하지, {name}. 이 {gift} 얘기, 여관에 다 퍼뜨리겠소. 두 번씩."
L["You cast {gift} first, {name}? My mother would despair of me."] = "그대가 먼저 {gift} 시전을? 어머니가 아시면 한숨 쉬시겠소, {name}."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "그대의 {gift}, 두고두고 기억하리다, {name}. 효과가 끝날 때까지는."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} 받고 {buff} 드리오. 공짜로. 어디선가 고블린이 우는구려."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "그대의 {gift}, 나의 {buff}. 이제 우리 못 말리겠구려."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "{gift} 고맙소, {name}. 효과 끝나기 전에 밥값은 하겠소."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "{gift} 보답으론 달 두 개라도 따 드리고 싶소만, {name}. 이걸로 참으시오."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "그대는 {gift}, 나는 {buff}. 이제 제대로 잔치구려."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift}, 그 뜻은 '행운을 비오'. {buff}, 그 뜻은 '그대도'."
L["Your {gift} came first; my {buff} tries twice as hard."] = "그대의 {gift}, 먼저 왔소. 내 {buff}, 두 배로 애쓰리다."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "누가 물으면 {buff} 먼저, {gift} 나중이오. 약조하오?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} 덕에 내 하루가 빛났소. {buff}, 그대 한 시간은 책임지리다."
L["Saved my {buff} for someone special. Then came {gift}."] = "특별한 이에게 주려고 {buff} 아껴 뒀소. 그런데 {gift} 들고 그대가 왔지."
L["Your {gift} went to my head; my {buff} goes to yours."] = "그대의 {gift}에 취했소. 이번엔 내 {buff}에 취해 보시오."
L["{gift} on me, {buff} on you. We wear each other's work."] = "내겐 {gift}, 그대에겐 {buff}. 서로의 솜씨를 걸치고 다니는구려."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift}도 {buff}도 사라지오. 친절은 남지. 뭐, 좀 더 오래."
L["You shared {gift}; I share {buff}. Next, snacks."] = "그대는 {gift}, 나는 {buff}. 다음엔 간식이오."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} 받을 땐 빈손이었소. 이젠 아니지. 자, {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}, 오늘 최고의 일이오. {buff}, 2등에 도전하오."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift}, 동상감이오. 난 조각가가 아니니, 대신 {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift} 받고 {buff} 드리고. 계속 이러면 줄 서겠구려."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift}, 친절했소. {buff}, 친절로 답하오. 지기 싫어서."
L["{gift} came like good news. {buff}, by return post."] = "{gift}, 반가운 편지 같았소. {buff}, 빠른우편 답장이오."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, 인사하시오. 이쪽은 {buff}. 둘이 사이좋게 지내시오."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "{gift} 주면 {buff} 드리리다. 아, 이미 냈구려."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift}에 {buff}까지. 여관에선 짜고 친 줄 알겠소."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! 방금 똑똑한 생각이 세 개나 났소, {name}. 이게 그중 하나요."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "{gift} 덕에, {name}, 드디어 내 메모를 알아보겠소. 고맙소."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "벌써 똑똑해졌소, {name}. 신세 진 걸 알 만큼은. 여기."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "그대의 {gift} 덕에 딱 맞는 말을 찾았소, {name}. '고맙소'."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift}! 고블린 계약서가 이해되오, {name}. 경악스럽구려."
L["{gift}! I finally get last week's mage joke, {name}. Thanks."] = "{gift}! 지난주 마법사 농담이 이제야 이해되오, {name}. 고맙소."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "그대의 {gift}, 말싸움 말고도 쓰겠소, {name}. 아마도."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "고맙소, {name}. 다음 주문엔 괜히 세 음절 더 붙이겠소. 뽐내려고."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? 이번만은 앞에 서 보겠소. 잠깐만."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "무릎, 팔꿈치, 자존심까지 다 튼튼해졌소, {name}. 고맙소."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "이제 날 쳐 보시오, {name}. 아니, 치진 마시오. 그래도 버틸 거요. 고맙소."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "이제 거의 안 깨지오, {name}. '거의'는 시험하지 맙시다. 고맙소."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift}! 우리 힐러가 감사 편지를 써야겠소, {name}. 난 이걸로 갚고."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "오늘 안 드는 멍은 다, {name}, 그대의 {gift} 덕이오."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "이젠 오우거랑 말싸움에 져도 살아남겠소, {name}. 고맙소."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "고맙소, {name}. 성벽이 된 기분이오. 감사할 줄 아는 성벽."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "고맙소, {name}. 다음에 날 들이받는 멧돼지는 오후 내내 고생하겠소."
L["{gift}! My spirits are lifted, {name}. Literally, it seems."] = "{gift}! 정신이 고양되오, {name}. 말 그대로 정신이."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "두 배로 차분하고 절반만 투덜대게 됐소, {name}. 고맙소."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "그대의 {gift}에 노래할 뻔했소, {name}. 이걸로 대신하오. 그게 자비지."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}, {name}? 벌써 세 명이나 용서했소. 고맙소."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "바닥나기 직전이었소, {name}. 그대의 {gift}, 따끈한 밥에 아랫목 같았소."
L["I've stopped counting mana between fights, {name}. Thank you."] = "전투 사이에 마나 셀 일이 없어졌소, {name}. 고맙소."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "정신이 가득 찼소, {name}. 나머지 몸도 고마워하오."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "덕분에 암흑이 안 통하오, {name}. 속삭임들이 잔뜩 성났소."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "이제 어둠은 못 들어오오, {name}. 대신 밝은 걸 내보내리다."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift}! 그림자송곳니 성채는 그림자나 끼고 살라지, {name}. 고맙소."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "다음 어둠의 화살은 실망하겠구려, {name}. 고맙소."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "그대의 {gift} 믿고 오늘 밤 그늘숲에 가 보겠소, {name}. 아니면 내일."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! 방금 다람쥐가 내게 고개를 까딱했소, {name}. 이건 그대 몫이오."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "가죽은 질기고 감각은 예리해졌소, {name}. 도토리 줍고 싶은 걸 참아야겠구려."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "온몸에 잎이 돋는 기분이오, {name}. 고맙소. 나무껍질 떨어지면 미안하오."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "그대의 {gift} 덕에 낯가죽이 두꺼워졌소, {name}. 화살도 욕도 끄떡없소."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift}! 새가 내 머리에 둥지를 틀려 했소, {name}. 고마운 거겠지?"
L["Half a tree now, {name}, the better half. Thanks for the {gift}."] = "이제 반쯤 나무요, {name}. 좋은 쪽 반. {gift} 고맙소."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "고맙소, {name}. 빗속에 서서 자라고 싶소. 참겠지만."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "이제 불모의 땅 가시덤불도 날 보면 망설이겠소, {name}. 고맙소."
L["Thank you, {name}. Even my boots feel like they've put down roots."] = "고맙소, {name}. 장화까지 뿌리를 내린 기분이오."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! 오늘은 아무도 날 못 안겠구려. 대신 이거라도."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "덕분에 가시가 돋쳤소, {name}. 평소엔 말에만 있었는데."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "그대의 {gift}, {name}! 다음 코볼트, 내 양초에 손대 보라지."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift}! 이제 난 할 말 많은 덤불이오, {name}. 고맙소."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "고맙소, {name}. 날 무는 놈은 반사당하고 반성하겠구려."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift}, 그대가 주는 거요, {name}? 왕조는 안 세우도록 조심하리다."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "모든 게 조금씩 나아졌소, {name}. 왕들은 이런 기분이었구려. 어쩐지."
L["Your {gift}! My first decree, {name}: thank you."] = "그대의 {gift}! 첫 칙령이오, {name}. '고맙소.'"
L["{gift} on a commoner, {name}? I'll try to look regal."] = "평민에게 {gift}, {name}? 위엄 있어 보이도록 애써 보겠소."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "그대의 {gift} 덕에 작은 왕국 하나는 다스리겠소, {name}. 서부 몰락지대쯤."
L["Thank you, {name}. I'm a little better at everything now, gratitude included."] = "고맙소, {name}. 이제 모든 게 조금씩 나아졌소. 감사 인사까지."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "벌써 팔 힘이 세졌소, {name}. 아무도 안 안도록 조심하리다. 고맙소."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "{gift} 덕에 코도도 들겠소, {name}. 안 들겠지만, 고맙소."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "그대의 {gift}에 내 팔이 아주 기고만장하오, {name}. 고맙소."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift}! 가시덤불 골짜기 때부터 씨름한 병뚜껑을 땄소, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "고맙소, {name}. 다음 일격은 그대에게 바치오. 찌그러진 자국까지."
L["{gift} from you, {name}, and my first wise act is this."] = "그대의 {gift}, 고맙소, {name}. 지혜로워진 내 첫 행동이 바로 이거요."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "벌써 지혜로워졌소, {name}. 친절을 알아볼 만큼은."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "내 마나가 {gift} 고맙다 하오, {name}. 우리 중 제일 수줍은 녀석이라."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "그대의 {gift}, 쓰는 것보다 빨리 채워 주오, {name}. 거의."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "그대의 {gift}, {name}. 마나는 돌아오고, 훈수 두고 싶어지오."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! 괴물들은 날 바로 잊었소, {name}. 난 안 잊겠지만."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "이제 아무도 나랑 안 싸우려 하오, {name}. 참 좋구려. 고맙소."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift}! 몇 분째 아무도 날 안 노려보오, {name}. 고맙소."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift}! 용의 잔칫상 밑 생쥐 꼴이오, {name}. 안 들키고 배부르지."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "{gift} 덕에 전투에선 그저 소문일 뿐이오, {name}."
L["The Light finds me easier now, {name}. It says thank you, and so do I."] = "이제 빛이 날 더 쉽게 찾소, {name}. 빛도 고맙다 하고, 나도 고맙소."
L["Easier to heal now, thanks to you, {name}. My healer thanks you too."] = "덕분에 치유가 잘 먹히오, {name}. 우리 힐러도 고맙다 하오."
L["With your {gift}, {name}, every heal feels like a homecoming."] = "그대의 {gift} 덕에, {name}, 치유받을 때마다 집에 온 기분이오."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift}! 이제 빛하고 말 놓는 사이요, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "{gift} 덕에 빛이 내 말부터 듣소, {name}. 소리칠 필요도 없지."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "이제 맞아도 덜 아프오, {name}. 멍들도 고맙다 하고, 나도 고맙소."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "덕분에 타격이 한결 부드럽소, {name}. 놈들도 알아채게 해 주리다."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "그대의 {gift}에 모든 타격이 푹신하오, {name}. 온몸을 솜으로 누볐소."
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift}! 이제 날 치면 빛이 제 일처럼 발끈하오, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "그대의 {gift} 덕에 반은 요새, 반은 예배당이 됐소, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "그대가 내게 소리쳤는데, {name}, 이렇게 힘이 난 적은 처음이오. 여기."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "귀는 멍멍하고 팔 힘은 두 배요, {name}. 고맙소!"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}, {name}! 이가 다 울렸소. 좋은 쪽으로."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "그대의 {gift}엔 조용히 답하리다, {name}. 누군가는 그래야지."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "그대의 {gift}에 벽으로 돌진할 뻔했소, {name}. 자, 차분하게."
L["All Azeroth heard your {gift}, {name}. Only I get to thank you."] = "그대의 {gift}, 아제로스가 다 들었소, {name}. 감사는 나만 하지만."
L["Your shout's still ringing, {name}, and so is my sword arm. Thank you."] = "그대 외침이 아직 귀에 쟁쟁하오, {name}. 칼 든 팔은 근질거리고. 고맙소."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "무슨 말인지 못 알아들었소, {name}. 팔은 알아들었지만. 고맙소!"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "고맙소, {name}. 다음 놈은 두 배로 세게 치고 그대 탓을 하겠소."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "물속에서 숨을 쉴 수 있소, {name}! 쓸 일은 없을지 몰라도, 고맙소."
L["Lungs like a murloc, thanks to you, {name}. Mrgl. Sorry. Thank you."] = "덕분에 폐활량이 멀록급이오, {name}. 므르글. 아, 미안. 고맙소."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "{gift} 덕에 가라앉은 난파선을 다 털겠소, {name}. 반은 그대 몫이오."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "{gift}, 그 공기가 어디서 오는지는 안 묻겠소, {name}. 그냥, 고맙소."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "{gift} 덕에 로다미어 호수를 건너겠소, {name}. 물밑으로."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "이렇게 자꾸 만나면 곤란하오, {name}. 아니, 곤란할 거 없구려."
L["Again, {name}? Splendid. I've been practising since last time."] = "또 만났소, {name}? 좋구려. 지난번 이후로 연습해 뒀소."
L["You again, {name}? People will start saying we're friends."] = "또 그대요, {name}? 사람들이 우리 친구라고 수군대겠소."
L["Same face, same spell, {name}. I do love a tradition."] = "같은 얼굴, 같은 주문이오, {name}. 난 전통이 참 좋소."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "한 판 더, {name}? 점수를 세고 있는데, 둘 다 이기는 중이오."
L["Ah, {name}! My favourite repeat customer."] = "아, {name}! 내가 제일 아끼는 단골손님."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "자꾸 길이 겹치는구려, {name}. 옷깃만 스쳐도 인연이라던데."
L["Hello again, {name}. Do stop me if you've heard this one."] = "또 만났구려, {name}. 이 얘기 들은 적 있으면 말리시오."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "그대가 다시 올까 봐 좀 남겨 뒀소, {name}. 내 감이 좋았구려."
L["Back already, {name}? I'm starting to think you like me."] = "벌써 돌아왔소, {name}? 날 좋아하는 게 아닌가 싶구려."
L["Again, {name}? At this rate I'll have to learn your middle name."] = "또 그대요, {name}? 이러다 족보까지 외우겠소."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "한 번은 친절, 두 번은 버릇이오, {name}. 버릇은 여든까지 간다지."
L["Encore, {name}. The crowd demanded it. The crowd is you."] = "앙코르요, {name}. 관객이 원했거든. 관객은 그대요."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "한 번만 더 하면, {name}, 길드 헌장에 서명해야겠소."
L["I'd know your footsteps anywhere now, {name}. Handy; I'm terrible with faces."] = "이젠 발소리만 들어도 알겠소, {name}. 다행이오. 얼굴은 영 못 외우니."
L["Us again, {name}. The world must be running out of other people."] = "또 우리구려, {name}. 세상에 사람이 동났나 보오."
L["Last time went so well, {name}, I've changed nothing. Not even my expression."] = "지난번이 워낙 좋아서, {name}, 하나도 안 바꿨소. 표정까지."
L["I know where you stand now, {name}. Literally; I've aimed at it before."] = "그대 입장은 잘 아오, {name}. 말 그대로. 거기다 주문을 겨눠 봤으니."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "아, 그대였구려, {name}. 다행이오. 낯선 이한테 주는 건 질색이라."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, 이쯤 되면 재료 주머니를 같이 써야겠소."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "내일 이 시간에, {name}? 난 {buff}, 그대는 그대만 가져오시오."
L["I've lost count, {name}, and I've decided that's a compliment."] = "몇 번째인지 세다 놓쳤소, {name}. 칭찬으로 받아 주시오."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "이대로 가면, {name}, 음유시인들이 우리 얘기로 아주 지루한 노래를 쓰겠소."
L["I could do this one in my sleep by now, {name}. I may have."] = "이젠 자면서도 하겠소, {name}. 이미 그랬을지도."
L["{name}, the usual? Of course the usual. It's always the usual."] = "{name}, 늘 먹던 걸로? 물론 늘 먹던 걸로. 언제나 늘 먹던 거지."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "이쯤이면 우리만의 비밀 악수가 있어야 하오, {name}. 다음엔 만들어 봅시다."
L["By now, {name}, I think we've built a small economy between us."] = "이쯤 되니, {name}, 우리 둘이 작은 경제를 이룬 것 같소."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "이제 오랜 친구요, {name}. 아니, 타이밍 기막힌 오랜 지인이랄까."
L["Let the record show: {name} and I, undefeated at being prepared."] = "기록해 두시오. {name}하고 나, 준비성 부문 무패."
L["My spellbook opens to your page on its own now, {name}."] = "이제 내 주문책이 알아서 그대 쪽을 펼치오, {name}."
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "그대가 안 나타나면, {name}, 경비병한테 실종 신고하겠소."
L["So much has passed between us, {name}, I've lost track of whose is whose."] = "주고받은 게 하도 많아, {name}, 뭐가 누구 건지 모르겠소."
L["We're a local landmark now, {name}. Travellers give directions by us."] = "이제 우린 동네 명소요, {name}. 나그네들이 우릴 보고 길을 찾소."
L["The innkeepers ask after you now when I come in alone, {name}."] = "이제 나 혼자 가면 여관 주인들이 그대 안부를 묻소, {name}."
L["The guards wave us both through now, {name}. They assume we're a set."] = "이제 경비병들이 우릴 같이 들여보내오, {name}. 세트인 줄 아나 보오."
L["Folk ask which of us taught the other, {name}. I say you, to be polite."] = "누가 누굴 가르쳤냐고들 묻소, {name}. 예의상 그대라고 하오."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "이게 끊기면 서운할 거요, {name}. 그러니 끊지 맙시다."
L["Somewhere a tavern has heard all about us, {name}. Mostly from me."] = "어느 선술집에선 우리 얘기를 다 안다오, {name}. 대부분 내가 떠들었지."
L["I hum a little when I see you coming now, {name}. Nobody else gets the hum."] = "이젠 그대가 오면 콧노래가 나오오, {name}. 콧노래는 그대 전용이오."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "튼튼한 성벽, 따뜻한 침대, 이제 {buff}까지. 호강하는구려, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "경비병이 지켜 주겠지만, {name}, 난 꼼꼼한 게 좋소."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "조심하시오, {name}. 마을에서 이리 유능해 보이면 다들 부탁하러 올 거요."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "근방에 괴물은 없소, {name}. 그래도 여기 요리는 모를 일이오."
L["For the crowds, {name}. In town, they're the real danger."] = "인파 대비용이오, {name}. 도시에선 그게 진짜 위험이지."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "편히 쉬시오, {name}. 이걸로 오늘 선행은 했으니 한잔하러 가겠소."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "도시에도 가끔 용이 들이닥친다오, {name}. 조심해서 나쁠 건 없지."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "여기서 하는 게 낫소, {name}. 밖에선 아무도 가만있질 않으니."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "소매치기 조심하시오, {name}. 이것만은 못 털어 가오."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "도시 규칙이오, {name}. 칼 뽑기 금지, 주문 던지기 금지. 이건 허용이오."
L["Nothing to fight here but the queue at the mailbox, {name}. Take this anyway."] = "여기서 싸울 거라곤 우체통 앞 줄뿐이오, {name}. 그래도 받으시오."
L["For the walk to the bank, {name}. It's always further than it looks."] = "은행 가는 길에 쓰시오, {name}. 늘 보기보다 멀지."
L["Put that on before the banker sees, {name}. They'll want to charge interest."] = "은행원이 보기 전에 얼른 두르시오, {name}. 이자 붙이려 들 테니."
L["The watch keeps the peace, {name}. I just keep you in one piece."] = "경비대는 치안을 지키고, {name}, 난 그대 치아를 지키오."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "계단용이오, {name}. 여길 지은 자는 지름길을 몰랐나 보오."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "도시에선 뭐든 값이 붙소, {name}. 이건 상인들 눈을 피했지."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "'친구'라 부르는 자한텐 아무것도 사지 마시오, {name}. 나만 빼고."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "여기선 뭐든 그대를 먹으려 드오, {name}. 이제 더 큰 포크가 필요할 거요."
L["No guards for miles, {name}, and the boars know it. Take this."] = "근방에 경비병 하나 없소, {name}. 멧돼지들도 그걸 알지. 받으시오."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "여긴 우리랑 짐승들뿐이오, {name}. 우리가 더 센 쪽이 됩시다."
L["If a bear asks, {name}, you were like this when I found you."] = "곰이 물으면, {name}, 원래부터 이랬다고 하시오."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "늑대들이 그대를 노리던데, {name}. 이러면 좀 망설이겠지."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "험한 땅이오, {name}. 좋은 뜻만 들고 맞서긴 곤란하오."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "지도, 물통, {buff}. 이제 제대로 길을 잃어도 되오, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "야영지는 한참 멀었소, {name}. 들고 다니는 지붕이라 생각하시오."
L["Murlocs, raptors, bandits, rain, {name}. This handles one of those. You pick."] = "멀록, 랩터, 산적, 비, {name}. 이건 그중 하나만 막소. 골라 보시오."
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "제일 가까운 여관은 하루 거리요, {name}. 이빨 달린 놈은 더 가깝고."
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "다음 마을까진 언덕 둘에 늪 하나요, {name}. 늪은 할 말이 많소."
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "야영은 조심히 하시오, {name}. 좋은 빈터엔 다 주인이 있소. 발톱 달린."
L["Out here the only law is the food chain, {name}. You've just moved up a rung."] = "여기 법은 먹이사슬뿐이오, {name}. 방금 한 칸 올라갔소."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "뭔가 따라오오, {name}. 아마 멧돼지겠지. 아닐 때를 대비해서요."
L["Stay on the road, {name}. The road has guards. Some of the time."] = "길로만 다니시오, {name}. 길엔 경비병이 있소. 가끔은."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "비가 오고, 늑대도 오오, {name}. 둘 중 하나는 내 소관이오."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "이 안 어딘가서 악당이 연설 연습 중이오, {name}. 가서 끊어 줍시다."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "이 끝에 뭐가 기다리든, {name}, 후회하게 만들어 줍시다."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "여기선 아무도 살아 나가지 못한다더군, {name}. 무례하게 반박해 줍시다."
L["Our host had years to prepare, {name}. We have {buff}."] = "이곳 주인은 몇 년을 준비했소, {name}. 우리에겐 {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "뒷문 달린 던전은 없소, {name}. 대신 이걸 받으시오."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "어두운 복도, 낡은 함정, 더 고약한 성질머리. 적어도 그대는 준비됐소, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "나중에 추도사를 바치느니, {name}, 지금 이걸 드리는 게 낫소."
L["There's treasure in here, {name}, and something very large sat on it."] = "여기 보물이 있소, {name}. 아주 큰 뭔가가 깔고 앉아 있지만."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "뒤에서 문이 쾅 닫히면, {name}, 그게 전통이오. 이것부터 받으시오."
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "순찰병을 조심하시오, {name}. 영원히 같은 길만 돌아 심사가 뒤틀렸소."
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "이곳 주인은, {name}, 해골 장식엔 돈을 펑펑 쓰고 등불엔 한 푼도 안 썼구려."
L["The last lot through here were never seen again, {name}. They lacked this."] = "먼저 온 일행은 다신 못 봤다더군, {name}. 이게 없었던 거요."
L["Check the ceiling, {name}. In places like this, something always drops in."] = "천장을 살피시오, {name}. 이런 곳엔 늘 위에서 불청객이 떨어지오."
L["If we meet a talking skull, {name}, let me do the talking."] = "말하는 해골이 나오면, {name}, 말은 내가 하리다."
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "벽이 속삭이거든 대꾸 마시오, {name}. 받아 주면 버릇 되오."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "빛나는 건 만지지 말고, 딸깍하는 건 당기지 마시오, {name}. 이걸 걸치고."
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "여기선 뭉쳐 다니시오, {name}. 메아리도 원한도 멀리 퍼지오."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "깃발, 탑, 무덤, {name}. 뭘 두고 싸우든, 이걸 받으시오."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "이기든 지든, {name}, 준비 없이 갔단 말은 안 나올 거요."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "무덤은 바로 저기요, {name}. 둘 다 들르지 맙시다."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "명예가 걸렸소, {name}. 깃발도 걸렸고. 주로 깃발이."
L["Stay with the group, {name}. Lone heroes end up in the other side's songs."] = "무리와 함께 있으시오, {name}. 홀로 나선 영웅은 적의 노래에 나오오."
L["Our banner looks better with you under it, {name}. Stand tall."] = "우리 깃발은 그대가 그 아래 설 때 더 멋지오, {name}. 당당히 서시오."
L["Keep your head down and your colours up, {name}."] = "머리는 낮게, 깃발은 높게, {name}."
L["Hold the line, {name}. The songs are always about the ones who stood."] = "전선을 지키시오, {name}. 노래에 남는 건 늘 버틴 자들이오."
L["The spirit healer knows my face by now, {name}. Let's keep yours a stranger."] = "영혼의 치유사와 난 이미 구면이오, {name}. 그대는 영영 초면으로 남으시오."
L["Drums are for courage, {name}. This is for everything else."] = "용기는 북이 채우고, {name}, 나머진 이게 채우오."
L["The quartermaster counts marks, {name}. I count friends. You're on my list."] = "병참장교는 징표를 세지만, {name}, 난 벗을 세오. 그대도 들어 있소."
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "깃발을 위해 싸우되, {name}, 승전가 부르러 돌아오시오. 난 음치요."
L["Early bird, {name}? Here's something better than a worm."] = "일찍 일어난 새구려, {name}. 벌레보다 나은 걸 드리리다."
L["Good morning, {name}. Consider this your first cup of something strong."] = "좋은 아침이오, {name}. 오늘의 첫 진한 차 한 잔이라 치시오."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "일찍 나섰구려, {name}. 하루가 아직 꼬일 틈도 없었소."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "점심도 안 됐는데, {name}, 벌써 나보다 준비가 잘됐구려."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "좋은 아침, {name}. 어디선가 괴물들은 아직 하품 중이오."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "새 하루에 새 {buff}, {name}. 둘 다 허투루 쓰지 맙시다."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "해와 함께 기상이라니, {name}. 잘난 척은. 옜소, 해한텐 안 주는 거요."
L["Rise and shine, {name}. Well, rise. The shining can wait till after breakfast."] = "일어나서 빛나시오, {name}. 아니, 일어나기만. 빛나는 건 아침 먹고."
L["Dawn, {name}. Everything's golden and nobody's shouted yet. Let's enjoy it."] = "새벽이오, {name}. 온통 금빛이고 아직 아무도 고함을 안 질렀소. 즐깁시다."
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "영웅 노릇하기엔 이르다고, {name}? 무슨 소리. 영웅담은 점심 전이 제맛이오."
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "새들이 노래하는구려, {name}. 아직 바깥 꼴을 못 봐서 그렇지."
L["Morning, {name}. Here's the first good deed of the day. It's all downhill now."] = "좋은 아침, {name}. 오늘의 첫 선행이오. 여기서부턴 내리막이오."
L["Still yawning, {name}? This works faster than tea."] = "아직 하품 중이오, {name}? 이건 차보다 빨리 듣소."
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "이르구려, {name}. 새벽 순찰대가 우릴 실성한 사람 보듯 하오."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "이 늦은 시간에, {name}? 밤은 낮보다 굶주렸소. 받으시오."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "잘 시간이 지났소, {name}. 분별 있는 이들은 다 잠들었으니, 남은 건 우리요."
L["Can't sleep either, {name}? Then let's be well-protected insomniacs."] = "그대도 잠이 안 오오, {name}? 그럼 든든하게 무장한 불면증 환자가 됩시다."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "어둠을 조심하시오, {name}. 밖엔 나처럼 친절한 것만 있지 않소."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "늦었소, {name}. 해가 우릴 기억해 낼 때까진 이걸로 버티시오."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "깨어 있는 건 부엉이와 우리뿐이오, {name}. 부엉이한텐 {buff} 없소."
L["The inns have locked up, {name}. This is the only thing still being served."] = "여관은 다 문을 닫았소, {name}. 아직 영업 중인 건 이것뿐이오."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "괴담 들을 시간이오, {name}. 하나쯤 진짜일지 모르니 받으시오."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "촛불은 낮고 별은 높소, {name}. 작은 친절에 좋은 시간이오."
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "고요한 시간이오, {name}. 삐걱 소리마다 매복 같지만, 대개는 아니오."
L["This late, {name}, even the guards are talking to themselves."] = "이 시간엔, {name}, 경비병들도 혼잣말을 하오."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "무덤에서 뭔가 기어 나오는 시간이오, {name}. 이걸 받고 걸음을 재촉하시오."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "내일이면 왜 밤을 새웠나 싶을 거요, {name}. 이게 그럴싸한 이유 하나요."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "알아보는 건 같은 직업이지, {name}. 제대로 챙기는 것도 같은 직업이고."
L["From one of our trade to another, {name}. No need to check my work."] = "동업자끼리 드리는 거요, {name}. 검수는 필요 없소."
L["Professional courtesy, {name}. We don't charge each other."] = "동업자 예우요, {name}. 우리끼린 돈 안 받소."
L["Two of a kind, {name}. Between us we could write the manual."] = "같은 부류구려, {name}. 둘이면 교본도 쓰겠소."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "그리 놀라지 마시오, {name}. 같은 스승한테 배웠나 보오."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "그대 솜씨를 평하고 싶지만, {name}, 내 것도 똑같이 생겼소."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "다른 이들한텐 비밀이오, {name}. 우리 직업이 사실 최고요."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "우릴 보시오, {name}. 전문가 둘이 쉬워 보이게 하는 중이오. 사실 안 쉽잖소?"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "동업자끼리 털어놓자면, {name}, 나도 절반은 어떻게 되는 건지 모르오."
L["Same trade, {name}, so you know exactly how hard that was. Let's say very."] = "같은 업이니 알 거요, {name}, 이게 얼마나 어려운지. 아주 어렵다 해 둡시다."
L["If anyone asks, {name}, we trained each other."] = "누가 물으면, {name}, 우리가 서로 가르쳤다 합시다."
L["Calling to calling, {name}. We should compare notes. Mine are mostly doodles."] = "같은 길 걷는 사이니, {name}, 필기 좀 맞춰 봅시다. 내 건 거의 낙서지만."
L["Colleague, {name}. We should found a society. Dues, minutes, a very small hat."] = "동업자여, {name}, 협회를 세웁시다. 회비, 회의록, 아주 작은 모자까지."
L["We'd be twins, {name}, if I were a touch better-looking."] = "내가 조금만 더 잘생겼으면, {name}, 우린 쌍둥이였을 거요."
L["I'd shout some encouragement, {name}, but you do that far better."] = "응원의 함성을 질러 주고 싶지만, {name}, 그건 그대가 훨씬 잘하지."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "늘 하던 대로 돌진하시오, {name}. 이제 내 마음이 좀 놓이겠소."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "맨 먼저 뛰어드는 이에게, {name}. 누군가는 해야 하고, 그게 난 아니지."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "우리 대신 맞아 주는 그대요, {name}. 이 정도는 해야지."
L["Go on, {name}, charge. I'll be right behind you. Quite a long way behind."] = "어서 돌진하시오, {name}. 바로 뒤따르겠소. 꽤 멀찍이 뒤에서."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "모든 문제를 때려서 푸는 그대에게, {name}. 대개 통하더군."
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "악수하고 싶지만, {name}, 두 손 다 날붙이를 쥐고 있구려."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "산더미 같은 갑옷에 작은 도움 하나, {name}. 안에 들어갈 틈이 있으려나."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "곧 뭔가 거대한 놈에게 돌진할 테지, {name}. 난 그놈이 지게 거들 뿐이오."
L["Save the bubble for later, {name}. This one's from me."] = "무적은 아껴 두시오, {name}. 이번 건 내가 드리오."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "종일 남들만 축복하잖소, {name}. 이번엔 거꾸로 드리오."
L["The Light already likes you, {name}. Consider this a second opinion."] = "빛은 이미 그대를 아끼오, {name}. 이건 두 번째 소견이라 치시오."
L["Even the Light's own champion needs a hand now and then, {name}."] = "빛의 용사에게도 가끔 도움은 필요하오, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "축복을 돌려 달라 하고 싶지만, {name}, 그럼 하루가 다 가겠소."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "망치와 양심을 함께 짊어진 그대에게, {name}. 짐이 무겁겠소."
L["Don't thank the Light for this one, {name}. It had the day off. This was me."] = "이번엔 빛에 감사하지 마시오, {name}. 빛은 오늘 쉬는 날이오. 내가 했소."
L["No need to kneel, {name}. I know it's a habit."] = "무릎 꿇을 필요 없소, {name}. 버릇인 건 알지만."
L["One for you, {name}, and a pat on the head for your companion."] = "그대에게 하나, {name}. 그대 야수에겐 머리 쓰다듬기 한 번."
L["You watch everyone's back from range, {name}. I've got yours."] = "멀리서 모두의 등을 지켜 주잖소, {name}. 그대 등은 내가 맡지."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "적에겐 사냥꾼의 징표, 그대에겐 {buff}, {name}. 훨씬 낫지."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "잘 조준하시오, {name}. 그래도 달려들면 우리 쪽으로 뛰어오시오."
L["Your pet was looking at me hopefully, {name}. This is for you; tell it sorry."] = "그대 야수가 날 애타게 보던데, {name}. 이건 그대 몫이오. 미안하다 전해 주오."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "이번엔 야수 몫은 없소, {name}. 벌써 내 샌드위치를 셋이나 먹었으니."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "화살을 가져올까 했소, {name}. 어떤 걸 좋아하는지 몰라서."
L["You can track anything, {name}, but you never saw this one coming."] = "무엇이든 추적하는 그대도, {name}, 이건 못 봤겠지."
L["For the one I never see coming, {name}. Meant as the highest praise."] = "언제 오는지 도통 안 보이는 이에게, {name}. 최고의 칭찬이오."
L["Quick, {name}, before you vanish again."] = "얼른, {name}. 또 사라지기 전에."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "칼날엔 독, 몸엔 {buff}. 아주 철저하구려, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "주머니에 슬쩍 넣어 두려 했소, {name}. 하지만 알아채겠지. 늘 알아채니까."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "잠긴 상자는 다 여는 그대에게, {name}. 이건 처음부터 열려 있소."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "그대가 오는 건 아무도 못 보지, {name}. 이젠 보는 순간 더 큰일이겠구려."
L["Take this, {name}. Very discreet. It even walks quietly."] = "받으시오, {name}. 아주 은밀한 거요. 발소리도 안 나오."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "포장하려다 말았소, {name}. 어차피 매듭을 따 버릴 테니."
L["Keep this one, {name}. You don't even have to steal it."] = "이건 가지시오, {name}. 훔칠 필요도 없소."
L["For once, {name}, somebody's looking after the priest."] = "이번만큼은, {name}, 누군가 사제를 챙기는구려."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "기도는 우리 몫으로 아껴 두시오, {name}. 이 기도는 이미 응답받았소."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "빛이든 암흑이든, {name}, 묻지 않겠소. 둘 다 어울리니."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "이 전투 끝나면 좀 앉으시오, {name}. 고마운 환자가 내리는 명령이오."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "그대 덕에 우리가 버티잖소, {name}. 그중 조금을 돌려드리오."
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "우리 모두 곁에 무릎 꿇어 준 그대요, {name}. 잠시 허리 펴시오."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "기도 없이 오는 거요, {name}. 오늘 기도는 충분히 했잖소."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "이건 머릿속 목소리가 딸려 오지 않소, {name}. 개운하지 않소?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "칠흑의 기사단은 호의를 청하지 않지, {name}. 그래도 드리겠소."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "온기 좀 드리오, {name}. 추위를 못 느끼는 건 알지만, 마음이오."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "죽음에서 돌아왔으니, {name}, 다시 안 가게 거드는 게 도리지."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "룬, 역병, 냉기, {name}. 이것도 받으시오. 세트 완성이오."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "해골 말에 말대꾸하는 검이라, {name}. 평범한 것도 하나 드리오."
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "죽음의 손아귀는 넣어 두시오, {name}. 제 발로 가던 참이오."
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "산 자의 땅에 돌아온 걸 환영하오, {name}. 뭐, 대충 그쪽 방향으로."
L["The elements look after you, {name}, but they don't make house calls."] = "정령들이 그대를 돌보지만, {name}, 왕진은 안 오잖소."
L["Tell the spirits I said hello, {name}. They never write back."] = "영혼들에게 안부 전해 주시오, {name}. 내 편지엔 답장이 없어서."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "날 기려 토템 하나 세워 주시오, {name}. 작은 걸로. 난 겸손하니."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "대지, 화염, 물, 바람, 그리고 나, {name}. 다섯 중 제일 약한 건 인정하오."
L["Totems up already, {name}? Then this goes next to them. Don't plant it."] = "벌써 토템을 세웠소, {name}? 그럼 이건 그 옆에. 심지는 마시오."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "바람 편에 보낼 수도 있었소, {name}. 헌데 바람은 바람기가 있어서. 난 한결같소."
L["Tell the earth I said thanks, {name}. It's done so much for my feet."] = "대지에 고맙다고 전해 주시오, {name}. 내 발이 신세를 많이 졌소."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "영혼들이 그대가 받을 만하다더군, {name}. 묻지도 않았는데 먼저 말하더이다."
L["A gift for a mage, {name}? Like bringing water to... well, you."] = "마법사에게 선물이라, {name}? 물빵 가게에 물 사 가는 격이구려."
L["You solve most problems with sheep, {name}. This covers the rest."] = "대부분의 문제는 양으로 해결하잖소, {name}. 나머진 이걸로."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "어떤 곤경이든 순간이동으로 빠지겠지만, {name}, 이건 빠지기 전 몫이오."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "똑똑한 그대에게, {name}. 감사 인사로 날 양으로 만들진 마시오."
L["Blink wherever you like, {name}. This comes too."] = "어디로 점멸하든, {name}, 이건 따라가오."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "곧 지를 불에서 한 발 물러서시오, {name}. 자, 이거."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "늘 물빵으로 우릴 먹여 살리잖소, {name}. 이번엔 그대가 챙김받을 차례요."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "차원문 삯이 비싸잖소, {name}. 이건 다음 차원문 계약금이오."
L["Entirely demon-free, {name}. I checked."] = "악마 성분 0%요, {name}. 직접 확인했소."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "그대 임프가 샘낼지도 모르오, {name}. 넉넉하다고 전해 주시오."
L["No contract, no fine print, {name}. Just a gift."] = "계약서도, 깨알 같은 약관도 없소, {name}. 그냥 선물이오."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "생명석 나눠 주는 그대에게, {name}. 고맙단 말 한 번 못 들었을 테니."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "여기, {name}. 나중에 우리 소환해 주면 퉁칩시다."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "그대 공허방랑자더러 그만 맴돌라 하시오, {name}. 난 좋은 뜻이오."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "그대 지옥사냥개는 마법을 먹지, {name}. 이건 먹이지 마시오. 그대 거요."
L["Keep your imp downwind, {name}, and we'll call it even."] = "임프는 바람 아래쪽에 두시오, {name}. 그럼 퉁칩시다."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "종일 영혼 주머니를 메고 다니니, {name}, 어깨가 이걸 원하겠구려."
L["Roll wherever you like, {name}. This rolls with you."] = "어디로 구르든, {name}, 이것도 같이 구르오."
L["Brew first or fight first, {name}? Either way, take this."] = "술이 먼저요, 싸움이 먼저요, {name}? 어느 쪽이든 받으시오."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "그대에게 내면의 평화를, {name}. 이게 지속되는 동안은 바깥 평화도."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "기의 흐름엔 도움이 좀 필요하오, {name}. 어느 수도사가 그러더군."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "차고, 뒤집고, 구르고, {name}. 난 여기 서서 이것만 하겠소."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "술 안 쏟고 공중제비 도는 법을 가르쳐 주면, {name}, 퉁칩시다."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "차, 명상, 그리고 이것, {name}. 좋은 하루의 세 기둥이오."
L["Tell the bear this is for them too, {name}."] = "곰에게도 전해 주시오, {name}. 이건 곰 몫이기도 하다고."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "가만있으시오, {name}. 치타일 땐 한 번도 못 잡았으니."
L["Nature looks after you already, {name}. Today she sent me to help."] = "이미 자연이 그대를 돌보지만, {name}, 오늘은 날 보냈구려."
L["Whatever shape you're in next, {name}, this goes with you."] = "다음에 무슨 모습이 되든, {name}, 이건 함께 가오."
L["For the forest's friend, {name}. Give my regards to the trees."] = "숲의 벗에게, {name}. 나무들에게 안부 전해 주시오."
L["It's the least we can do for somebody who is also a bear, {name}."] = "곰이기도 한 이에게, {name}, 이 정도는 해야지."
L["I'd hand it to the cat, {name}, but it would only knock it off the table."] = "표범한테 주면, {name}, 고양이답게 탁자에서 툭 떨어뜨리겠지."
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "달빛야수에게 안부 전해 주시오, {name}. 늘 화들짝 놀란 얼굴이던데."
L["You were not prepared, {name}. Now you are."] = "'아직 준비가 안 됐다'더니, {name}. 이제 됐소."
L["Ten thousand years in a cell, {name}. You've earned a small kindness."] = "감옥에서 만 년이라, {name}. 작은 친절쯤은 받을 만하오."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "군단과 싸우려 많은 걸 버렸잖소, {name}. 조금 돌려드리오."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "맨 먼저 뛰어드는 그대에게, {name}. 착지는 부디 우리 편 쪽에."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "지옥 마력과 분노, {name}, 이제 친절도 조금. 균형이 맞을 거요."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "올 줄 알았냐 묻고 싶지만, {name}, 그대는 눈 가리고도 다 보지."
L["You can see souls, {name}. Mine's the one being generous."] = "영혼이 보이잖소, {name}. 지금 베푸는 게 내 영혼이오."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "일리단은 누구의 도움도 받지 않았지, {name}. 그대가 스승보다 현명하오."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "안엔 악마, 밖엔 군단이라, {name}. 그대 편도 하나쯤은 있어야지."
L["For you, {name}. Please don't breathe on it."] = "그대에게, {name}. 부디 입김은 불지 마시오."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "용에게 도움을 주다니, {name}. 손주들한테 두고두고 자랑하겠소."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "위상들이 그대를 세상에 보냈소, {name}. 난 세상을 좀 다정하게 만드는 중이오."
L["Take to the skies after this, {name}. I'll wave from down here."] = "이걸 받고 하늘로 날아오르시오, {name}. 난 여기서 손 흔들겠소."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "용이 우리 편이라, {name}. 이렇게 안심하고 베풀어 본 적이 없소."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "용에게 선물이라, {name}. 보통은 금을 바치고 살아 나가길 빌 텐데."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "옆 마을까지 태워 줄 수 있는 그대에게, {name}. 부탁 아니오. 눈치 주는 거지."
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "용을 몇 번 만나 봤소, {name}. 도망 안 친 건 그대가 처음이오."
L["For the world's youngest ancient, {name}."] = "세상에서 제일 어린 고룡에게, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "마법사에게 {buff}, {name}. 도서관에 책 빌려주는 격이오."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "마법사끼리 약속합시다, {name}. 서로 물 달라고는 하지 않기로."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "마법사가 둘이오, {name}. 어디든 차원문을 열 수 있는데도 둘 다 지각하지."
L["A mage for a mage, {name}. The Kirin Tor would call this peer review."] = "마법사가 마법사에게, {name}. 키린 토라면 동료 심사라 부를 거요."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "마법사가 마법사에게 마법을, {name}. 둘 다 필요했던 척합시다."
L["Neither of us will admit which spells we still read off the page, {name}."] = "아직 책 보고 외는 주문이 뭔지는, {name}, 둘 다 입 다뭅시다."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "마법사 하나는 학자, {name}, 둘이면 논쟁이오. 이게 내 첫 논거요."
L["We both know this spell backwards, {name}. Luckily I cast it forwards."] = "이 주문은 둘 다 눈 감고도 외지, {name}. 다행히 난 눈 뜨고 시전했소."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "마나를 더 드리오, {name}. 화염구 한 방에 다 쓰진 마시오."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "사제끼리 묻겠소, {name}. 축복하는 이는 누가 축복하오? 오늘은 나요."
L["Between us priests, {name}, we'll both pretend the tank listens."] = "사제끼리니까, {name}, 탱커가 말 듣는다고 서로 믿는 척합시다."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "사제가 사제를 챙기다니, {name}. 왠지 금기 같구려."
L["Two priests, {name}. Twice the praying and half the panic."] = "사제가 둘이오, {name}. 기도는 두 배, 호들갑은 절반."
L["Two priests, {name}. If it goes wrong, we're the last ones standing. Kneeling."] = "사제가 둘이오, {name}. 일이 틀어져도 끝까지 서 있는 건 우리요. 무릎 꿇고."
L["Your prayers can take a break, {name}. Mine are covering the shift."] = "그대 기도는 좀 쉬어도 되오, {name}. 내 기도가 대타를 뛰니."
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "설교를 해 드리려다, {name}, 관뒀소. 다 들어 봤을 테니. 아니, 해 봤을 테니."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "서약도 같고 시린 무릎도 같소, {name}. 그대 무릎에 이걸 드리오."
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "내가 쓰러지면 그대가, 그대가 쓰러지면 내가 기도문을 알지, {name}. 둘 다 버팁시다."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "드루이드가 둘이오, {name}. 세나리온 의회라면 정족수를 채웠다 하겠소."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "드루이드끼리니까, {name}. 곰이든 표범이든 머리에 붙은 잎사귀로 알아보오."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "변신술사끼리 드리오, {name}. 이건 어느 모습에나 맞소."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "악수는 생략하오, {name}. 드루이드 둘인데 둘 다 손 있는 모습이 아니라서."
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "우리 둘이면, {name}, 어떤 문제에든 맞는 모습이 있소. 대개 곰이지만."
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "드루이드 동지요, {name}? 그럼 알겠구려. 나무들이 그대 온다고 일러 줬소."
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "나중에 표범이 된 나를 보거든, {name}, 모르는 척해 주시오. 체면이 있지."
L["Paladin to paladin, {name}: I won't mention the bubble if you don't."] = "성기사끼리니까, {name}. 무적 얘긴 서로 꺼내지 맙시다."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "성기사에게 축복을, {name}. 이제 둘 다 못 봐줄 만큼 눈부시오."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "성기사가 둘이오, {name}. 어디선가 사제가 조용히 한숨 돌리겠구려."
L["One of us should be humble about this, {name}. Neither of us will be."] = "둘 중 하나는 겸손해야 할 텐데, {name}. 둘 다 안 그럴 거요."
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "맹세는 같고 광택은 다르구려, {name}. 그대 게 더 번쩍이오. 다 봤소."
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "우리 둘이면, {name}, 대성당도 밝히겠소. 아니면 아주 성스러운 작은 방이나."
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "판금 갑옷 둘이 살금살금 가오, {name}. 철컹철컹. 아무도 모를 거요."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "그대 성서와 내 성서가 이번엔 뜻이 같소, {name}. 드문 일이지."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "흑마법사끼리니까, {name}. 임프끼리는 떼어 놓읍시다. 수다가 심하오."
L["Fellow warlock, {name}? Then you know this one's actually harmless. Honestly."] = "흑마법사 동지요, {name}? 그럼 이게 진짜 무해한 거 알겠구려. 정말이오."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "흑마법사가 둘이오, {name}. 남들 앞에서 영혼의 조각 개수는 비교하지 맙시다."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "우리끼리 얘기지만, {name}, 일은 악마들이 다 하지. 이건 내가 직접 하오."
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "흑마법사 동지구려, {name}. 예의 바르게 지냅시다. 그대가 뭘 소환하는지 봤으니."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "흑마법사가 주는 주문이오, {name}. 저주 들었나 살펴보시오. 나라면 그러겠소."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "흑마법사 동지여, {name}. 이게 어디서 났냐고 안 물을 유일한 분이구려."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "흑마법사 둘에 선행 하나라, {name}. 불타는 군단이 길길이 뛰겠소."
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "술 한잔 소환해 드리고 싶지만, {name}, 소환하면 뭐가 딸려 오는지 알잖소."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "전사가 둘이오, {name}. 어디선가 힐러가 한숨 쉬었소."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "전사끼리 규칙이오, {name}. 먼저 뛰어든 자가 술 사기. 내가 사겠소."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "외침엔 외침으로, {name}. 같이 이 동네 귀를 먹게 합시다."
L["No plan, {name}? Perfect. We'll get along."] = "작전이 없다고, {name}? 완벽하오. 우린 잘 맞겠구려."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "전사란, {name}, 외침도 주문이라 믿는 유일한 족속이오. 그리고 우리가 옳소."
L["One warrior to another, {name}: whoever's hit first gets angriest. Lucky them."] = "전사끼리니 알겠지, {name}. 먼저 맞는 쪽이 분노가 제일 차오르오. 부럽구려."
L["You know this one, {name}. You've probably shouted it at me already."] = "이건 그대도 알지, {name}. 아마 벌써 내게 외쳐 줬을 거요."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "교관님이 뿌듯해하실 거요, {name}. 고함을 치시겠지만, 뿌듯해는 하실 거요."
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "전사 동지요? 그럼 그대도 대장장이랑 말 트고 지내겠구려, {name}."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "채울 마나는 없지만, {name}, 이건 그냥 똑똑하게 서 있을 거요. 나처럼."
L["Intellect on a warrior, {name}. The Kirin Tor would call it research."] = "전사에게 지능이라, {name}. 키린 토라면 연구라 부르겠지."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "벗에게 줄 주문은 이거 하나뿐이오, {name}. 분노든 마나든 받으시오."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "그대 분노엔 필요 없겠지만, {name}, 그냥 지나치면 결례 같아서."
L["No mana, I know, {name}. Use it on locks. They're only puzzles with opinions."] = "마나가 없는 건 아오, {name}. 자물쇠에 쓰시오. 고집 센 수수께끼일 뿐이니."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "마나용이긴 하오, {name}. 쓸 데를 찾겠지. 도적은 늘 찾아내니."
L["Energy, not mana, I know, {name}. Call it a very clever lockpick."] = "마나가 아니라 기력인 건 아오, {name}. 아주 영리한 자물쇠 따개라 치시오."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "암, {name}, 말만 하면 되지. 가만있어 보게!"
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "옜네, {name}. 쓰러지지 말라고 주는 작은 선물일세."
L["My thanks, {name}. Allow me to return the kindness."] = "고맙소, {name}. 이 호의에 보답하겠소."
L["Of course, {name}. Stand fast a moment."] = "물론이오, {name}. 잠시 그대로 서 계시오."
L["The road ahead is long, {name}. Take this with you."] = "갈 길이 멀다오, {name}. 이것을 챙겨 가시오."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. 그대의 호의를 돌려드리리다."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. 별빛 아래 사뿐히 걷기를."
L["The Light rewards kindness, {name}, and so shall I."] = "빛이 친절에 보답하듯, 저도 보답하겠습니다, {name}."
L["Of course, {name}. May the Naaru guide your steps."] = "물론입니다, {name}. 나루께서 그대의 길을 인도하시길."
L["The Light is with you, {name}. Go in peace."] = "빛이 그대와 함께합니다, {name}. 평안히 가십시오."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "신세 졌소, {name}. 길니아스는 은혜를 잊지 않소."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! 이걸 품고 전장으로 가라!"
L["The Earth Mother sees your kindness, {name}. I return it."] = "대지모신께서 그대의 친절을 보셨소, {name}. 나도 보답하리다."
L["Of course, {name}. Stand tall and be at peace."] = "여부가 있겠소, {name}. 곧게 서서 마음을 편히 가지시오."
L["Walk with the Earth Mother, {name}."] = "대지모신과 함께 걷기를, {name}."
L["Sure ting, {name}. Hold still now."] = "암, 그렇고말고, {name}. 가만있으라고."
L["Da loa be watchin' over ya, {name}."] = "로아가 널 지켜보고 있다고, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "그 예의, 칭찬할 만하군요, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. 태양이 그대를 인도하기를."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "그 아량, 기억하지요, {name}. 수라마르는 벗을 잊지 않으니."
L["Thank you, {name}! The caravan always repays a kindness."] = "고마워요, {name}님! 대상단은 받은 친절을 꼭 갚아요."
L["Every traveller needs something for the road, {name}."] = "나그네라면 길에서 쓸 게 필요하죠, {name}님."
L["Of course, {name}. Patience, and it is done."] = "물론이지, {name}. 조금만 참으면 다 된다네."
L["Take this, {name}. Even a dragon needs allies."] = "이걸 받으시오, {name}. 용에게도 동료는 필요하오."
L["Thank you, {name}. The Alliance looks after its own."] = "고맙소, {name}. 얼라이언스는 동료를 챙기는 법이오."
L["Of course, {name}. Allies help each other."] = "당연하오, {name}. 동맹은 서로 돕는 법이오."
L["For the Alliance, {name}! Stay strong out there."] = "얼라이언스를 위하여, {name}! 굳건히 버티시오."
L["Strength and honour, {name}. Your kindness is repaid."] = "힘과 명예를, {name}. 받은 호의는 갚았소."
L["Consider it done, {name}. For the Horde."] = "맡겨 두시오, {name}. 호드를 위하여."
L["For the Horde, {name}! Go with strength."] = "호드를 위하여, {name}! 힘이 함께하기를."
L["Thank you, {name}. Good hearts are found everywhere."] = "고맙소, {name}. 선한 마음은 어디에나 있구려."
L["Gladly, {name}, whatever banner you fly."] = "기꺼이, {name}. 그대가 어느 깃발 아래 있든."
L["Friends can come from any side, {name}."] = "벗은 어느 편에서든 오는 법이오, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "무사히 가시오, {name}. {buff}도 챙겨 가시고."
L["Returning a favour:"] = "호의에 보답할 때:"
L["Answering a request:"] = "요청에 응할 때:"
L["In your group:"] = "파티원일 때:"
L["Offering unasked:"] = "먼저 줄 때:"
L["Returning a favour of %s:"] = "받은 %s 버프에 보답할 때:"
L["Meeting somebody a third time:"] = "같은 사람을 세 번째 만났을 때:"
L["(nothing -- speech off, or no usable lines)"] = "(없음 -- 말하기 꺼짐 또는 쓸 수 있는 대사 없음)"
