L["Below %d%% only favours and requests are offered; the rest come back at %d%%."] = "마나가 %d%% 미만이면 보답과 요청만 뜨고, 나머지는 마나가 %d%%로 회복되면 다시 뜹니다."
L["Fantasy (general)"] = "판타지 (일반)"
L["loaded the %s lines."] = "%s 대사를 불러왔습니다."
L["In combat: changes here apply once the fight ends."] = "전투 중: 여기서 바꾼 설정은 전투가 끝나면 적용됩니다."
L["Thanks and speech"] = "감사 인사와 말하기"
L["/thank people who buff me"] = "나에게 버프를 준 사람에게 /thank 감정 표현"
L["Everyone near you sees it; never in combat or instances, and at most once per person every five minutes."] = "주변 사람 모두에게 보입니다. 전투 중이나 인스턴스에서는 하지 않으며, 한 사람에게 5분에 한 번까지만 합니다."
L["Say a line when I buff someone"] = "버프를 줄 때 한마디 하기"
L["Where to say it"] = "말할 채널"
L["Whisper them sends it only to the person you buff."] = "상대에게 귓속말을 고르면 버프를 받는 사람에게만 보냅니다."
L["Say"] = "일반 대화"
L["Whisper them"] = "상대에게 귓속말"
L["Emote"] = "감정 표현"
L["Party"] = "파티"
L["Raid"] = "공격대"
L["Yell"] = "외치기"
L["Only when I buff someone back"] = "버프로 보답할 때만"
L["Off, you also speak when you buff someone first."] = "끄면 내가 먼저 버프를 줄 때도 말합니다."
L["Tick Say a line to choose what you say."] = "할 말을 고르려면 한마디 하기 옵션을 켜세요."
